/* Dialectica thinkers: one per person, grouped by tradition, in English and Chinese. Edit freely, then run `node scripts/check-data.mjs`. */
window.DIALECTICA = window.DIALECTICA || {};
window.DIALECTICA.thinkers = [
  {"id":"laozi","tradition":"eastasia","born":-571,"died":-471,"life":{"en":"traditionally 6th c. BCE","zh":"传为公元前6世纪"},"name":{"en":"Laozi","zh":"老子"},"role":{"en":"Legendary sage credited with the Daodejing","zh":"传说中的圣人，相传著有《道德经》"},"idea":{"en":"The Daodejing teaches that the Dao is nameless and acts by not acting, and that the sage ruler stays low like water and lets things take their course. Whether a single author named Laozi existed is doubted; the text probably grew over the 4th–3rd centuries BCE.","zh":"《道德经》主张道不可名、无为而无不为，圣人治国应像水一样处下，让万物自然运行。是否真有一位名叫老子的作者颇受怀疑，该书可能在公元前4至前3世纪逐渐成形。"},"schools":["daoism"],"works":[{"t":{"en":"Daodejing","zh":"《道德经》"},"y":-300}],"wiki":"Laozi","c":"Zhang Lu-Laozi Riding an Ox.jpg","portrait":{"w":600,"h":1094,"v":"daba4508cb","author":"Zhang Lu","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Zhang_Lu-Laozi_Riding_an_Ox.jpg"},"focus":"50% 40%"},
  {"id":"confucius","tradition":"eastasia","born":-551,"died":-479,"life":{"en":"551–479 BCE (traditional)","zh":"公元前551–前479年（传统纪年）"},"name":{"en":"Confucius","zh":"孔子"},"role":{"en":"Teacher from Lu who sought to revive the Zhou way","zh":"鲁国教师，致力于复兴周代之道"},"idea":{"en":"Taught that anyone can become an exemplary person (junzi) by cultivating humaneness and practising ritual, beginning with respect within the family. He wrote no treatise; his sayings were collected by his disciples’ circles in the Analects.","zh":"主张人人都能通过修养仁德、践行礼仪成为君子，而这要从家庭中的孝悌开始。他没有留下专著，其言论由弟子及再传弟子辑为《论语》。"},"schools":["confucianism"],"works":[{"t":{"en":"Analects (compiled by disciples)","zh":"《论语》（弟子辑录）"},"y":-400}],"wiki":"Confucius","c":"Confucius Tang Dynasty.jpg","portrait":{"w":350,"h":640,"v":"c4a73d0dd5","author":"Wu Daozi, 685-758, Tang Dynasty.","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Confucius_Tang_Dynasty.jpg"}},
  {"id":"mozi","tradition":"eastasia","born":-470,"died":-391,"life":{"en":"c. 470–391 BCE","zh":"约公元前470–前391年"},"name":{"en":"Mozi","zh":"墨子"},"role":{"en":"Founder of Mohism and critic of Confucian partiality","zh":"墨家创始人，批评儒家的差等之爱"},"idea":{"en":"Argued for impartial care and against offensive war and costly rituals, judging every doctrine by its benefit to the people; he is often called China’s first consequentialist.","zh":"主张兼爱，反对侵略战争与奢靡礼制，以是否有利于百姓衡量一切学说；常被称为中国最早的后果主义者。"},"schools":["mohism"],"works":[{"t":{"en":"Mozi (compiled by his followers)","zh":"《墨子》（门人编纂）"},"y":-350}],"wiki":"Mozi"},
  {"id":"shang-yang","tradition":"eastasia","born":-390,"died":-338,"life":{"en":"c. 390–338 BCE","zh":"约公元前390–前338年"},"name":{"en":"Shang Yang","zh":"商鞅"},"role":{"en":"Qin minister whose reforms built Qin’s power","zh":"秦国重臣，其变法奠定了秦的强盛"},"idea":{"en":"Reorganised Qin around farming and war: ranks earned by military merit, households made mutually responsible, and strict laws applied to all. After his patron Duke Xiao died he was executed by being torn apart by chariots.","zh":"以耕战重组秦国：按军功授爵，什伍连坐，严刑峻法普遍适用。其支持者秦孝公死后，他被车裂而死。"},"schools":["legalism"],"works":[{"t":{"en":"The Book of Lord Shang (compiled by followers)","zh":"《商君书》（后学编纂）"},"y":-300}],"wiki":"Shang Yang"},
  {"id":"mencius","tradition":"eastasia","born":-372,"died":-289,"life":{"en":"c. 372–289 BCE","zh":"约公元前372–前289年"},"name":{"en":"Mencius","zh":"孟子"},"role":{"en":"Confucian who argued that human nature is good","zh":"主张人性本善的儒家思想家"},"idea":{"en":"Everyone has four “sprouts” of benevolence, righteousness, propriety and wisdom, shown by the alarm anyone feels on seeing a child about to fall into a well; cultivation makes them grow. A ruler who oppresses the people loses Heaven’s mandate.","zh":"人人皆有仁、义、礼、智“四端”，正如任何人见到孩子将要跌入井中都会怵惕恻隐；扩充培养便能使之成长。暴虐百姓的君主将失去天命。"},"schools":["confucianism"],"works":[{"t":{"en":"Mencius","zh":"《孟子》"},"y":-300}],"wiki":"Mencius","c":"Half Portraits of the Great Sage and Virtuous Men of Old - Meng Ke (孟軻).jpg","portrait":{"w":600,"h":813,"v":"1efa3cc9ec","author":"anonymous","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Half_Portraits_of_the_Great_Sage_and_Virtuous_Men_of_Old_-_Meng_Ke_(%E5%AD%9F%E8%BB%BB).jpg"}},
  {"id":"hui-shi","tradition":"eastasia","born":-370,"died":-310,"life":{"en":"c. 370–310 BCE","zh":"约公元前370–前310年"},"name":{"en":"Hui Shi","zh":"惠施"},"role":{"en":"Wei statesman, logician and Zhuangzi’s debating partner","zh":"魏国相，名辩家，庄子的论辩对手"},"idea":{"en":"His ten paradoxes, preserved only in the Zhuangzi, argue that size, place and time are relative (“I set off for Yue today and arrived yesterday”), ending in “love all things; heaven and earth are one body”. His own writings are lost.","zh":"他的“历物十事”仅保存于《庄子》中，论证大小、方位与时间的相对性（如“今日适越而昔来”），最终归结为“泛爱万物，天地一体也”。其本人著作已佚。"},"schools":["school-of-names"],"works":[],"wiki":"Hui Shi"},
  {"id":"zhuangzi","tradition":"eastasia","born":-369,"died":-286,"life":{"en":"c. 369–286 BCE","zh":"约公元前369–前286年"},"name":{"en":"Zhuangzi","zh":"庄子"},"role":{"en":"Daoist writer of parables, paradoxes and freedom","zh":"以寓言与悖论书写自由的道家思想家"},"idea":{"en":"Through stories such as the butterfly dream and Cook Ding carving an ox, he showed that every perspective is partial and that freedom comes from “free and easy wandering” with change rather than clinging to fixed views.","zh":"他借庄周梦蝶、庖丁解牛等故事表明，一切视角都是片面的；真正的自由在于随变化而“逍遥游”，而非执着于固定的见解。"},"schools":["daoism"],"works":[{"t":{"en":"Zhuangzi (the Inner Chapters)","zh":"《庄子》（内篇）"},"y":-290}],"wiki":"Zhuang Zhou","c":"玄門十子圖 莊子.jpg","portrait":{"w":600,"h":864,"v":"88958eda40","author":"Hua Zili (華祖立)","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:%E7%8E%84%E9%96%80%E5%8D%81%E5%AD%90%E5%9C%96_%E8%8E%8A%E5%AD%90.jpg"}},
  {"id":"gongsun-long","tradition":"eastasia","born":-320,"died":-250,"life":{"en":"c. 320–250 BCE","zh":"约公元前320–前250年"},"name":{"en":"Gongsun Long","zh":"公孙龙"},"role":{"en":"Disputer famous for “a white horse is not a horse”","zh":"以“白马非马”闻名的辩者"},"idea":{"en":"Argued that a term for a compound (“white horse”) is not the same as a term for a kind (“horse”), probing how names pick out attributes and things.","zh":"论证指称复合物的名（“白马”）不同于指称类别的名（“马”），由此探讨名如何指称属性与事物。"},"schools":["school-of-names"],"works":[{"t":{"en":"Gongsun Longzi (partly surviving)","zh":"《公孙龙子》（部分存世）"},"y":-270}],"wiki":"Gongsun Long"},
  {"id":"xunzi","tradition":"eastasia","born":-310,"died":-235,"life":{"en":"c. 310–235 BCE","zh":"约公元前310–前235年"},"name":{"en":"Xunzi","zh":"荀子"},"role":{"en":"Confucian realist who held human nature to be bad","zh":"主张人性本恶的儒家现实主义者"},"idea":{"en":"Human nature left to itself leads to strife; goodness is the product of deliberate effort (wei) through ritual and learning, as a warped board is straightened by steaming and bending.","zh":"人性顺其自然会导致争夺；善是通过礼义与学习的“伪”（人为努力）造就的，正如弯曲的木材须经蒸烤矫正才能变直。"},"schools":["confucianism"],"works":[{"t":{"en":"Xunzi","zh":"《荀子》"},"y":-250}],"wiki":"Xunzi (philosopher)"},
  {"id":"han-feizi","tradition":"eastasia","born":-280,"died":-233,"life":{"en":"c. 280–233 BCE","zh":"约公元前280–前233年"},"name":{"en":"Han Feizi","zh":"韩非"},"role":{"en":"Prince of Han who synthesised Legalist thought","zh":"韩国公子，法家思想的集大成者"},"idea":{"en":"Combined law (fa), positional power (shi) and administrative technique (shu) into a theory of rule that relies on self-interest rather than virtue. A student of Xunzi, he died in a Qin prison.","zh":"将“法”“势”“术”合为一体，构建了一种依靠人的自利而非德行的统治理论。他曾师从荀子，最终死于秦国狱中。"},"schools":["legalism"],"works":[{"t":{"en":"Han Feizi","zh":"《韩非子》"},"y":-240}],"wiki":"Han Fei"},
  {"id":"dong-zhongshu","tradition":"eastasia","born":-179,"died":-104,"life":{"en":"c. 179–104 BCE","zh":"约公元前179–前104年"},"name":{"en":"Dong Zhongshu","zh":"董仲舒"},"role":{"en":"Han scholar who helped make Confucianism the state learning","zh":"推动儒学成为国家官学的汉代学者"},"idea":{"en":"Joined Confucian ethics to yin–yang and five-phase cosmology: Heaven and humanity resonate, so natural portents warn a ruler of his faults. His advice to Emperor Wu helped place Confucian classics at the centre of court learning.","zh":"将儒家伦理与阴阳五行宇宙论相结合，提出“天人感应”：自然灾异是上天对君主过失的警示。他对汉武帝的建言推动了儒家经典成为朝廷学术的中心。"},"schools":["confucianism"],"works":[{"t":{"en":"Luxuriant Dew of the Spring and Autumn Annals (attributed)","zh":"《春秋繁露》（托名）"},"y":-110}],"wiki":"Dong Zhongshu"},
  {"id":"wang-bi","tradition":"eastasia","born":226,"died":249,"life":{"en":"226–249","zh":"226–249年"},"name":{"en":"Wang Bi","zh":"王弼"},"role":{"en":"Prodigy commentator who founded Xuanxue metaphysics","zh":"早慧的注释家，玄学“贵无”论的奠基者"},"idea":{"en":"Read the Laozi and the Book of Changes as pointing to non-being (wu) as the root of all beings, and taught that once meaning is grasped, words and images can be forgotten. He died at twenty-three.","zh":"把《老子》和《周易》解读为指向“以无为本”，并主张“得意忘言”。他年仅二十三岁便去世。"},"schools":["xuanxue"],"works":[{"t":{"en":"Commentary on the Laozi","zh":"《老子注》"},"y":245},{"t":{"en":"Commentary on the Book of Changes","zh":"《周易注》"},"y":247}],"wiki":"Wang Bi"},
  {"id":"guo-xiang","tradition":"eastasia","born":252,"died":312,"life":{"en":"c. 252–312","zh":"约252–312年"},"name":{"en":"Guo Xiang","zh":"郭象"},"role":{"en":"Editor and commentator who shaped the Zhuangzi we read","zh":"编订并注释今本《庄子》的学者"},"idea":{"en":"Denied any creator or “non-being” behind things: each thing generates itself and is fulfilled by following its own nature, so the sage can serve in government while remaining inwardly free. He drew heavily on Xiang Xiu’s earlier commentary.","zh":"否认万物背后有造物者或“无”：万物自生独化，各顺其性便得圆满，因此圣人可以身处庙堂而心游山林。他大量吸收了向秀的旧注。"},"schools":["xuanxue"],"works":[{"t":{"en":"Commentary on the Zhuangzi","zh":"《庄子注》"},"y":300}],"wiki":"Guo Xiang"},
  {"id":"huineng","tradition":"eastasia","born":638,"died":713,"life":{"en":"638–713","zh":"638–713年"},"name":{"en":"Huineng","zh":"慧能"},"role":{"en":"Sixth Patriarch of Chan, emblem of sudden awakening","zh":"禅宗六祖，顿悟法门的象征"},"idea":{"en":"Taught that everyone’s original nature is pure and that seeing it directly is enlightenment, not the result of gradually polishing the mind. Much of his traditional story comes from the later Platform Sutra and the polemics of his follower Shenhui.","zh":"主张人人本性清净，直见本性即是觉悟，而非逐渐“拂拭”心镜的结果。他的传统生平很大程度上来自后出的《坛经》以及弟子神会的论争。"},"schools":["chan-zen"],"works":[{"t":{"en":"Platform Sutra (attributed; compiled by followers)","zh":"《六祖坛经》（门人记录）"},"y":780}],"wiki":"Huineng"},
  {"id":"zhou-dunyi","tradition":"eastasia","born":1017,"died":1073,"life":{"en":"1017–1073","zh":"1017–1073年"},"name":{"en":"Zhou Dunyi","zh":"周敦颐"},"role":{"en":"Song scholar honoured as the pioneer of Neo-Confucianism","zh":"被尊为理学开山的宋代学者"},"idea":{"en":"His Diagram of the Supreme Ultimate traced how the Ultimate of Non-being and the Supreme Ultimate give rise to yin and yang, the five phases and all things, and he grounded sagehood in sincerity (cheng).","zh":"其《太极图说》描述了“无极而太极”如何化生阴阳、五行与万物，并以“诚”为圣人之本。"},"schools":["neo-confucianism"],"works":[{"t":{"en":"Explanation of the Diagram of the Supreme Ultimate","zh":"《太极图说》"},"y":1070},{"t":{"en":"Penetrating the Book of Changes","zh":"《通书》"},"y":1070}],"wiki":"Zhou Dunyi"},
  {"id":"zhang-zai","tradition":"eastasia","born":1020,"died":1077,"life":{"en":"1020–1077","zh":"1020–1077年"},"name":{"en":"Zhang Zai","zh":"张载"},"role":{"en":"Neo-Confucian who saw all things as condensations of qi","zh":"以“气”解释万物聚散的理学家"},"idea":{"en":"Everything is qi condensing and dispersing in the Great Void; because all share one qi, “Heaven is my father and Earth my mother… all people are my siblings.”","zh":"万物都是“太虚”之中气的聚散；因为同出一气，所以“乾称父，坤称母……民吾同胞，物吾与也”。"},"schools":["neo-confucianism"],"works":[{"t":{"en":"Western Inscription","zh":"《西铭》"},"y":1070},{"t":{"en":"Correcting the Unenlightened","zh":"《正蒙》"},"y":1076}],"wiki":"Zhang Zai"},
  {"id":"cheng-hao","tradition":"eastasia","born":1032,"died":1085,"life":{"en":"1032–1085","zh":"1032–1085年"},"name":{"en":"Cheng Hao","zh":"程颢"},"role":{"en":"Elder Cheng brother, teacher of humaneness as oneness","zh":"二程中的兄长，以“万物一体”论仁"},"idea":{"en":"The humane person forms one body with heaven, earth and the myriad things; principle is realised by quietly recognising this unity rather than by piling up book learning.","zh":"仁者以天地万物为一体；体认天理在于默识这种一体，而非堆积书本知识。"},"schools":["neo-confucianism"],"works":[{"t":{"en":"On Understanding Humaneness","zh":"《识仁篇》"},"y":1080}],"wiki":"Cheng Hao"},
  {"id":"cheng-yi","tradition":"eastasia","born":1033,"died":1107,"life":{"en":"1033–1107","zh":"1033–1107年"},"name":{"en":"Cheng Yi","zh":"程颐"},"role":{"en":"Younger Cheng brother who made “principle” central","zh":"二程中的弟弟，使“理”成为核心概念"},"idea":{"en":"Taught that “human nature is principle” and that one approaches principle by investigating things one by one while holding reverent seriousness (jing).","zh":"提出“性即理”，主张通过逐一格物并持守“敬”来接近天理。"},"schools":["neo-confucianism"],"works":[{"t":{"en":"Commentary on the Book of Changes","zh":"《伊川易传》"},"y":1099}],"wiki":"Cheng Yi (philosopher)"},
  {"id":"zhu-xi","tradition":"eastasia","born":1130,"died":1200,"life":{"en":"1130–1200","zh":"1130–1200年"},"name":{"en":"Zhu Xi","zh":"朱熹"},"role":{"en":"Great synthesiser of Song Neo-Confucianism","zh":"宋代理学的集大成者"},"idea":{"en":"Systematised the theory of principle and qi and put the Four Books at the centre of learning; by investigating things patiently, one finally reaches a sudden, comprehensive understanding of principle.","zh":"系统化了理气论，并将《四书》置于学问的中心；耐心格物日久，终能“豁然贯通”，通晓天理。"},"schools":["neo-confucianism"],"works":[{"t":{"en":"Reflections on Things at Hand (with Lü Zuqian)","zh":"《近思录》（与吕祖谦合编）"},"y":1175},{"t":{"en":"Collected Commentaries on the Four Books","zh":"《四书章句集注》"},"y":1190}],"wiki":"Zhu Xi","c":"唯一可靠的朱熹画像.jpg","portrait":{"w":600,"h":675,"v":"71faa10080","author":"向史公哲曰","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","page":"https://commons.wikimedia.org/wiki/File:%E5%94%AF%E4%B8%80%E5%8F%AF%E9%9D%A0%E7%9A%84%E6%9C%B1%E7%86%B9%E7%94%BB%E5%83%8F.jpg"}},
  {"id":"lu-jiuyuan","tradition":"eastasia","born":1139,"died":1193,"life":{"en":"1139–1193","zh":"1139–1193年"},"name":{"en":"Lu Jiuyuan (Lu Xiangshan)","zh":"陆九渊（象山）"},"role":{"en":"Song scholar who taught that the mind is principle","zh":"主张“心即理”的宋代学者"},"idea":{"en":"“The universe is my mind, and my mind is the universe”: moral principle is complete in the original mind, so learning means first “establishing the great root” rather than fragmented study. He left mainly letters and recorded sayings.","zh":"“宇宙便是吾心，吾心即是宇宙”：道德之理完具于本心，所以为学应“先立乎其大者”，而非支离地考索。他主要留下书信与语录。"},"schools":["xinxue"],"works":[],"wiki":"Lu Jiuyuan"},
  {"id":"dogen","tradition":"eastasia","born":1200,"died":1253,"life":{"en":"1200–1253","zh":"1200–1253年"},"name":{"en":"Dōgen","zh":"道元"},"role":{"en":"Japanese monk who founded Sōtō Zen","zh":"日本曹洞宗的开创者"},"idea":{"en":"Taught “just sitting” (shikantaza): practice is not a means to enlightenment but enlightenment itself, and being is time (uji).","zh":"倡导“只管打坐”：修行不是通往觉悟的手段，修行本身就是觉悟；并提出“有时”，即存在即时间。"},"schools":["chan-zen"],"works":[{"t":{"en":"Universal Recommendation for Zazen","zh":"《普劝坐禅仪》"},"y":1227},{"t":{"en":"Shōbōgenzō","zh":"《正法眼藏》"},"y":1240}],"wiki":"Dōgen"},
  {"id":"wang-yangming","tradition":"eastasia","born":1472,"died":1529,"life":{"en":"1472–1529","zh":"1472–1529年"},"name":{"en":"Wang Yangming","zh":"王阳明（王守仁）"},"role":{"en":"Ming official, general and master of the School of Mind","zh":"明代官员、军事家，心学的集大成者"},"idea":{"en":"Principle is in the mind; everyone has innate good knowing (liangzhi), and knowing and acting are one, so moral learning means extending that knowing in action.","zh":"理在心中；人人皆有良知，知行合一，因此道德修养就是在行动中“致良知”。"},"schools":["xinxue"],"works":[{"t":{"en":"Instructions for Practical Living","zh":"《传习录》"},"y":1518},{"t":{"en":"Inquiry on the Great Learning","zh":"《大学问》"},"y":1527}],"wiki":"Wang Yangming","c":"王守仁.jpg","portrait":{"w":600,"h":719,"v":"41cb7287fc","author":"Shen Junhui (沈俊繪)","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:%E7%8E%8B%E5%AE%88%E4%BB%81.jpg"}},
  {"id":"yi-hwang","tradition":"eastasia","born":1501,"died":1570,"life":{"en":"1501–1570","zh":"1501–1570年"},"name":{"en":"Yi Hwang (Toegye)","zh":"李滉（退溪）"},"role":{"en":"Leading Neo-Confucian scholar of Joseon Korea","zh":"朝鲜王朝最重要的理学家之一"},"idea":{"en":"In the Four–Seven debate with Ki Taesŭng he argued that the four moral sprouts issue from principle and the seven emotions from qi, giving principle an active role in moral life.","zh":"在与奇大升的“四七之辩”中主张四端发于理、七情发于气，赋予“理”在道德生活中的能动作用。"},"schools":["neo-confucianism"],"works":[{"t":{"en":"Ten Diagrams on Sage Learning","zh":"《圣学十图》"},"y":1568}],"wiki":"Yi Hwang"},
  {"id":"yi-i","tradition":"eastasia","born":1536,"died":1584,"life":{"en":"1536–1584","zh":"1536–1584年"},"name":{"en":"Yi I (Yulgok)","zh":"李珥（栗谷）"},"role":{"en":"Korean statesman-scholar and Toegye’s younger rival","zh":"朝鲜政治家兼学者，退溪的后辈论敌"},"idea":{"en":"Held that only qi issues and principle “rides” on it, so the four sprouts are a subset of the seven emotions; he also pressed for practical reforms of government.","zh":"主张“气发理乘”，只有气能发动，理乘于其上，因此四端包含在七情之中；他还力主务实的政治改革。"},"schools":["neo-confucianism"],"works":[{"t":{"en":"Essentials of Sage Learning","zh":"《圣学辑要》"},"y":1575}],"wiki":"Yi I"},
  {"id":"nishida","tradition":"eastasia","born":1870,"died":1945,"life":{"en":"1870–1945","zh":"1870–1945年"},"name":{"en":"Nishida Kitarō","zh":"西田几多郎"},"role":{"en":"Founder of the Kyoto School","zh":"京都学派的创始人"},"idea":{"en":"Began from “pure experience” prior to the split between subject and object, and later developed a “logic of place” (basho) whose ultimate ground is absolute nothingness.","zh":"从主客未分的“纯粹经验”出发，后来发展出“场所的逻辑”，其最终根基是“绝对无”。"},"schools":["kyoto"],"works":[{"t":{"en":"An Inquiry into the Good","zh":"《善的研究》"},"y":1911},{"t":{"en":"From the Acting to the Seeing","zh":"《从动者到见者》"},"y":1927}],"wiki":"Kitaro Nishida"},
  {"id":"tanabe","tradition":"eastasia","born":1885,"died":1962,"life":{"en":"1885–1962","zh":"1885–1962年"},"name":{"en":"Tanabe Hajime","zh":"田边元"},"role":{"en":"Kyoto School philosopher and Nishida’s critic","zh":"京都学派哲学家，西田的批评者"},"idea":{"en":"Criticised Nishida’s “place of nothingness” as too contemplative and proposed a “logic of species” centred on social mediation; after the war he called for “metanoetics”, philosophy as repentance.","zh":"批评西田的“无的场所”过于静观，提出以社会中介为中心的“种的逻辑”；战后则倡导“忏悔道”，即作为忏悔的哲学。"},"schools":["kyoto"],"works":[{"t":{"en":"Philosophy as Metanoetics","zh":"《作为忏悔道的哲学》"},"y":1946}],"wiki":"Hajime Tanabe"},
  {"id":"xiong-shili","tradition":"eastasia","born":1885,"died":1968,"life":{"en":"1885–1968","zh":"1885–1968年"},"name":{"en":"Xiong Shili","zh":"熊十力"},"role":{"en":"Founder of New Confucian metaphysics","zh":"现代新儒家形上学的奠基者"},"idea":{"en":"Trained in Yogācāra, he broke with it: original reality (benti) and its functioning (yong) are not two, but one ceaselessly creative process grasped in the moral mind.","zh":"他出身唯识学，后又与之决裂，主张“体用不二”：本体与其作用并非两物，而是在道德本心中体认到的生生不息的创造过程。"},"schools":["new-confucianism"],"works":[{"t":{"en":"New Treatise on Consciousness-Only","zh":"《新唯识论》"},"y":1932}],"wiki":"Xiong Shili"},
  {"id":"hu-shi","tradition":"eastasia","born":1891,"died":1962,"life":{"en":"1891–1962","zh":"1891–1962年"},"name":{"en":"Hu Shi","zh":"胡适"},"role":{"en":"May Fourth reformer who brought pragmatism to China","zh":"把实用主义带入中国的五四运动领袖"},"idea":{"en":"A student of John Dewey at Columbia, he preached “bold hypotheses, careful verification”, applied scientific method to the study of Chinese tradition, and championed writing in the vernacular.","zh":"他在哥伦比亚大学师从杜威，提倡“大胆的假设，小心的求证”，以科学方法整理国故，并倡导白话文。"},"schools":["pragmatism"],"works":[{"t":{"en":"Some Modest Proposals for the Reform of Literature","zh":"《文学改良刍议》"},"y":1917},{"t":{"en":"Outline of the History of Chinese Philosophy, vol. 1","zh":"《中国哲学史大纲》（卷上）"},"y":1919}],"wiki":"Hu Shih"},
  {"id":"liang-shuming","tradition":"eastasia","born":1893,"died":1988,"life":{"en":"1893–1988","zh":"1893–1988年"},"name":{"en":"Liang Shuming","zh":"梁漱溟"},"role":{"en":"Philosopher and rural reformer, called “the last Confucian”","zh":"哲学家与乡村建设者，被称为“最后的儒家”"},"idea":{"en":"Argued that Western, Chinese and Indian cultures express three different orientations of the will, and that the world would turn from the Western path to the Chinese one; he later led the rural reconstruction movement.","zh":"认为西方、中国、印度文化体现了意欲的三种不同路向，世界将由西方路向转向中国路向；后来他投身乡村建设运动。"},"schools":["new-confucianism"],"works":[{"t":{"en":"Eastern and Western Cultures and Their Philosophies","zh":"《东西文化及其哲学》"},"y":1921},{"t":{"en":"The Essential Meaning of Chinese Culture","zh":"《中国文化要义》"},"y":1949}],"wiki":"Liang Shuming"},
  {"id":"feng-youlan","tradition":"eastasia","born":1895,"died":1990,"life":{"en":"1895–1990","zh":"1895–1990年"},"name":{"en":"Feng Youlan","zh":"冯友兰"},"role":{"en":"Historian of Chinese philosophy and builder of a “new principle learning”","zh":"中国哲学史家，“新理学”的构建者"},"idea":{"en":"Used Western logical analysis to rebuild Cheng–Zhu principle learning and wrote a landmark modern history of Chinese philosophy; he described four realms of life, rising to the “realm of heaven and earth”.","zh":"用西方逻辑分析方法重建程朱理学，写出具有里程碑意义的现代中国哲学史；他提出人生四境界，最高为“天地境界”。"},"schools":["new-confucianism"],"works":[{"t":{"en":"A History of Chinese Philosophy","zh":"《中国哲学史》"},"y":1934},{"t":{"en":"New Treatise on Principle","zh":"《新理学》"},"y":1939}],"wiki":"Feng Youlan"},
  {"id":"nishitani","tradition":"eastasia","born":1900,"died":1990,"life":{"en":"1900–1990","zh":"1900–1990年"},"name":{"en":"Nishitani Keiji","zh":"西谷启治"},"role":{"en":"Kyoto School thinker of nihilism and emptiness","zh":"思考虚无主义与“空”的京都学派哲学家"},"idea":{"en":"Argued that modern nihilism can only be overcome by passing through nothingness to the standpoint of emptiness (śūnyatā). He attended Heidegger’s lectures in Freiburg in 1937–39.","zh":"主张现代虚无主义只能通过穿越“虚无”而达到“空”（śūnyatā）的立场来克服。1937至1939年，他在弗赖堡听过海德格尔的课。"},"schools":["kyoto"],"works":[{"t":{"en":"The Self-Overcoming of Nihilism","zh":"《虚无主义》"},"y":1949},{"t":{"en":"Religion and Nothingness","zh":"《宗教是什么》"},"y":1961}],"wiki":"Keiji Nishitani"},
  {"id":"mou-zongsan","tradition":"eastasia","born":1909,"died":1995,"life":{"en":"1909–1995","zh":"1909–1995年"},"name":{"en":"Mou Zongsan","zh":"牟宗三"},"role":{"en":"Leading second-generation New Confucian and translator of Kant","zh":"第二代现代新儒家的代表，康德著作的译者"},"idea":{"en":"Argued, against Kant, that humans do have “intellectual intuition” through the moral mind, and built a Confucian “moral metaphysics” that he traced mainly through the Lu–Wang line.","zh":"针对康德，主张人通过道德本心确有“智的直觉”，并建立了儒家的“道德形上学”，以陆王一系为其主要传承。"},"schools":["new-confucianism"],"works":[{"t":{"en":"Mind and Human Nature","zh":"《心体与性体》"},"y":1968},{"t":{"en":"Phenomenon and Thing-in-Itself","zh":"《现象与物自身》"},"y":1975}],"wiki":"Mou Zongsan"},
  {"id":"uddalaka","tradition":"indian","born":-780,"died":-700,"life":{"en":"fl. c. 8th c. BCE (traditional)","zh":"约公元前8世纪（传统说法）"},"name":{"en":"Uddālaka Āruṇi","zh":"乌达罗迦·阿鲁尼"},"role":{"en":"Upanishadic teacher who told his son ‘You are that’","zh":"对儿子说出“你就是那个”的奥义书导师"},"idea":{"en":"In the Chāndogya Upaniṣad he teaches his son Śvetaketu, with images like salt dissolved in water, that the subtle essence of all things is the self: ‘you are that’ (tat tvam asi). He also held that the world arose from ‘being’ (sat), not from non-being.","zh":"在《歌者奥义书》中，他用盐溶于水等比喻教导儿子希婆多凯土：万物精微的本质就是自我——“你就是那个”。他还认为世界源于“有”，而非源于“无”。"},"schools":["upanishads"],"works":[{"t":{"en":"Chāndogya Upaniṣad (teachings ascribed to him)","zh":"《歌者奥义书》（归于他的教导）"},"y":-650}],"wiki":"Uddalaka Aruni"},
  {"id":"yajnavalkya","tradition":"indian","born":-750,"died":-680,"life":{"en":"fl. c. 8th–7th c. BCE (traditional)","zh":"约公元前8–前7世纪（传统说法）"},"name":{"en":"Yājñavalkya","zh":"耶若伏吉耶"},"role":{"en":"Sage who wins the great debate at King Janaka’s court","zh":"在遮那迦王宫廷辩论中胜出的圣者"},"idea":{"en":"Known from his dialogues in the Bṛhadāraṇyaka Upaniṣad, he taught that the self is the unseen seer and inner controller, describable only as ‘not this, not this’ (neti neti).","zh":"他的思想见于《广林奥义书》中的对话：自我是不可见的见者、内在的主宰，只能用“不是这个，不是这个”来描述。"},"schools":["upanishads"],"works":[{"t":{"en":"Bṛhadāraṇyaka Upaniṣad (dialogues traditionally credited to him)","zh":"《广林奥义书》（传统上归于他的对话）"},"y":-700}],"wiki":"Yajnavalkya"},
  {"id":"mahavira","tradition":"indian","born":-599,"died":-527,"life":{"en":"traditionally 599–527 BCE (many scholars date him later)","zh":"传统说法公元前599–前527年（许多学者认为更晚）"},"name":{"en":"Mahāvīra","zh":"大雄"},"role":{"en":"Twenty-fourth Jain tīrthaṅkara, a contemporary of the Buddha","zh":"耆那教第二十四位祖师，与佛陀同时代"},"idea":{"en":"Left princely life, practised severe austerities, and taught that liberation comes from the ‘three jewels’—right faith, right knowledge, right conduct—and five vows led by non-violence. His teachings were preserved orally in the Jain canon.","zh":"他放弃王子生活，修习严苛的苦行，教导解脱来自“三宝”——正信、正知、正行——以及以不杀生为首的五大誓。他的教导经口传保存在耆那教圣典中。"},"schools":["jainism"],"works":[],"wiki":"Mahavira"},
  {"id":"ajita","tradition":"indian","born":-560,"died":-480,"life":{"en":"fl. 6th–5th c. BCE","zh":"约公元前6–前5世纪"},"name":{"en":"Ajita Kesakambalī","zh":"阿耆多·翅舍钦婆罗"},"role":{"en":"Materialist teacher of the Buddha’s time, named for his hair blanket","zh":"佛陀时代的唯物论导师，以身披发毯得名"},"idea":{"en":"Wrote nothing that survives. As reported in the Buddhist Sāmaññaphala Sutta, he taught that a person is made of four elements that disperse at death, so there is no fruit of good or bad deeds and no other world.","zh":"没有著作传世。据佛经《沙门果经》转述，他认为人由四大元素组成，死后即各自散去，因此善恶行为没有果报，也不存在来世。"},"schools":["charvaka"],"works":[],"wiki":"Ajita Kesakambali"},
  {"id":"buddha","tradition":"indian","born":-480,"died":-400,"life":{"en":"c. 480–400 BCE (debated; traditionally 563–483 BCE)","zh":"约公元前480–前400年（有争议；传统说法为前563–前483年）"},"name":{"en":"The Buddha (Siddhārtha Gautama)","zh":"释迦牟尼（乔达摩·悉达多）"},"role":{"en":"Founder of Buddhism, who taught a middle way out of suffering","zh":"佛教创立者，教导一条脱离痛苦的中道"},"idea":{"en":"He wrote nothing; his disciples memorised his discourses. He taught that suffering comes from craving and from ignorance of impermanence and non-self, and that it can be ended through the Eightfold Path of ethics, meditation and wisdom.","zh":"他没有留下著作，弟子们背诵记下他的教说。他教导：苦来自渴爱，以及对无常、无我的无知；通过戒、定、慧的八正道，苦可以止息。"},"schools":["buddhism"],"works":[],"wiki":"The Buddha","c":"Buddha in Sarnath Museum (Dhammajak Mutra).jpg","portrait":{"w":600,"h":769,"v":"29d5b37b75","author":"พระมหาเทวประภาส วชิรญาณเมธี","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","page":"https://commons.wikimedia.org/wiki/File:Buddha_in_Sarnath_Museum_(Dhammajak_Mutra).jpg"}},
  {"id":"jaimini","tradition":"indian","born":-250,"died":-180,"life":{"en":"c. 3rd–2nd c. BCE (traditional)","zh":"约公元前3–前2世纪（传统说法）"},"name":{"en":"Jaimini","zh":"阇弥尼"},"role":{"en":"Traditional author of the Mīmāṃsā Sūtra","zh":"传统上《弥曼差经》的作者"},"idea":{"en":"His sūtras open with ‘Now, the inquiry into dharma’, define duty as what Vedic injunctions command, and give systematic rules for interpreting ritual texts.","zh":"他的经文以“今欲探究达磨”开篇，把职责定义为吠陀命令所规定之事，并提出解释祭祀文本的系统规则。"},"schools":["mimamsa"],"works":[{"t":{"en":"Mīmāṃsā Sūtra","zh":"《弥曼差经》"},"y":-200}],"wiki":"Jaimini"},
  {"id":"kanada","tradition":"indian","born":-200,"died":-130,"life":{"en":"c. 2nd c. BCE? (dates uncertain)","zh":"约公元前2世纪？（年代不确定）"},"name":{"en":"Kaṇāda","zh":"迦那陀"},"role":{"en":"Founder of Vaiśeṣika, India’s classic atomism","zh":"胜论派创始人，印度经典原子论的奠基者"},"idea":{"en":"He classified reality into categories—substance, quality, action, universal, particularity, inherence—and held that the material world is built from eternal, indivisible atoms.","zh":"他把实在分为若干范畴——实、德、业、同、异、和合——并认为物质世界由永恒而不可分的极微构成。"},"schools":["nyaya"],"works":[{"t":{"en":"Vaiśeṣika Sūtra","zh":"《胜论经》"},"y":-150}],"wiki":"Kanada (philosopher)"},
  {"id":"akshapada","tradition":"indian","born":100,"died":170,"life":{"en":"c. 2nd c. BCE – 2nd c. CE (traditional author)","zh":"约公元前2世纪–公元2世纪（传统上的作者）"},"name":{"en":"Akṣapāda Gautama","zh":"足目（乔达摩）"},"role":{"en":"Traditional author of the Nyāya Sūtra","zh":"传统上《正理经》的作者"},"idea":{"en":"He listed sixteen topics for disciplined debate and four means of knowledge, and set out the five-part syllogism—thesis, reason, example, application, conclusion—as the form of sound argument.","zh":"他列出有序辩论的十六句义与四种量，并提出五支论式——宗、因、喻、合、结——作为正确论证的形式。"},"schools":["nyaya"],"works":[{"t":{"en":"Nyāya Sūtra","zh":"《正理经》"},"y":150}],"wiki":"Akshapada Gautama"},
  {"id":"nagarjuna","tradition":"indian","born":150,"died":250,"life":{"en":"c. 150–250","zh":"约150–250年"},"name":{"en":"Nāgārjuna","zh":"龙树"},"role":{"en":"Founder of Madhyamaka, revered as a ‘second Buddha’","zh":"中观派创始人，被尊为“第二佛陀”"},"idea":{"en":"He argued that nothing has intrinsic nature because everything arises dependently; emptiness is not nothingness but the Middle Way, and emptiness itself is empty.","zh":"他论证：一切皆依缘而生，所以没有任何事物具有自性；空不是虚无，而是中道，而且空本身也是空的。"},"schools":["madhyamaka"],"works":[{"t":{"en":"Mūlamadhyamakakārikā (Fundamental Verses on the Middle Way)","zh":"《中论》"},"y":200},{"t":{"en":"Vigrahavyāvartanī (The Dispeller of Disputes)","zh":"《回诤论》"},"y":200}],"wiki":"Nagarjuna","c":"Nagarjuna with 84 mahasiddha cropped.jpg","portrait":{"w":600,"h":750,"v":"e9d7465f46","author":"Unknown | Recovered from Himalayan Art Resources","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Nagarjuna_with_84_mahasiddha_cropped.jpg"}},
  {"id":"asanga","tradition":"indian","born":310,"died":390,"life":{"en":"c. 4th c. CE","zh":"约公元4世纪"},"name":{"en":"Asaṅga","zh":"无著"},"role":{"en":"Co-founder of Yogācāra, elder half-brother of Vasubandhu","zh":"瑜伽行派共同创始人，世亲的兄长"},"idea":{"en":"He systematised Yogācāra—the storehouse consciousness, the three natures and the bodhisattva path—drawing, tradition says, on teachings revealed to him by the future Buddha Maitreya.","zh":"他系统阐述了瑜伽行派的阿赖耶识、三性与菩萨道；据传统说法，他的学说得自未来佛弥勒的启示。"},"schools":["yogacara"],"works":[{"t":{"en":"Mahāyānasaṃgraha (Compendium of the Mahāyāna)","zh":"《摄大乘论》"},"y":370}],"wiki":"Asanga"},
  {"id":"vasubandhu","tradition":"indian","born":330,"died":410,"life":{"en":"c. 4th–5th c. CE","zh":"约公元4–5世纪"},"name":{"en":"Vasubandhu","zh":"世亲"},"role":{"en":"Abhidharma master who became Yogācāra’s great systematiser","zh":"由阿毗达磨大师转为唯识学的集大成者"},"idea":{"en":"He first summed up Abhidharma in his Treasury; then, converted by Asaṅga, he argued in short verse treatises that experience is ‘mere representation’, using dream examples and a critique of atoms.","zh":"他先在《俱舍论》中总结了阿毗达磨；后来在无著影响下转向大乘，在简短的颂文中以梦为喻、并批判极微说，论证经验“唯是表识”。"},"schools":["yogacara"],"works":[{"t":{"en":"Abhidharmakośa (Treasury of Abhidharma)","zh":"《阿毗达磨俱舍论》"},"y":380},{"t":{"en":"Viṃśatikā (Twenty Verses)","zh":"《唯识二十论》"},"y":400}],"wiki":"Vasubandhu"},
  {"id":"umasvati","tradition":"indian","born":350,"died":420,"life":{"en":"c. 2nd–5th c. CE (dates uncertain)","zh":"约公元2–5世纪（年代不确定）"},"name":{"en":"Umāsvāti","zh":"乌玛斯瓦蒂"},"role":{"en":"Author of the Jain text accepted by both main sects","zh":"写出耆那教两大派共同承认之经典的作者"},"idea":{"en":"His Tattvārtha Sūtra compressed Jain teaching into concise aphorisms, setting out seven realities from soul and non-soul to liberation, and the path of right faith, knowledge and conduct.","zh":"他的《谛义证得经》把耆那教教义浓缩为简洁的经句，阐述了从命（灵魂）与非命到解脱的七谛，以及正信、正知、正行之道。"},"schools":["jainism"],"works":[{"t":{"en":"Tattvārtha Sūtra","zh":"《谛义证得经》"},"y":400}],"wiki":"Umaswati"},
  {"id":"ishvarakrishna","tradition":"indian","born":350,"died":420,"life":{"en":"c. 4th–5th c. CE","zh":"约公元4–5世纪"},"name":{"en":"Īśvarakṛṣṇa","zh":"自在黑"},"role":{"en":"Author of the classical summary of Sāṃkhya","zh":"古典数论纲要的作者"},"idea":{"en":"His seventy-odd verses argue that effects pre-exist in their cause, that matter evolves into intellect, ego and world through three qualities, and that liberation comes from discriminating consciousness from matter.","zh":"他约七十首颂文论证：果先存于因中；物质经由三德演化出觉、我慢与世界；解脱来自把意识与物质分辨清楚。"},"schools":["samkhya-yoga"],"works":[{"t":{"en":"Sāṃkhyakārikā","zh":"《数论颂》（汉译注本为《金七十论》）"},"y":400}],"wiki":"Ishvara Krishna"},
  {"id":"patanjali","tradition":"indian","born":350,"died":420,"life":{"en":"c. 4th–5th c. CE? (dating disputed)","zh":"约公元4–5世纪？（年代有争议）"},"name":{"en":"Patañjali","zh":"帕坦伽利"},"role":{"en":"Compiler of the Yoga Sūtra","zh":"《瑜伽经》的编纂者"},"idea":{"en":"He defined yoga as ‘the stilling of the fluctuations of the mind’, set out eight limbs from ethical restraint to absorption (samādhi), and, within a Sāṃkhya-like framework, allowed a special self, Īśvara, as an object of devotion.","zh":"他把瑜伽定义为“止息心的波动”，提出从道德持戒到三摩地的八支，并在类似数论的框架中，承认一个特殊的自我——自在天——作为虔敬的对象。"},"schools":["samkhya-yoga"],"works":[{"t":{"en":"Yoga Sūtra","zh":"《瑜伽经》"},"y":400}],"wiki":"Patanjali"},
  {"id":"buddhaghosa","tradition":"indian","born":380,"died":450,"life":{"en":"fl. 5th c. CE","zh":"活跃于公元5世纪"},"name":{"en":"Buddhaghosa","zh":"觉音"},"role":{"en":"Theravāda commentator who systematised doctrine in Sri Lanka","zh":"在斯里兰卡系统整理教义的上座部注释家"},"idea":{"en":"Working at the Mahāvihāra in Anurādhapura, he wrote the Path of Purification, a map of Theravāda ethics, meditation and Abhidhamma analysis that is still its standard handbook.","zh":"他在阿努拉德普勒的大寺撰写了《清净道论》，系统描绘了上座部的戒律、禅修与阿毗达磨分析，至今仍是该传统的标准手册。"},"schools":["buddhism"],"works":[{"t":{"en":"Visuddhimagga (The Path of Purification)","zh":"《清净道论》"},"y":430}],"wiki":"Buddhaghosa"},
  {"id":"dignaga","tradition":"indian","born":480,"died":540,"life":{"en":"c. 480–540","zh":"约480–540年"},"name":{"en":"Dignāga","zh":"陈那"},"role":{"en":"Founder of Buddhist logic and epistemology","zh":"佛教逻辑与认识论的奠基者"},"idea":{"en":"He cut the means of knowledge to perception and inference, defined perception as free of concepts, explained word meaning as exclusion (apoha), and mapped valid and invalid reasons in his ‘wheel of reasons’.","zh":"他把认识手段精简为现量与比量，把现量定义为离分别（不带概念），用“遮遣”解释语词的意义，并以“九句因”系统区分有效与无效的理由。"},"schools":["pramana"],"works":[{"t":{"en":"Pramāṇasamuccaya (Compendium of Valid Cognition)","zh":"《集量论》"},"y":520},{"t":{"en":"Nyāyamukha (Introduction to Logic)","zh":"《因明正理门论》"},"y":500}],"wiki":"Dignāga"},
  {"id":"gaudapada","tradition":"indian","born":500,"died":570,"life":{"en":"c. 6th c. CE","zh":"约公元6世纪"},"name":{"en":"Gauḍapāda","zh":"乔荼波陀"},"role":{"en":"Earliest known Advaita teacher, by tradition Śaṅkara’s teacher’s teacher","zh":"已知最早的不二论导师，传统上是商羯罗的师祖"},"idea":{"en":"In verses on the Māṇḍūkya Upaniṣad he argued for non-origination (ajātivāda): nothing is ever truly born; the world of change is like a dream, and only non-dual consciousness is real.","zh":"他在解释《蛙氏奥义书》的颂文中提出“无生论”：没有任何东西真正生起；变化的世界如同梦境，唯有不二的意识是真实的。"},"schools":["advaita"],"works":[{"t":{"en":"Māṇḍūkya Kārikā","zh":"《蛙氏奥义颂》"},"y":550}],"wiki":"Gaudapada"},
  {"id":"chandrakirti","tradition":"indian","born":600,"died":650,"life":{"en":"c. 600–650","zh":"约600–650年"},"name":{"en":"Candrakīrti","zh":"月称"},"role":{"en":"Madhyamaka commentator whose reading became orthodox in Tibet","zh":"其诠释在西藏成为正统的中观注释家"},"idea":{"en":"He defended Buddhapālita against Bhāviveka: a Mādhyamika should only draw out the absurd consequences of opponents’ views rather than offer independent proofs. Tibetan scholars later named this approach Prāsaṅgika.","zh":"他为佛护辩护、反驳清辨：中观论者只应揭示论敌观点的荒谬后果，而不应另立自己的独立论证。后来的藏族学者把这一路线称为“应成派”。"},"schools":["madhyamaka"],"works":[{"t":{"en":"Prasannapadā (Clear Words)","zh":"《明句论》"},"y":630},{"t":{"en":"Madhyamakāvatāra (Entering the Middle Way)","zh":"《入中论》"},"y":630}],"wiki":"Chandrakirti"},
  {"id":"dharmakirti","tradition":"indian","born":600,"died":660,"life":{"en":"c. 600–660","zh":"约600–660年"},"name":{"en":"Dharmakīrti","zh":"法称"},"role":{"en":"Buddhist logician whose theory of knowledge dominated Indian debate","zh":"其认识论主导了印度哲学论辩的佛教逻辑学家"},"idea":{"en":"He grounded valid inference in two real relations, identity and causation, held that only what has causal power is ultimately real, and defended rebirth and the Buddha’s authority by argument rather than scripture.","zh":"他把有效推理建立在同一性与因果这两种真实关系之上，主张只有具有因果效力的东西才是胜义上真实的，并以论证而非经典来为轮回与佛陀的权威辩护。"},"schools":["pramana"],"works":[{"t":{"en":"Pramāṇavārttika (Commentary on Valid Cognition)","zh":"《释量论》"},"y":630},{"t":{"en":"Nyāyabindu (A Drop of Logic)","zh":"《正理一滴论》"},"y":640}],"wiki":"Dharmakirti"},
  {"id":"kumarila","tradition":"indian","born":620,"died":680,"life":{"en":"fl. 7th c.","zh":"活跃于7世纪"},"name":{"en":"Kumārila Bhaṭṭa","zh":"鸠摩利罗"},"role":{"en":"Mīmāṃsā champion of Vedic authority against the Buddhists","zh":"捍卫吠陀权威、对抗佛教的弥曼差派大师"},"idea":{"en":"He argued that every cognition is valid by itself until defeated, so the authorless Veda deserves trust, and he attacked Buddhist momentariness and the claim that anyone, the Buddha included, could be omniscient.","zh":"他主张每个认识在被推翻之前都自身有效，因此无作者的吠陀值得信任；他还批驳了佛教的刹那灭论，以及任何人（包括佛陀）能够全知的说法。"},"schools":["mimamsa"],"works":[{"t":{"en":"Ślokavārttika (Verse Commentary)","zh":"《颂释》"},"y":660}],"wiki":"Kumārila Bhaṭṭa"},
  {"id":"shankara","tradition":"indian","born":700,"died":750,"life":{"en":"c. 700–750 (traditionally 788–820)","zh":"约700–750年（传统说法788–820年）"},"name":{"en":"Śaṅkara","zh":"商羯罗"},"role":{"en":"Advaita master whose commentaries defined non-dual Vedānta","zh":"以注疏奠定不二论吠檀多的宗师"},"idea":{"en":"He taught that Brahman, pure consciousness, alone is real, that the individual self is identical with it, and that the world is superimposed on it through ignorance; liberation comes from knowledge, not ritual.","zh":"他教导：唯有纯粹意识之梵是真实的，个体自我与梵同一，世界则因无明而被增益于梵之上；解脱来自知识，而非祭祀。"},"schools":["advaita"],"works":[{"t":{"en":"Brahmasūtra-bhāṣya (Commentary on the Brahma Sūtra)","zh":"《梵经注》"},"y":720},{"t":{"en":"Upadeśasāhasrī (A Thousand Teachings)","zh":"《示教千则》"},"y":720}],"wiki":"Adi Shankara","c":"Raja Ravi Varma - Sankaracharya.jpg","portrait":{"w":600,"h":847,"v":"5625310164","author":"Raja Ravi Varma","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Raja_Ravi_Varma_-_Sankaracharya.jpg"},"focus":"30% 45%"},
  {"id":"jayarashi","tradition":"indian","born":770,"died":830,"life":{"en":"fl. c. 800","zh":"约活跃于公元800年前后"},"name":{"en":"Jayarāśi Bhaṭṭa","zh":"阇耶罗希·跋吒"},"role":{"en":"Radical sceptic who attacked every theory of valid knowledge","zh":"抨击一切有效认识理论的激进怀疑论者"},"idea":{"en":"He took each school’s definition of valid knowledge, perception included, and showed it to be incoherent, concluding that no means of knowledge can be established. He is linked to the Lokāyata tradition, though his scepticism goes beyond standard Cārvāka materialism.","zh":"他逐一检讨各派对有效认识的定义（包括感知），指出它们都自相矛盾，结论是没有任何认识手段能够成立。他通常被归入顺世论传统，但他的怀疑论比一般的顺世论唯物主义走得更远。"},"schools":["charvaka"],"works":[{"t":{"en":"Tattvopaplavasiṃha (The Lion that Devours All Categories)","zh":"《吞噬一切范畴之狮》"},"y":800}],"wiki":"Jayarāśi Bhaṭṭa"},
  {"id":"ramanuja","tradition":"indian","born":1017,"died":1137,"life":{"en":"traditionally 1017–1137","zh":"传统说法1017–1137年"},"name":{"en":"Rāmānuja","zh":"罗摩奴阇"},"role":{"en":"Vaiṣṇava theologian and founder of Viśiṣṭādvaita","zh":"毗湿奴派神学家，限定不二论的创立者"},"idea":{"en":"His ‘qualified non-dualism’ holds that Brahman is one but includes real souls and matter as its body; liberation is reaching God through devotion and surrender, not dissolving into featureless consciousness.","zh":"他的“限定不二论”认为：梵是一，但包含真实的灵魂与物质作为自己的身体；解脱是通过虔爱与皈依抵达神，而不是消融于无差别的意识。"},"schools":["theistic-vedanta"],"works":[{"t":{"en":"Śrībhāṣya (commentary on the Brahma Sūtra)","zh":"《吉祥注》（梵经注）"},"y":1100},{"t":{"en":"Vedārthasaṃgraha","zh":"《吠陀义摄》"},"y":1100}],"wiki":"Ramanuja"},
  {"id":"madhva","tradition":"indian","born":1238,"died":1317,"life":{"en":"traditionally 1238–1317","zh":"传统说法1238–1317年"},"name":{"en":"Madhva","zh":"摩陀婆"},"role":{"en":"Founder of Dvaita, the dualist school of Vedānta","zh":"吠檀多二元论派的创立者"},"idea":{"en":"He taught five eternal differences—between God and souls, God and matter, soul and soul, soul and matter, and one material thing and another—so the soul never becomes God, though in liberation it enjoys God’s presence.","zh":"他提出五种永恒差别——神与灵魂、神与物质、灵魂与灵魂、灵魂与物质、物质与物质之间——因此灵魂永远不会变成神，但在解脱中能享有与神同在的喜乐。"},"schools":["theistic-vedanta"],"works":[{"t":{"en":"Brahmasūtra-bhāṣya (commentary on the Brahma Sūtra)","zh":"《梵经注》"},"y":1280}],"wiki":"Madhvacharya"},
  {"id":"gangesha","tradition":"indian","born":1300,"died":1360,"life":{"en":"fl. 14th c., Mithilā","zh":"活跃于14世纪，弥提罗"},"name":{"en":"Gaṅgeśa Upādhyāya","zh":"甘吉沙"},"role":{"en":"Founder of Navya-Nyāya, the ‘new logic’","zh":"新正理派（“新逻辑”）的创始人"},"idea":{"en":"He reorganised Nyāya around the four means of knowledge and developed a precise technical language of relations and absences, used to define invariable concomitance (vyāpti) with new rigour.","zh":"他围绕四种量重组了正理学说，并发展出一套关于关系与“无”的精密技术语言，以前所未有的严格性来界定遍充。"},"schools":["nyaya"],"works":[{"t":{"en":"Tattvacintāmaṇi (Jewel of Reflection on Reality)","zh":"《真理如意珠》"},"y":1325}],"wiki":"Gangesha"},
  {"id":"vivekananda","tradition":"indian","born":1863,"died":1902,"life":{"en":"1863–1902","zh":"1863–1902年"},"name":{"en":"Swami Vivekananda","zh":"辨喜"},"role":{"en":"Monk who introduced Vedānta and yoga to the West","zh":"把吠檀多与瑜伽介绍到西方的僧人"},"idea":{"en":"A disciple of Ramakrishna, he presented Vedānta as a universal religion at the 1893 Parliament of the World’s Religions in Chicago, and taught that serving the poor is worshipping God in human form.","zh":"他是罗摩克里希纳的弟子，在1893年芝加哥世界宗教议会上把吠檀多介绍为一种普世宗教，并教导：服务穷人，就是敬奉化身为人的神。"},"schools":["neo-vedanta"],"works":[{"t":{"en":"Raja Yoga","zh":"《胜王瑜伽》"},"y":1896},{"t":{"en":"Karma Yoga","zh":"《业瑜伽》"},"y":1896}],"wiki":"Swami Vivekananda","c":"Swami Vivekananda-1893-09-signed.jpg","portrait":{"w":600,"h":824,"v":"823fcfdb0f","author":"The original uploader was Dziewa at English Wikipedia .","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Swami_Vivekananda-1893-09-signed.jpg"}},
  {"id":"gandhi","tradition":"indian","born":1869,"died":1948,"life":{"en":"1869–1948","zh":"1869–1948年"},"name":{"en":"Mohandas K. Gandhi","zh":"甘地"},"role":{"en":"Leader of Indian independence and theorist of non-violent resistance","zh":"印度独立运动领袖，非暴力抵抗的理论家"},"idea":{"en":"He developed satyagraha, ‘holding firmly to truth’: resisting injustice through non-violent non-cooperation and willingly accepted suffering, on the conviction that means shape ends and that truth is God.","zh":"他提出“坚持真理”（萨蒂亚格拉哈）：以非暴力的不合作和甘愿承受的苦难来抵抗不义，其信念是手段塑造目的，而真理即是神。"},"schools":[],"works":[{"t":{"en":"Hind Swaraj (Indian Home Rule)","zh":"《印度自治》"},"y":1909},{"t":{"en":"An Autobiography: The Story of My Experiments with Truth","zh":"《甘地自传：我对真理的实验》"},"y":1927}],"wiki":"Mahatma Gandhi","c":"Mahatma-Gandhi, studio, 1931.jpg","portrait":{"w":600,"h":749,"v":"86d45f98e5","author":"Elliott & Fry","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Mahatma-Gandhi,_studio,_1931.jpg"}},
  {"id":"aurobindo","tradition":"indian","born":1872,"died":1950,"life":{"en":"1872–1950","zh":"1872–1950年"},"name":{"en":"Sri Aurobindo","zh":"室利·阿罗频多"},"role":{"en":"Nationalist revolutionary turned philosopher of spiritual evolution","zh":"由民族主义革命者转为精神进化哲学家"},"idea":{"en":"After leading radical nationalism in Bengal he withdrew to Pondicherry and developed Integral Yoga: consciousness involved in matter is evolving toward a ‘supermind’ that will transform life on earth.","zh":"他曾领导孟加拉的激进民族主义运动，后隐居本地治里，发展出“整体瑜伽”：潜藏于物质中的意识正向“超心”进化，并将改变地上的生命。"},"schools":["neo-vedanta"],"works":[{"t":{"en":"The Life Divine","zh":"《神圣人生论》"},"y":1940}],"wiki":"Sri Aurobindo"},
  {"id":"ambedkar","tradition":"indian","born":1891,"died":1956,"life":{"en":"1891–1956","zh":"1891–1956年"},"name":{"en":"B. R. Ambedkar","zh":"安贝德卡尔"},"role":{"en":"Dalit leader, jurist and chief architect of India’s constitution","zh":"达利特（贱民）领袖、法学家、印度宪法的主要起草者"},"idea":{"en":"He argued that caste is a system of graded inequality sanctioned by Hindu scripture and must be annihilated, not reformed. In 1956 he converted to Buddhism with hundreds of thousands of followers, recasting it as a rational, social ethic (Navayana).","zh":"他认为种姓是一种由印度教经典认可的等级不平等制度，必须废除，而不是改良。1956年，他与数十万追随者一同皈依佛教，并把佛教重新诠释为一种理性的社会伦理（新乘佛教）。"},"schools":[],"works":[{"t":{"en":"Annihilation of Caste","zh":"《种姓的消灭》"},"y":1936},{"t":{"en":"The Buddha and His Dhamma","zh":"《佛陀及其正法》"},"y":1957}],"wiki":"B. R. Ambedkar"},
  {"id":"thales","tradition":"greek","born":-624,"died":-546,"life":{"en":"c. 624–546 BCE","zh":"约公元前624–前546年"},"name":{"en":"Thales","zh":"泰勒斯"},"role":{"en":"Sage of Miletus, traditionally the first Greek philosopher","zh":"米利都的贤者，传统上被视为第一位希腊哲学家"},"idea":{"en":"Taught that water is the origin of all things and that the world is “full of gods”, meaning nature is alive with its own powers. He wrote nothing; ancient reports credit him with geometry and with predicting an eclipse, usually dated to 585 BCE.","zh":"主张水是万物的本原，并说世界“充满了神”，意即自然自身就充满活力。他没有留下著作；古代记载称他精通几何，并预言了一次日食（通常定为公元前585年）。"},"schools":["milesian"],"works":[],"wiki":"Thales of Miletus"},
  {"id":"anaximander","tradition":"greek","born":-610,"died":-546,"life":{"en":"c. 610–546 BCE","zh":"约公元前610–前546年"},"name":{"en":"Anaximander","zh":"阿那克西曼德"},"role":{"en":"Thales’ successor, credited with the first Greek world map","zh":"泰勒斯的后继者，据说绘制了第一幅希腊世界地图"},"idea":{"en":"Argued that the origin cannot be any one element, which would overwhelm the others, but the apeiron, the boundless and indefinite. Opposites separate out of it and “pay penalty to one another for their injustice according to the order of time”.","zh":"认为本原不能是任何一种元素，否则它会压倒其他元素；本原应是“无定”（apeiron），即无界限、无规定之物。对立面从中分离出来，并“按照时间的秩序，为彼此的不义相互补偿”。"},"schools":["milesian"],"works":[{"t":{"en":"On Nature (one fragment survives)","zh":"《论自然》（仅存一则残篇）"},"y":-550}],"wiki":"Anaximander"},
  {"id":"anaximenes","tradition":"greek","born":-586,"died":-526,"life":{"en":"c. 586–526 BCE","zh":"约公元前586–前526年"},"name":{"en":"Anaximenes","zh":"阿那克西美尼"},"role":{"en":"Third Milesian, who made air the first principle","zh":"第三位米利都哲学家，以气为本原"},"idea":{"en":"Held that air is the basic stuff: rarefied it becomes fire, condensed it becomes wind, water, earth and stone. This gave a single mechanism, change of density, for how one stuff becomes many.","zh":"主张气是基本质料：气稀散则成火，凝聚则依次成为风、水、土和石头。这为“一种质料如何变成万物”提供了单一的机制——密度的变化。"},"schools":["milesian"],"works":[],"wiki":"Anaximenes of Miletus"},
  {"id":"pythagoras","tradition":"greek","born":-570,"died":-495,"life":{"en":"c. 570–495 BCE","zh":"约公元前570–前495年"},"name":{"en":"Pythagoras","zh":"毕达哥拉斯"},"role":{"en":"Founder of a philosophical and religious brotherhood at Croton","zh":"在克罗顿创立哲学兼宗教兄弟会的人"},"idea":{"en":"Taught the immortality and transmigration of the soul and a disciplined way of life; the idea that all things are number is attested for his followers. He wrote nothing, and layers of later legend make it hard to know what was his own.","zh":"教导灵魂不朽与轮回，以及一种严格自律的生活方式；“万物皆数”的观念见于他的追随者。他没有著作，后世传说层层叠加，很难确定哪些思想真正属于他本人。"},"schools":["pythagorean"],"works":[],"wiki":"Pythagoras"},
  {"id":"heraclitus","tradition":"greek","born":-535,"died":-475,"life":{"en":"c. 535–475 BCE","zh":"约公元前535–前475年"},"name":{"en":"Heraclitus","zh":"赫拉克利特"},"role":{"en":"Riddling sage of Ephesus who saw the world as ordered flux","zh":"以谜语般言辞著称的以弗所哲人，视世界为有序的流变"},"idea":{"en":"Taught that all things flow and that opposites are one, held together by the logos, a hidden rational order; “you cannot step into the same river twice” is a later paraphrase. Fire, ever-changing yet kept in measure, is his image of the cosmos.","zh":"教导万物流变、对立统一，由“逻各斯”——隐藏的理性秩序——维系在一起；“人不能两次踏进同一条河流”是后人的转述。永远变化却又守着分寸的火，是他心中宇宙的意象。"},"schools":[],"works":[{"t":{"en":"Book of sayings (fragments)","zh":"格言集（残篇）"},"y":-500}],"wiki":"Heraclitus"},
  {"id":"parmenides","tradition":"greek","born":-515,"died":-450,"life":{"en":"c. 515 – after 450 BCE","zh":"约公元前515–前450年后"},"name":{"en":"Parmenides","zh":"巴门尼德"},"role":{"en":"Founder of the Eleatic school and of deductive argument","zh":"埃利亚学派的创始人，演绎论证的开创者"},"idea":{"en":"In his poem a goddess reveals that only “what is” can be thought, so being is one, eternal, unchanging and whole. The “way of opinion”, full of change, is presented as deceptive.","zh":"在他的诗中，一位女神启示：只有“存在者”可以被思考，因此存在是一、永恒、不变、完整的。充满变化的“意见之路”则被视为虚幻。"},"schools":["eleatic"],"works":[{"t":{"en":"On Nature (poem)","zh":"《论自然》（诗）"},"y":-475}],"wiki":"Parmenides"},
  {"id":"anaxagoras","tradition":"greek","born":-500,"died":-428,"life":{"en":"c. 500–428 BCE","zh":"约公元前500–前428年"},"name":{"en":"Anaxagoras","zh":"阿那克萨戈拉"},"role":{"en":"First philosopher to settle in Athens; tried for impiety","zh":"第一位定居雅典的哲学家，曾因不敬神受审"},"idea":{"en":"Taught that everything contains a portion of everything, and that Mind (nous), unmixed and infinite, set the cosmos rotating. His claim that the sun is a fiery stone led to his prosecution.","zh":"主张万物之中都有万物的一份，而纯粹、无限的“心灵”（努斯）推动宇宙旋转。他声称太阳是一块燃烧的石头，因此遭到起诉。"},"schools":["pluralists"],"works":[{"t":{"en":"On Nature (fragments)","zh":"《论自然》（残篇）"},"y":-460}],"wiki":"Anaxagoras"},
  {"id":"empedocles","tradition":"greek","born":-494,"died":-434,"life":{"en":"c. 494–434 BCE","zh":"约公元前494–前434年"},"name":{"en":"Empedocles","zh":"恩培多克勒"},"role":{"en":"Sicilian poet, healer and statesman of the four roots","zh":"西西里的诗人、医者与政治家，提出“四根”说"},"idea":{"en":"Held that earth, water, air and fire are eternal “roots” that Love unites and Strife separates in an endless cosmic cycle. He also taught the transmigration of souls and abstention from killing animals.","zh":"认为土、水、气、火是永恒的“根”，在无尽的宇宙循环中由“爱”结合、由“争”分离。他还教导灵魂轮回，主张不杀动物。"},"schools":["pluralists"],"works":[{"t":{"en":"On Nature and Purifications (fragments)","zh":"《论自然》与《净化》（残篇）"},"y":-450}],"wiki":"Empedocles"},
  {"id":"zeno-elea","tradition":"greek","born":-490,"died":-430,"life":{"en":"c. 490–430 BCE","zh":"约公元前490–前430年"},"name":{"en":"Zeno of Elea","zh":"埃利亚的芝诺"},"role":{"en":"Parmenides’ pupil, famous for paradoxes of motion and plurality","zh":"巴门尼德的学生，以关于运动与多的悖论闻名"},"idea":{"en":"Defended Parmenides by showing that common-sense belief in motion and plurality leads to absurdities, as in Achilles and the Tortoise and the flying Arrow. His method, reductio ad absurdum, became a basic tool of philosophy.","zh":"为替巴门尼德辩护，他证明常识中对运动与多的信念会导出荒谬，例如“阿基里斯追乌龟”和“飞矢不动”。他所用的归谬法成为哲学的基本工具。"},"schools":["eleatic"],"works":[{"t":{"en":"Paradoxes (book lost; reported by Aristotle)","zh":"《悖论》（原书已佚，见于亚里士多德的转述）"},"y":-460}],"wiki":"Zeno of Elea"},
  {"id":"protagoras","tradition":"greek","born":-490,"died":-420,"life":{"en":"c. 490–420 BCE","zh":"约公元前490–前420年"},"name":{"en":"Protagoras","zh":"普罗泰戈拉"},"role":{"en":"The most famous sophist, who taught virtue for a fee","zh":"最著名的智者，收费传授德性"},"idea":{"en":"Declared that “man is the measure of all things”, so that things are for each person as they appear to that person. He was agnostic about the gods, saying the question is obscure and human life is short.","zh":"宣称“人是万物的尺度”，即事物对每个人来说就是它向那个人显现的样子。他对神持不可知论态度，说这个问题晦暗不明，而人生短暂。"},"schools":["sophists"],"works":[{"t":{"en":"Truth (lost)","zh":"《论真理》（已佚）"},"y":-440},{"t":{"en":"On the Gods (lost)","zh":"《论神》（已佚）"},"y":-440}],"wiki":"Protagoras"},
  {"id":"gorgias","tradition":"greek","born":-483,"died":-375,"life":{"en":"c. 483–375 BCE","zh":"约公元前483–前375年"},"name":{"en":"Gorgias","zh":"高尔吉亚"},"role":{"en":"Sicilian master of rhetoric and envoy to Athens","zh":"西西里的修辞大师，曾出使雅典"},"idea":{"en":"Argued, perhaps as a parody of Eleatic reasoning, that nothing exists, that if it did it could not be known, and that if known it could not be told. He compared speech to a powerful drug that works on the soul.","zh":"论证说（或许是在戏仿埃利亚学派的推理）：无物存在；即使存在也不可知；即使可知也无法言说。他把言辞比作一种作用于灵魂的强效药物。"},"schools":["sophists"],"works":[{"t":{"en":"On Non-Being","zh":"《论非存在》"},"y":-440},{"t":{"en":"Encomium of Helen","zh":"《海伦颂》"},"y":-415}],"wiki":"Gorgias"},
  {"id":"leucippus","tradition":"greek","born":-480,"died":-420,"life":{"en":"5th c. BCE","zh":"公元前5世纪"},"name":{"en":"Leucippus","zh":"留基伯"},"role":{"en":"Founder of atomism, about whom almost nothing is known","zh":"原子论的创始人，生平几乎无从知晓"},"idea":{"en":"Proposed that the world consists of indivisible atoms moving in the void, and that “nothing happens at random, but everything for a reason and by necessity”. Epicurus is reported to have doubted that he existed at all.","zh":"提出世界由在虚空中运动的不可分原子构成，并说“没有什么是偶然发生的，一切都有其理由并出于必然”。据说伊壁鸠鲁甚至怀疑他是否真实存在过。"},"schools":["atomism"],"works":[{"t":{"en":"The Great World-System (attributed, lost)","zh":"《大宇宙系统》（传为其作，已佚）"},"y":-440}],"wiki":"Leucippus"},
  {"id":"philolaus","tradition":"greek","born":-470,"died":-385,"life":{"en":"c. 470–385 BCE","zh":"约公元前470–前385年"},"name":{"en":"Philolaus","zh":"菲洛劳斯"},"role":{"en":"Pythagorean whose book first set out the school’s doctrines","zh":"毕达哥拉斯派哲学家，其著作首次系统阐述该派学说"},"idea":{"en":"Argued that the cosmos is made of “limiters” and “unlimiteds” fitted together by harmony, and that nothing can be known without number. He also moved the Earth from the centre of the cosmos, having it circle a central fire.","zh":"认为宇宙由“限定者”与“无限定者”构成，并由“和谐”结合在一起；没有数，就无法认识任何事物。他还把地球从宇宙中心移开，让它绕着一团“中心火”运行。"},"schools":["pythagorean"],"works":[{"t":{"en":"On Nature (fragments)","zh":"《论自然》（残篇）"},"y":-420}],"wiki":"Philolaus"},
  {"id":"socrates","tradition":"greek","born":-470,"died":-399,"life":{"en":"c. 470–399 BCE","zh":"约公元前470–前399年"},"name":{"en":"Socrates","zh":"苏格拉底"},"role":{"en":"Athenian questioner, executed for impiety in 399 BCE","zh":"雅典的诘问者，公元前399年以不敬神罪被处死"},"idea":{"en":"Claimed only to know that he knew nothing, and spent his life questioning Athenians about justice, courage and the good. He wrote nothing; his thought reaches us mainly through Plato’s dialogues, so the historical Socrates is hard to separate from Plato’s character.","zh":"自称唯一知道的是自己一无所知，一生都在向雅典人追问正义、勇敢与善。他没有留下任何著作，其思想主要通过柏拉图的对话录传下来，因此历史上的苏格拉底很难与柏拉图笔下的人物区分开。"},"schools":["socratic"],"works":[],"wiki":"Socrates","c":"Socrates Louvre.jpg","portrait":{"w":600,"h":800,"v":"1c96ce774e","author":"Copy of Lysippos (?)","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Socrates_Louvre.jpg"}},
  {"id":"democritus","tradition":"greek","born":-460,"died":-370,"life":{"en":"c. 460–370 BCE","zh":"约公元前460–前370年"},"name":{"en":"Democritus","zh":"德谟克利特"},"role":{"en":"The “laughing philosopher” of Abdera, who developed atomism","zh":"阿布德拉的“欢笑哲学家”，发展了原子论"},"idea":{"en":"Developed atomism into a full account of nature, perception and the soul: sense qualities exist “by convention”, while only atoms and void exist “in reality”. In ethics he prized cheerfulness (euthymia), a calm and well-ordered soul.","zh":"把原子论发展为对自然、感知与灵魂的完整解释：感官性质只是“约定”，“实际上”只有原子和虚空。在伦理上，他推崇“愉悦”（euthymia）——一种平静而有序的灵魂状态。"},"schools":["atomism"],"works":[{"t":{"en":"Fragments on ethics and nature","zh":"伦理与自然残篇"},"y":-400}],"wiki":"Democritus"},
  {"id":"antisthenes","tradition":"greek","born":-446,"died":-366,"life":{"en":"c. 446–366 BCE","zh":"约公元前446–前366年"},"name":{"en":"Antisthenes","zh":"安提斯泰尼"},"role":{"en":"Devoted follower of Socrates, later seen as the Cynics’ founder","zh":"苏格拉底的忠实追随者，后被视为犬儒派的开创者"},"idea":{"en":"Taught that virtue can be taught and is sufficient for happiness, needing nothing but “Socratic strength”. He prized toil and self-sufficiency over pleasure. His many writings are lost.","zh":"主张德性可以传授，且足以带来幸福，所需的只是“苏格拉底式的力量”。他重视辛劳与自足，而非快乐。他的大量著作均已失传。"},"schools":["cynicism"],"works":[],"wiki":"Antisthenes"},
  {"id":"plato","tradition":"greek","born":-428,"died":-348,"life":{"en":"c. 428–348 BCE","zh":"约公元前428–前348年"},"name":{"en":"Plato","zh":"柏拉图"},"role":{"en":"Socrates’ student, founder of the Academy, master of the dialogue","zh":"苏格拉底的学生，学园的创办者，对话体的大师"},"idea":{"en":"Argued that true knowledge is of eternal Forms, above all the Form of the Good, and that a just soul and a just city both need reason to rule. He wrote dialogues, so his own views must be read through his characters.","zh":"认为真正的知识是关于永恒理念的知识，首先是“善”的理念；正义的灵魂与正义的城邦都要求理性居于统治地位。他以对话体写作，因此他本人的观点需要透过人物去解读。"},"schools":["platonism"],"works":[{"t":{"en":"Republic","zh":"《理想国》"},"y":-375},{"t":{"en":"Symposium","zh":"《会饮篇》"},"y":-385},{"t":{"en":"Phaedo","zh":"《斐多篇》"},"y":-380}],"wiki":"Plato","c":"Plato Silanion Musei Capitolini MC1377.png","portrait":{"w":600,"h":900,"v":"2d6bb0e08f","author":"© Marie-Lan Nguyen / Wikimedia Commons","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Plato_Silanion_Musei_Capitolini_MC1377.png"}},
  {"id":"diogenes","tradition":"greek","born":-412,"died":-323,"life":{"en":"c. 412–323 BCE","zh":"约公元前412–前323年"},"name":{"en":"Diogenes of Sinope","zh":"锡诺普的第欧根尼"},"role":{"en":"Exile from Sinope who lived as a “dog” in Athens","zh":"来自锡诺普的流亡者，在雅典像“狗”一样生活"},"idea":{"en":"Lived out Cynic self-sufficiency in public, sleeping in a jar and, according to anecdote, telling Alexander the Great to stand out of his sunlight. Asked where he came from, he reportedly answered, “I am a citizen of the world.”","zh":"在大庭广众之下践行犬儒式的自足：睡在陶瓮里；据轶事记载，他曾让亚历山大大帝“别挡住我的阳光”。有人问他来自哪里，据说他回答：“我是世界公民。”"},"schools":["cynicism"],"works":[],"wiki":"Diogenes"},
  {"id":"aristotle","tradition":"greek","born":-384,"died":-322,"life":{"en":"384–322 BCE","zh":"公元前384–前322年"},"name":{"en":"Aristotle","zh":"亚里士多德"},"role":{"en":"Plato’s student, Alexander’s tutor, founder of the Lyceum","zh":"柏拉图的学生，亚历山大的老师，吕克昂学园的创办者"},"idea":{"en":"Brought Plato’s Forms down into things and founded formal logic, biology and the systematic study of ethics and politics. He held that humans are rational, political animals whose good is a life of virtuous activity.","zh":"把柏拉图的理念拉回事物之中，创立了形式逻辑、生物学，以及对伦理与政治的系统研究。他认为人是理性的、政治的动物，人的善在于一生合乎德性的活动。"},"schools":["aristotelianism"],"works":[{"t":{"en":"Nicomachean Ethics","zh":"《尼各马可伦理学》"},"y":-340},{"t":{"en":"Metaphysics","zh":"《形而上学》"},"y":-330},{"t":{"en":"Politics","zh":"《政治学》"},"y":-330}],"wiki":"Aristotle","c":"Aristotle Altemps Inv8575.jpg","portrait":{"w":600,"h":804,"v":"9d0c967f4b","author":"After Lysippos","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Aristotle_Altemps_Inv8575.jpg"}},
  {"id":"theophrastus","tradition":"greek","born":-371,"died":-287,"life":{"en":"c. 371–287 BCE","zh":"约公元前371–前287年"},"name":{"en":"Theophrastus","zh":"泰奥弗拉斯托斯"},"role":{"en":"Aristotle’s successor at the Lyceum and founder of botany","zh":"亚里士多德在吕克昂的继任者，植物学的奠基人"},"idea":{"en":"Extended Aristotle’s research programme to plants, stones and human types, while probing weak points in his teacher’s account of purpose in nature. His Characters sketches thirty kinds of flawed person.","zh":"把亚里士多德的研究纲领推广到植物、矿石与人的类型，同时探查老师关于自然目的之说的薄弱之处。他的《人物志》刻画了三十种有缺陷的人。"},"schools":["aristotelianism"],"works":[{"t":{"en":"Enquiry into Plants","zh":"《植物志》"},"y":-300},{"t":{"en":"Characters","zh":"《人物志》"},"y":-319}],"wiki":"Theophrastus"},
  {"id":"pyrrho","tradition":"greek","born":-360,"died":-270,"life":{"en":"c. 360–270 BCE","zh":"约公元前360–前270年"},"name":{"en":"Pyrrho","zh":"皮浪"},"role":{"en":"Founder of Pyrrhonian skepticism, who went to India with Alexander","zh":"皮浪怀疑主义的创始人，曾随亚历山大远征印度"},"idea":{"en":"Taught, according to his pupil Timon, that things are indifferent, unmeasurable and undecidable, so we should be without opinions and unshaken. Ancient sources say he met Indian “naked sages”; whether this shaped his views is debated.","zh":"据其学生蒂蒙记载，他教导说事物无差别、不可衡量、不可判定，因此我们应当不持意见、不为所动。古代资料说他见过印度的“裸体智者”，这是否影响了他的思想，学界仍有争议。"},"schools":["skepticism"],"works":[],"wiki":"Pyrrho"},
  {"id":"epicurus","tradition":"greek","born":-341,"died":-270,"life":{"en":"341–270 BCE","zh":"公元前341–前270年"},"name":{"en":"Epicurus","zh":"伊壁鸠鲁"},"role":{"en":"Founder of the Garden, a philosophical community near Athens","zh":"“花园”学派的创始人，在雅典郊外建立哲学团体"},"idea":{"en":"Taught that the good life is tranquil pleasure, reached by understanding that the world is atoms and void, that the gods do not punish, and that death is nothing to us. He valued friendship and simple food over fame and luxury.","zh":"教导美好的生活在于宁静的快乐：要明白世界由原子与虚空构成，神不会惩罚人，死亡与我们无关。他看重友谊与粗茶淡饭，而非名声与奢华。"},"schools":["epicureanism"],"works":[{"t":{"en":"Letter to Menoeceus","zh":"《致美诺寇的信》"},"y":-300},{"t":{"en":"Principal Doctrines","zh":"《基本要道》"},"y":-300}],"wiki":"Epicurus","c":"Epikouros BM 1843.jpg","portrait":{"w":600,"h":900,"v":"ec40e88ed2","author":"Unknown artist","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Epikouros_BM_1843.jpg"}},
  {"id":"zeno-citium","tradition":"greek","born":-334,"died":-262,"life":{"en":"c. 334–262 BCE","zh":"约公元前334–前262年"},"name":{"en":"Zeno of Citium","zh":"季蒂昂的芝诺"},"role":{"en":"Merchant from Cyprus who founded Stoicism in Athens","zh":"来自塞浦路斯的商人，在雅典创立斯多葛学派"},"idea":{"en":"Taught that happiness is a smoothly flowing life in agreement with nature, which is the same as living virtuously. His lost Republic imagined a community of the wise without temples, law courts or money.","zh":"教导幸福是一种与自然相一致、顺畅流动的生活，这与合乎德性的生活是同一回事。他已失传的《国家篇》设想了一个没有神庙、法庭与货币的智者共同体。"},"schools":["stoicism"],"works":[{"t":{"en":"Republic (lost)","zh":"《国家篇》（已佚）"},"y":-300}],"wiki":"Zeno of Citium"},
  {"id":"chrysippus","tradition":"greek","born":-279,"died":-206,"life":{"en":"c. 279–206 BCE","zh":"约公元前279–前206年"},"name":{"en":"Chrysippus","zh":"克吕西波"},"role":{"en":"Third head of the Stoa, its great systematiser and logician","zh":"斯多葛学派第三任领袖，该派伟大的体系化者与逻辑学家"},"idea":{"en":"Built Stoicism into a rigorous system, including an early propositional logic and a theory of fate compatible with moral responsibility. Ancients said, “Without Chrysippus there would be no Stoa.” Of his reported 700-plus books, only fragments survive.","zh":"把斯多葛主义构建成严密的体系，包括早期的命题逻辑，以及一种与道德责任相容的命运论。古人说：“没有克吕西波，就没有斯多葛。”据说他写了七百多卷书，如今只剩残篇。"},"schools":["stoicism"],"works":[],"wiki":"Chrysippus"},
  {"id":"cicero","tradition":"greek","born":-106,"died":-43,"life":{"en":"106–43 BCE","zh":"公元前106–前43年"},"name":{"en":"Cicero","zh":"西塞罗"},"role":{"en":"Roman orator and statesman who brought Greek philosophy into Latin","zh":"罗马演说家与政治家，把希腊哲学带入拉丁语世界"},"idea":{"en":"A follower of the sceptical Academy, he weighed Stoic, Epicurean and Academic views against each other and accepted what seemed most probable. He coined much of the Latin philosophical vocabulary Europe would use for centuries.","zh":"作为怀疑论学园派的追随者，他把斯多葛派、伊壁鸠鲁派与学园派的观点相互权衡，接受看起来最可信的部分。他创造了大量拉丁哲学词汇，欧洲沿用了许多个世纪。"},"schools":["skepticism"],"works":[{"t":{"en":"Academica","zh":"《学园派》"},"y":-45},{"t":{"en":"On the Nature of the Gods","zh":"《论神性》"},"y":-45},{"t":{"en":"On Duties","zh":"《论义务》"},"y":-44}],"wiki":"Cicero"},
  {"id":"lucretius","tradition":"greek","born":-99,"died":-55,"life":{"en":"c. 99–55 BCE","zh":"约公元前99–前55年"},"name":{"en":"Lucretius","zh":"卢克莱修"},"role":{"en":"Roman poet who set Epicurus’ philosophy in verse","zh":"以诗歌阐述伊壁鸠鲁哲学的罗马诗人"},"idea":{"en":"His Latin poem explains atoms, the “swerve” that allows free will, the mortality of the soul and the natural origin of civilisation, to free readers from fear of the gods and of death. Its rediscovery in 1417 helped spark early modern science.","zh":"他的拉丁长诗阐述了原子、使自由意志成为可能的“偏斜”、灵魂的可朽以及文明的自然起源，以帮助读者摆脱对神和死亡的恐惧。这部诗于1417年被重新发现，助燃了早期现代科学。"},"schools":["epicureanism"],"works":[{"t":{"en":"On the Nature of Things","zh":"《物性论》"},"y":-55}],"wiki":"Lucretius"},
  {"id":"seneca","tradition":"greek","born":-4,"died":65,"life":{"en":"c. 4 BCE – 65 CE","zh":"约公元前4年–公元65年"},"name":{"en":"Seneca","zh":"塞涅卡"},"role":{"en":"Roman statesman, playwright and tutor to Nero","zh":"罗马政治家、剧作家，尼禄的老师"},"idea":{"en":"Wrote practical Stoic ethics on anger, grief and the use of time, insisting that philosophy is training for life, not cleverness. Ordered by Nero to kill himself, he died, by ancient accounts, with Stoic composure.","zh":"撰写关于愤怒、悲伤与时间运用的实践性斯多葛伦理，坚持哲学是为生活而进行的训练，而非卖弄聪明。他被尼禄下令自尽；据古代记载，他死时保持着斯多葛式的从容。"},"schools":["stoicism"],"works":[{"t":{"en":"Letters to Lucilius","zh":"《致鲁基里乌斯的道德书简》"},"y":65},{"t":{"en":"On the Shortness of Life","zh":"《论生命之短暂》"},"y":49}],"wiki":"Seneca the Younger"},
  {"id":"epictetus","tradition":"greek","born":50,"died":135,"life":{"en":"c. 50–135","zh":"约50–135年"},"name":{"en":"Epictetus","zh":"爱比克泰德"},"role":{"en":"Freed slave who taught Stoicism at Nicopolis","zh":"获释的奴隶，在尼科波利斯讲授斯多葛哲学"},"idea":{"en":"Taught that some things are up to us, namely our judgements, desires and choices, and everything else is not; we are disturbed not by events but by our opinions about them. He wrote nothing himself; his student Arrian recorded his lectures.","zh":"教导有些事取决于我们——我们的判断、欲望与选择——其余一切都不取决于我们；困扰人的不是事情本身，而是我们对事情的看法。他本人没有写作，其讲课由学生阿里安记录下来。"},"schools":["stoicism"],"works":[{"t":{"en":"Discourses (recorded by Arrian)","zh":"《论说集》（阿里安记录）"},"y":108},{"t":{"en":"Enchiridion","zh":"《道德手册》"},"y":125}],"wiki":"Epictetus"},
  {"id":"marcus-aurelius","tradition":"greek","born":121,"died":180,"life":{"en":"121–180","zh":"121–180年"},"name":{"en":"Marcus Aurelius","zh":"马可·奥勒留"},"role":{"en":"Roman emperor who wrote Stoic notes to himself","zh":"罗马皇帝，写下给自己的斯多葛式札记"},"idea":{"en":"In private notes, partly written on military campaigns, he reminded himself to accept fate, do his duty to the human community and remember that everything is fleeting. They show Stoicism as daily self-examination rather than theory.","zh":"他在部分写于军旅途中的私人札记里提醒自己：接受命运，履行对人类共同体的责任，记住一切都转瞬即逝。这些札记展示的斯多葛主义是一种日常的自我省察，而非一套理论。"},"schools":["stoicism"],"works":[{"t":{"en":"Meditations","zh":"《沉思录》"},"y":175}],"wiki":"Marcus Aurelius"},
  {"id":"sextus-empiricus","tradition":"greek","born":160,"died":210,"life":{"en":"fl. c. 200 CE","zh":"约公元200年前后在世"},"name":{"en":"Sextus Empiricus","zh":"塞克斯都·恩披里柯"},"role":{"en":"Physician whose books are our main source for ancient skepticism","zh":"医生，其著作是我们了解古代怀疑主义的主要来源"},"idea":{"en":"Collected the “modes” that lead to suspension of judgement, such as conflicting appearances and the problem that every proof needs a further proof. He presented skepticism not as a doctrine but as an ability and a way of life.","zh":"汇集了导向悬置判断的各种“论式”，例如现象相互冲突、每个证明都需要进一步证明等。他把怀疑主义呈现为一种能力和生活方式，而非一种学说。"},"schools":["skepticism"],"works":[{"t":{"en":"Outlines of Pyrrhonism","zh":"《皮浪学说概要》"},"y":200},{"t":{"en":"Against the Mathematicians","zh":"《反数学家》"},"y":200}],"wiki":"Sextus Empiricus"},
  {"id":"plotinus","tradition":"greek","born":204,"died":270,"life":{"en":"c. 204–270","zh":"约204–270年"},"name":{"en":"Plotinus","zh":"普罗提诺"},"role":{"en":"Founder of Neoplatonism, teaching in Rome","zh":"新柏拉图主义的创始人，在罗马讲学"},"idea":{"en":"Described reality as emanating from the One through Intellect and Soul, and the philosophical life as the soul’s inward ascent to union with its source. Porphyry reports that he experienced such union several times.","zh":"把实在描述为从太一经由理智与灵魂流溢而出，把哲学生活视为灵魂向内上升、与其源头合一的过程。据波菲利记载，他曾数次体验到这种合一。"},"schools":["neoplatonism"],"works":[{"t":{"en":"Enneads (edited by Porphyry)","zh":"《九章集》（波菲利编订）"},"y":270}],"wiki":"Plotinus"},
  {"id":"porphyry","tradition":"greek","born":234,"died":305,"life":{"en":"c. 234–305","zh":"约234–305年"},"name":{"en":"Porphyry","zh":"波菲利"},"role":{"en":"Plotinus’ student, editor and biographer","zh":"普罗提诺的学生、编者与传记作者"},"idea":{"en":"Edited Plotinus’ Enneads and wrote the Isagoge, an introduction to Aristotle’s logic that posed the medieval problem of universals: do genera and species really exist? He also wrote a polemic against the Christians that was later burned.","zh":"编订了普罗提诺的《九章集》，并写了《导论》——一部亚里士多德逻辑学入门，它提出了中世纪的“共相问题”：属和种真的存在吗？他还写过一部反对基督徒的论战著作，后被焚毁。"},"schools":["neoplatonism"],"works":[{"t":{"en":"Isagoge","zh":"《导论》"},"y":270},{"t":{"en":"Life of Plotinus","zh":"《普罗提诺传》"},"y":301}],"wiki":"Porphyry (philosopher)"},
  {"id":"hypatia","tradition":"greek","born":360,"died":415,"life":{"en":"c. 360–415","zh":"约360–415年"},"name":{"en":"Hypatia","zh":"希帕提娅"},"role":{"en":"Mathematician and Neoplatonist teacher in Alexandria","zh":"亚历山大里亚的数学家与新柏拉图主义教师"},"idea":{"en":"Taught Platonic philosophy, astronomy and mathematics to pagan and Christian students alike and was a respected public figure. She was murdered by a Christian mob in 415 amid a political feud; none of her writings survives with certainty.","zh":"向异教徒与基督徒学生讲授柏拉图哲学、天文学与数学，是受人尊敬的公众人物。415年，在一场政治纷争中，她被一群基督徒暴民杀害；她的著作没有一部能确定地流传下来。"},"schools":["neoplatonism"],"works":[],"wiki":"Hypatia"},
  {"id":"proclus","tradition":"greek","born":412,"died":485,"life":{"en":"412–485","zh":"412–485年"},"name":{"en":"Proclus","zh":"普罗克洛"},"role":{"en":"Head of the Platonic school in Athens and Neoplatonism’s great systematiser","zh":"雅典柏拉图学派的领袖，新柏拉图主义伟大的体系化者"},"idea":{"en":"Organised Neoplatonism into a deductive system of 211 propositions, in which every effect remains in, proceeds from and returns to its cause. Through Pseudo-Dionysius and the Arabic Book of Causes he shaped medieval theology.","zh":"把新柏拉图主义整理成由211个命题构成的演绎体系，其中每个结果都“停留于”、“出离于”并“回归于”它的原因。经由伪狄奥尼修斯和阿拉伯文的《原因之书》，他塑造了中世纪神学。"},"schools":["neoplatonism"],"works":[{"t":{"en":"Elements of Theology","zh":"《神学要素》"},"y":450},{"t":{"en":"Platonic Theology","zh":"《柏拉图神学》"},"y":460}],"wiki":"Proclus"},
  {"id":"al-kindi","tradition":"islamic","born":801,"died":873,"life":{"en":"c. 801–873","zh":"约801–873年"},"name":{"en":"Al-Kindī","zh":"铿迪"},"role":{"en":"Baghdad polymath called “the philosopher of the Arabs”","zh":"巴格达的博学家，被称为“阿拉伯人的哲学家”"},"idea":{"en":"Truth should be welcomed whatever its source, even foreign nations; philosophy and prophecy agree, and the world was created in time by the One, the true cause.","zh":"无论真理来自何处，哪怕来自异族，都应当接受；哲学与先知启示相一致，世界由真正的原因“太一”在时间中创造。"},"schools":["falsafa"],"works":[{"t":{"en":"On First Philosophy","zh":"《论第一哲学》"},"y":840}],"wiki":"Al-Kindi"},
  {"id":"al-farabi","tradition":"islamic","born":870,"died":950,"life":{"en":"c. 870–950","zh":"约870–950年"},"name":{"en":"Al-Fārābī","zh":"法拉比"},"role":{"en":"Logician called the “Second Teacher” after Aristotle","zh":"继亚里士多德之后被称为“第二导师”的逻辑学家"},"idea":{"en":"The ideal city is ruled by a philosopher-prophet who grasps the truth by reason and conveys it to the people in images; religion is philosophy expressed in symbols.","zh":"理想城邦由哲学家兼先知统治，他以理性把握真理，再以形象传达给民众；宗教是以象征表达的哲学。"},"schools":["falsafa"],"works":[{"t":{"en":"The Enumeration of the Sciences","zh":"《科学纲要》"},"y":930},{"t":{"en":"The Opinions of the People of the Virtuous City","zh":"《美德城邦居民意见书》"},"y":942}],"wiki":"Al-Farabi","c":"Alpharabius in Liber Chronicarum 1493 AD.png","portrait":{"w":600,"h":618,"v":"738b2b0184","author":"Mr.Nostalgic","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Alpharabius_in_Liber_Chronicarum_1493_AD.png"}},
  {"id":"al-ashari","tradition":"islamic","born":874,"died":936,"life":{"en":"c. 874–936","zh":"约874–936年"},"name":{"en":"Abū al-Ḥasan al-Ashʿarī","zh":"艾布·哈桑·艾什尔里"},"role":{"en":"Muʿtazili theologian who broke with his school around 912","zh":"约912年脱离本派的穆尔太齐赖派神学家"},"idea":{"en":"God’s power and will are unlimited: God creates every act, humans only “acquire” them, and good and evil are what God commands and forbids. He used rational argument to defend traditional beliefs.","zh":"真主的权能与意志没有限制：真主创造一切行为，人只是“获取”它们；善恶就是真主所命令与禁止的。他用理性论证来捍卫传统信仰。"},"schools":["kalam"],"works":[{"t":{"en":"Doctrines of the Muslims (Maqālāt al-Islāmiyyīn)","zh":"《伊斯兰教派言论集》"},"y":920},{"t":{"en":"Elucidation of the Principles of Religion (al-Ibāna)","zh":"《宗教原理阐释》"},"y":925}],"wiki":"Abu al-Hasan al-Ash'ari"},
  {"id":"ibn-sina","tradition":"islamic","born":980,"died":1037,"life":{"en":"980–1037","zh":"980–1037年"},"name":{"en":"Ibn Sīnā (Avicenna)","zh":"伊本·西那（阿维森纳）"},"role":{"en":"Persian physician-philosopher, the most influential Islamic philosopher","zh":"波斯医生兼哲学家，影响最大的伊斯兰哲学家"},"idea":{"en":"Essence and existence are distinct: knowing what a thing is does not tell you that it is, so all contingent things need a Necessary Existent. His “floating man”, suspended without any sensation, still knows that he exists.","zh":"本质与存在相区分：知道一物是什么，并不意味着知道它存在，因此一切偶然之物都需要一个必然存在者。他设想的“飘浮人”在没有任何感觉的状态下，依然知道自己存在。"},"schools":["falsafa"],"works":[{"t":{"en":"The Canon of Medicine","zh":"《医典》"},"y":1025},{"t":{"en":"The Book of Healing (al-Shifāʾ)","zh":"《治疗论》"},"y":1027},{"t":{"en":"Pointers and Reminders","zh":"《指要与诠释》"},"y":1030}],"wiki":"Avicenna","c":"Avicenna Bust, left profile (cropped).jpg","portrait":{"w":600,"h":774,"v":"887c4adcdc","author":"National Library of Medicine","license":"No restrictions","licenseUrl":"https://www.flickr.com/commons/usage/","page":"https://commons.wikimedia.org/wiki/File:Avicenna_Bust,_left_profile_(cropped).jpg"}},
  {"id":"al-ghazali","tradition":"islamic","born":1058,"died":1111,"life":{"en":"c. 1058–1111","zh":"约1058–1111年"},"name":{"en":"Al-Ghazālī","zh":"安萨里"},"role":{"en":"Ashʿarite theologian who left his Baghdad chair for Sufism","zh":"辞去巴格达教席、转向苏非之道的艾什尔里派神学家"},"idea":{"en":"The philosophers fail to prove their own claims, such as the eternity of the world; fire does not burn cotton by necessity, God creates the burning. Certainty finally came to him not from argument but from Sufi experience.","zh":"哲学家们未能证明自己的主张，例如世界永恒；火并非必然地烧着棉花，是真主创造了燃烧。最终给他确定性的不是论证，而是苏非体验。"},"schools":["kalam","sufism"],"works":[{"t":{"en":"The Incoherence of the Philosophers","zh":"《哲学家的矛盾》"},"y":1095},{"t":{"en":"The Revival of the Religious Sciences","zh":"《宗教学科的复兴》"},"y":1100},{"t":{"en":"Deliverance from Error","zh":"《摆脱迷误》"},"y":1108}],"wiki":"Al-Ghazali"},
  {"id":"ibn-tufayl","tradition":"islamic","born":1105,"died":1185,"life":{"en":"c. 1105–1185","zh":"约1105–1185年"},"name":{"en":"Ibn Ṭufayl","zh":"伊本·图斐利"},"role":{"en":"Andalusian court physician and philosophical novelist","zh":"安达卢斯宫廷医生，哲理小说作者"},"idea":{"en":"In his novel, a child raised alone on an island reaches by reason and contemplation the same truths that religion teaches in symbols.","zh":"在他的小说中，一个在荒岛上独自长大的孩子，仅凭理性与沉思，就领悟了宗教以象征教导的同样真理。"},"schools":["falsafa"],"works":[{"t":{"en":"Ḥayy ibn Yaqẓān","zh":"《哈伊·本·叶格赞》"},"y":1175}],"wiki":"Ibn Tufail"},
  {"id":"ibn-rushd","tradition":"islamic","born":1126,"died":1198,"life":{"en":"1126–1198","zh":"1126–1198年"},"name":{"en":"Ibn Rushd (Averroes)","zh":"伊本·鲁世德（阿威罗伊）"},"role":{"en":"Córdoban judge, known in Europe simply as “the Commentator”","zh":"科尔多瓦法官，在欧洲被直接称为“评注家”"},"idea":{"en":"The Qur’an itself commands philosophical study, and where demonstration conflicts with the literal text, the text must be interpreted. He defended Aristotle against al-Ghazālī and against Avicenna’s Neoplatonic additions.","zh":"《古兰经》本身就要求人研究哲学；当证明与经文字面意义冲突时，应当对经文加以诠释。他为亚里士多德辩护，既反驳安萨里，也反对阿维森纳添加的新柏拉图主义成分。"},"schools":["falsafa"],"works":[{"t":{"en":"The Decisive Treatise","zh":"《决定性论述》"},"y":1179},{"t":{"en":"The Incoherence of the Incoherence","zh":"《矛盾的矛盾》"},"y":1180},{"t":{"en":"Long Commentary on Aristotle’s On the Soul","zh":"《亚里士多德〈论灵魂〉详注》"},"y":1190}],"wiki":"Averroes","c":"Andrea di bonaiuto, apoteosi di san tommaso d'aquino, 11 averroè.jpg","portrait":{"w":600,"h":647,"v":"d3c9c6fa92","author":"Sailko","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","page":"https://commons.wikimedia.org/wiki/File:Andrea_di_bonaiuto,_apoteosi_di_san_tommaso_d%27aquino,_11_averro%C3%A8.jpg"}},
  {"id":"suhrawardi","tradition":"islamic","born":1154,"died":1191,"life":{"en":"1154–1191","zh":"1154–1191年"},"name":{"en":"Shihāb al-Dīn Suhrawardī","zh":"希哈布丁·苏赫拉瓦迪"},"role":{"en":"Persian founder of Illuminationism, executed in Aleppo","zh":"照明学派的波斯创始人，在阿勒颇被处死"},"idea":{"en":"Reality is light in degrees of intensity, from the Light of Lights down to darkness; the self knows itself by direct presence, not through definitions, which the Peripatetics wrongly relied on.","zh":"实在是强度不同的光，从“众光之光”一直到黑暗；自我凭借直接临在认识自身，而不是靠定义，逍遥学派对定义的依赖是错误的。"},"schools":["illuminationism"],"works":[{"t":{"en":"The Philosophy of Illumination (Ḥikmat al-Ishrāq)","zh":"《照明哲学》"},"y":1186}],"wiki":"Shahab al-Din Yahya ibn Habash Suhrawardi"},
  {"id":"ibn-arabi","tradition":"islamic","born":1165,"died":1240,"life":{"en":"1165–1240","zh":"1165–1240年"},"name":{"en":"Ibn ʿArabī","zh":"伊本·阿拉比"},"role":{"en":"Andalusian mystic, called “the Greatest Master” by followers","zh":"安达卢斯神秘主义者，被追随者尊为“最伟大的导师”"},"idea":{"en":"God alone truly exists; the world is God’s continual self-disclosure, and each thing shows a divine name. The “Perfect Human” is the mirror in which God’s names are fully reflected.","zh":"唯有真主真正存在；世界是真主持续不断的自我显现，每一物都显示一个神圣之名。“完人”是完整映现真主诸名的镜子。"},"schools":["sufism"],"works":[{"t":{"en":"The Bezels of Wisdom (Fuṣūṣ al-Ḥikam)","zh":"《智慧的珍宝》"},"y":1229},{"t":{"en":"The Meccan Revelations","zh":"《麦加启示》"},"y":1231}],"wiki":"Ibn Arabi"},
  {"id":"rumi","tradition":"islamic","born":1207,"died":1273,"life":{"en":"1207–1273","zh":"1207–1273年"},"name":{"en":"Jalāl al-Dīn Rūmī","zh":"贾拉鲁丁·鲁米"},"role":{"en":"Persian poet and Sufi teacher in Konya","zh":"在科尼亚讲学的波斯诗人与苏非导师"},"idea":{"en":"The soul is a reed cut from its reed-bed and longs to return; love, not reason alone, is the way back to God.","zh":"灵魂像一支从芦苇丛中被割下的芦笛，渴望回到原处；通往真主的道路是爱，而不仅仅是理性。"},"schools":["sufism"],"works":[{"t":{"en":"Dīwān-e Shams-e Tabrīzī","zh":"《沙姆斯诗集》"},"y":1250},{"t":{"en":"Masnavi","zh":"《玛斯纳维》"},"y":1273}],"wiki":"Rumi"},
  {"id":"ibn-khaldun","tradition":"islamic","born":1332,"died":1406,"life":{"en":"1332–1406","zh":"1332–1406年"},"name":{"en":"Ibn Khaldūn","zh":"伊本·赫勒敦"},"role":{"en":"North African historian and judge, founder of a science of society","zh":"北非历史学家与法官，社会科学的开创者"},"idea":{"en":"Dynasties rise and fall in cycles driven by ʿaṣabiyya, group solidarity, which is strong among hardy desert peoples and decays in luxurious cities. History needs a science of human society to judge which reports are even possible.","zh":"王朝以周期兴衰，推动力是“群体凝聚力”：它在坚韧的游牧民中强大，在奢华的城市中衰败。历史需要一门关于人类社会的科学，来判断哪些记载根本可能发生。"},"schools":[],"works":[{"t":{"en":"The Muqaddimah","zh":"《历史绪论》"},"y":1377}],"wiki":"Ibn Khaldun"},
  {"id":"mulla-sadra","tradition":"islamic","born":1571,"died":1640,"life":{"en":"c. 1571–1640","zh":"约1571–1640年"},"name":{"en":"Mullā Ṣadrā","zh":"穆拉·萨德拉"},"role":{"en":"Safavid philosopher of Shiraz, founder of Transcendent Theosophy","zh":"萨法维王朝设拉子的哲学家，超验神智学的创立者"},"idea":{"en":"Existence, not essence, is what is real; it is one reality in many degrees. Things change in their very substance, so the whole world is in constant motion toward perfection.","zh":"真实的是存在而非本质；存在是一个实在，却有许多等级。事物在实体本身中变化，因此整个世界都在不断朝向完满运动。"},"schools":["illuminationism"],"works":[{"t":{"en":"The Four Journeys (al-Asfār al-Arbaʿa)","zh":"《心灵四旅》"},"y":1628}],"wiki":"Mulla Sadra"},
  {"id":"augustine","tradition":"medieval","born":354,"died":430,"life":{"en":"354–430","zh":"354–430年"},"name":{"en":"Augustine of Hippo","zh":"希波的奥古斯丁"},"role":{"en":"North African bishop who fused Christianity with Platonism","zh":"把基督教与柏拉图主义融为一体的北非主教"},"idea":{"en":"Evil is a privation of good, freely chosen by a will turned away from God; we find truth by turning inward, where God illuminates the mind.","zh":"恶是善的缺乏，源于背离上帝的自由意志；我们转向内心才能找到真理，在那里上帝照亮心灵。"},"schools":["patristic"],"works":[{"t":{"en":"Confessions","zh":"《忏悔录》"},"y":400},{"t":{"en":"On the Trinity","zh":"《论三位一体》"},"y":417},{"t":{"en":"The City of God","zh":"《上帝之城》"},"y":426}],"wiki":"Augustine of Hippo","c":"Saint Augustine by Philippe de Champaigne.jpg","portrait":{"w":600,"h":766,"v":"693186f2c6","author":"Philippe de Champaigne","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Saint_Augustine_by_Philippe_de_Champaigne.jpg"}},
  {"id":"boethius","tradition":"medieval","born":480,"died":524,"life":{"en":"c. 480–524","zh":"约480–524年"},"name":{"en":"Boethius","zh":"波爱修斯"},"role":{"en":"Roman statesman who translated Aristotle’s logic into Latin","zh":"把亚里士多德逻辑译成拉丁文的罗马政治家"},"idea":{"en":"God’s foreknowledge does not destroy free will, because God is eternal and sees all times at once, as a present. He also posed the medieval problem of universals.","zh":"上帝的预知并不取消自由意志，因为上帝是永恒的，把一切时间当作当下一并看见。他还提出了贯穿中世纪的共相问题。"},"schools":["patristic"],"works":[{"t":{"en":"Commentaries on Porphyry’s Isagoge","zh":"《波菲利〈导论〉注》"},"y":510},{"t":{"en":"The Consolation of Philosophy","zh":"《哲学的慰藉》"},"y":524}],"wiki":"Boethius"},
  {"id":"saadia","tradition":"medieval","born":882,"died":942,"life":{"en":"882–942","zh":"882–942年"},"name":{"en":"Saadia Gaon","zh":"萨阿迪亚·加昂"},"role":{"en":"Egyptian-born head of the Sura academy in Babylonia","zh":"生于埃及、执掌巴比伦苏拉经学院的学者"},"idea":{"en":"There are four sources of knowledge: the senses, reason, inference and reliable tradition. Revelation teaches what reason could eventually discover, so that everyone can have the truth at once.","zh":"知识有四个来源：感官、理性、推论和可靠的传统。启示所教的，理性终究也能发现；启示的作用是让所有人立刻拥有真理。"},"schools":["jewish-medieval"],"works":[{"t":{"en":"Arabic translation of the Torah (Tafsīr)","zh":"《托拉》阿拉伯文译注"},"y":920},{"t":{"en":"The Book of Beliefs and Opinions","zh":"《信仰与见解之书》"},"y":933}],"wiki":"Saadia Gaon"},
  {"id":"anselm","tradition":"medieval","born":1033,"died":1109,"life":{"en":"1033–1109","zh":"1033–1109年"},"name":{"en":"Anselm of Canterbury","zh":"坎特伯雷的安瑟伦"},"role":{"en":"Benedictine monk and Archbishop of Canterbury","zh":"本笃会修士，坎特伯雷大主教"},"idea":{"en":"Faith seeks understanding. God is “that than which nothing greater can be conceived”, and such a being must exist in reality, not only in the mind: the ontological argument.","zh":"信仰寻求理解。上帝是“无法设想比之更伟大者”，这样的存在者不能只存在于心灵中，必定也实际存在：这就是本体论证明。"},"schools":["scholasticism"],"works":[{"t":{"en":"Monologion","zh":"《独白》"},"y":1076},{"t":{"en":"Proslogion","zh":"《宣讲》"},"y":1078},{"t":{"en":"Why God Became Man (Cur Deus Homo)","zh":"《上帝为何成为人》"},"y":1098}],"wiki":"Anselm of Canterbury"},
  {"id":"abelard","tradition":"medieval","born":1079,"died":1142,"life":{"en":"1079–1142","zh":"1079–1142年"},"name":{"en":"Peter Abelard","zh":"彼得·阿伯拉尔"},"role":{"en":"Paris logician famed for his dialectic and his love for Héloïse","zh":"以辩证法和与爱洛伊丝的爱情闻名的巴黎逻辑学家"},"idea":{"en":"Universals are neither things nor mere sounds but words insofar as they signify; in ethics, what makes an act sinful is the intention behind it.","zh":"共相既不是事物，也不只是声音，而是就其有所指称而言的语词；在伦理上，使行为成为罪的是背后的意图。"},"schools":["scholasticism"],"works":[{"t":{"en":"Sic et Non (Yes and No)","zh":"《是与否》"},"y":1121},{"t":{"en":"Ethics, or Know Thyself","zh":"《伦理学：认识你自己》"},"y":1138}],"wiki":"Peter Abelard"},
  {"id":"maimonides","tradition":"medieval","born":1138,"died":1204,"life":{"en":"1138–1204","zh":"1138–1204年"},"name":{"en":"Maimonides (Moses ben Maimon)","zh":"迈蒙尼德"},"role":{"en":"Rabbi, physician and philosopher from Córdoba, later in Cairo","zh":"生于科尔多瓦、后居开罗的拉比、医生与哲学家"},"idea":{"en":"God can only be described negatively; biblical images of God are figures for the unlearned. Reason cannot prove whether the world is eternal or created, so on that question one may follow scripture.","zh":"上帝只能以否定方式描述；《圣经》中关于上帝的形象是为未受教育者设的比喻。理性无法证明世界是永恒的还是被创造的，因此在这个问题上可以依从经典。"},"schools":["jewish-medieval"],"works":[{"t":{"en":"Mishneh Torah","zh":"《重述托拉》"},"y":1180},{"t":{"en":"The Guide for the Perplexed","zh":"《迷途指津》"},"y":1190}],"wiki":"Maimonides"},
  {"id":"aquinas","tradition":"medieval","born":1225,"died":1274,"life":{"en":"1225–1274","zh":"1225–1274年"},"name":{"en":"Thomas Aquinas","zh":"托马斯·阿奎那"},"role":{"en":"Dominican friar who wove Aristotle into Christian theology","zh":"把亚里士多德编织进基督教神学的多明我会修士"},"idea":{"en":"Reason and faith are two roads to one truth: reason can prove that God exists, through the “five ways”, while revelation adds what reason cannot reach. In every creature, its essence is distinct from its act of existing; only in God are they one.","zh":"理性与信仰是通往同一真理的两条道路：理性可以通过“五路论证”证明上帝存在，启示则补充理性无法企及的内容。在一切受造物中，本质与存在相区别，唯有在上帝中二者合一。"},"schools":["scholasticism"],"works":[{"t":{"en":"On Being and Essence","zh":"《论存在者与本质》"},"y":1255},{"t":{"en":"Summa contra Gentiles","zh":"《反异教大全》"},"y":1265},{"t":{"en":"Summa Theologiae","zh":"《神学大全》"},"y":1273}],"wiki":"Thomas Aquinas","c":"St-thomas-aquinasFXD.jpg","portrait":{"w":600,"h":900,"v":"34de5a0a92","author":"Carlo Crivelli","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:St-thomas-aquinasFXD.jpg"}},
  {"id":"siger","tradition":"medieval","born":1240,"died":1284,"life":{"en":"c. 1240–c. 1284","zh":"约1240–约1284年"},"name":{"en":"Siger of Brabant","zh":"布拉班特的西格尔"},"role":{"en":"Radical Aristotelian master at the Paris arts faculty","zh":"巴黎艺学院的激进亚里士多德主义教师"},"idea":{"en":"Following Averroes, he argued that Aristotle’s principles imply one intellect for all humans and an eternal world, while professing that faith teaches otherwise. Dante placed him in Paradise beside Aquinas, his critic.","zh":"他追随阿威罗伊，认为亚里士多德的原理意味着全人类共享一个理智、世界是永恒的，同时声明信仰的教导与此不同。但丁把他安置在天堂，与批评他的阿奎那并列。"},"schools":["latin-averroism"],"works":[{"t":{"en":"Questions on the Third Book of On the Soul","zh":"《〈论灵魂〉第三卷问题集》"},"y":1269},{"t":{"en":"On the Intellective Soul","zh":"《论理智灵魂》"},"y":1273}],"wiki":"Siger of Brabant"},
  {"id":"duns-scotus","tradition":"medieval","born":1266,"died":1308,"life":{"en":"c. 1266–1308","zh":"约1266–1308年"},"name":{"en":"John Duns Scotus","zh":"约翰·邓斯·司各脱"},"role":{"en":"Franciscan theologian, the “Subtle Doctor”","zh":"方济各会神学家，人称“精微博士”"},"idea":{"en":"“Being” means the same thing when said of God and of creatures, so we can reason about God; each individual is made itself by a unique “thisness” (haecceity), and the will is freer and higher than the intellect.","zh":"“存在”用于上帝和受造物时意义相同，因此我们能对上帝进行推理；每个个体凭借独一无二的“此性”成为它自己；意志比理智更自由、更高。"},"schools":["scholasticism"],"works":[{"t":{"en":"Ordinatio","zh":"《〈箴言集〉评注》"},"y":1300},{"t":{"en":"Treatise on the First Principle","zh":"《论第一原理》"},"y":1305}],"wiki":"Duns Scotus"},
  {"id":"ockham","tradition":"medieval","born":1287,"died":1347,"life":{"en":"c. 1287–1347","zh":"约1287–1347年"},"name":{"en":"William of Ockham","zh":"奥卡姆的威廉"},"role":{"en":"English Franciscan logician who defied the pope","zh":"敢于对抗教宗的英格兰方济各会逻辑学家"},"idea":{"en":"Only individuals exist; universals are concepts that signify many individuals. Do not posit more entities than you need, the principle later called “Ockham’s razor”.","zh":"只有个体存在；共相是指称多个个体的概念。不要设定超出需要的实体，这一原则后来被称为“奥卡姆剃刀”。"},"schools":["nominalism"],"works":[{"t":{"en":"Summa Logicae","zh":"《逻辑大全》"},"y":1323},{"t":{"en":"Quodlibetal Questions","zh":"《任意论题问答》"},"y":1324}],"wiki":"William of Ockham"},
  {"id":"buridan","tradition":"medieval","born":1301,"died":1360,"life":{"en":"c. 1301–c. 1360","zh":"约1301–约1360年"},"name":{"en":"Jean Buridan","zh":"让·布里丹"},"role":{"en":"Paris arts master, logician and natural philosopher","zh":"巴黎艺学院教师，逻辑学家与自然哲学家"},"idea":{"en":"A thrown body keeps moving because of an impressed force, “impetus”, rather than the surrounding air, a step toward the idea of inertia. The paradox of the ass starving between two equal haystacks is named after him, though it is not in his writings.","zh":"被抛出的物体之所以继续运动，是因为它被赋予了一种“冲力”，而不是周围空气在推动它，这是迈向惯性概念的一步。“饿死在两堆等量干草之间的驴”这一悖论以他命名，但并不见于他的著作。"},"schools":["nominalism"],"works":[{"t":{"en":"Summulae de Dialectica","zh":"《辩证法纲要》"},"y":1340},{"t":{"en":"Questions on Aristotle’s Physics","zh":"《亚里士多德〈物理学〉问题集》"},"y":1350}],"wiki":"Jean Buridan"},
  {"id":"pico","tradition":"modern","born":1463,"died":1494,"life":{"en":"1463–1494","zh":"1463–1494年"},"name":{"en":"Giovanni Pico della Mirandola","zh":"皮科·德拉·米兰多拉"},"role":{"en":"Italian humanist who proclaimed humanity’s freedom to shape itself","zh":"宣告人有塑造自身之自由的意大利人文主义者"},"idea":{"en":"In his Oration, God gives Adam no fixed place in creation: humans alone can make themselves into beasts or into angels. He hoped to show that all philosophies and religions share a single hidden truth.","zh":"在他的《论人的尊严》中，上帝没有给亚当在造物中安排固定的位置：唯有人能把自己造就为禽兽或天使。他希望证明，一切哲学与宗教共享同一个隐藏的真理。"},"schools":["renaissance"],"works":[{"t":{"en":"Oration on the Dignity of Man","zh":"《论人的尊严》"},"y":1486},{"t":{"en":"900 Theses","zh":"《九百论题》"},"y":1486}],"wiki":"Giovanni Pico della Mirandola"},
  {"id":"erasmus","tradition":"modern","born":1466,"died":1536,"life":{"en":"c. 1466–1536","zh":"约1466–1536年"},"name":{"en":"Desiderius Erasmus","zh":"伊拉斯谟"},"role":{"en":"Dutch humanist scholar, editor of the Greek New Testament","zh":"荷兰人文主义学者，希腊文《新约》的编订者"},"idea":{"en":"He wanted a simple, inward “philosophy of Christ” recovered from the original sources, and mocked clerical greed and the schoolmen’s hair-splitting. He defended free will against Luther but refused to join either side of the Reformation.","zh":"他希望从原典中恢复一种朴素、内在的“基督哲学”，并嘲讽教士的贪婪和经院学者的咬文嚼字。他为自由意志辩护、反对路德，却拒绝加入宗教改革的任何一方。"},"schools":["renaissance"],"works":[{"t":{"en":"The Praise of Folly","zh":"《愚人颂》"},"y":1511},{"t":{"en":"Greek New Testament (Novum Instrumentum)","zh":"希腊文《新约》（《新工具书》）"},"y":1516},{"t":{"en":"On Free Will","zh":"《论自由意志》"},"y":1524}],"wiki":"Erasmus"},
  {"id":"machiavelli","tradition":"modern","born":1469,"died":1527,"life":{"en":"1469–1527","zh":"1469–1527年"},"name":{"en":"Niccolò Machiavelli","zh":"尼科洛·马基雅维利"},"role":{"en":"Florentine diplomat who studied power as it actually works","zh":"研究权力实际如何运作的佛罗伦萨外交官"},"idea":{"en":"A ruler who wants to keep his state must sometimes act against conventional virtue, and is judged by results. In the Discourses he praised republics in which free citizens and well-managed conflict sustain liberty.","zh":"想保住国家的君主有时必须违背通常的美德行事，人们以成败来评判他。在《论李维》中，他赞美那种由自由公民和受到引导的冲突来维持自由的共和国。"},"schools":["renaissance"],"works":[{"t":{"en":"The Prince","zh":"《君主论》"},"y":1513},{"t":{"en":"Discourses on Livy","zh":"《论李维》"},"y":1517}],"wiki":"Niccolò Machiavelli"},
  {"id":"montaigne","tradition":"modern","born":1533,"died":1592,"life":{"en":"1533–1592","zh":"1533–1592年"},"name":{"en":"Michel de Montaigne","zh":"米歇尔·德·蒙田"},"role":{"en":"French magistrate who invented the essay as self-examination","zh":"把随笔发明为自我审视之文体的法国法官"},"idea":{"en":"“What do I know?” was his motto: studying himself, he found human judgement shifting, custom-bound and fallible. He urged tolerance, since other peoples’ customs seem barbarous only to those who never question their own.","zh":"“我知道什么？”是他的座右铭：在审视自己时，他发现人的判断变动不居、受习俗束缚而且容易出错。他主张宽容，因为别的民族的习俗之所以显得野蛮，只是因为人们从不质疑自己的习俗。"},"schools":["renaissance"],"works":[{"t":{"en":"Essays","zh":"《随笔集》"},"y":1580}],"wiki":"Michel de Montaigne"},
  {"id":"bacon","tradition":"modern","born":1561,"died":1626,"life":{"en":"1561–1626","zh":"1561–1626年"},"name":{"en":"Francis Bacon","zh":"弗朗西斯·培根"},"role":{"en":"English statesman who called for science built on experiment","zh":"呼吁以实验为基础建立科学的英国政治家"},"idea":{"en":"Human knowledge and human power meet in one: we master nature only by careful observation and gradual induction, not by syllogisms. He catalogued the “idols” — biases of human nature, language and authority — that distort understanding.","zh":"人类的知识与人类的力量合而为一：只有通过细致的观察和逐步的归纳，而不是三段论，我们才能驾驭自然。他列举了扭曲理解的种种“假象”——来自人性、语言和权威的偏见。"},"schools":["empiricism"],"works":[{"t":{"en":"The Advancement of Learning","zh":"《学术的进展》"},"y":1605},{"t":{"en":"Novum Organum","zh":"《新工具》"},"y":1620}],"wiki":"Francis Bacon"},
  {"id":"hobbes","tradition":"modern","born":1588,"died":1679,"life":{"en":"1588–1679","zh":"1588–1679年"},"name":{"en":"Thomas Hobbes","zh":"托马斯·霍布斯"},"role":{"en":"English materialist who grounded the state in fear and consent","zh":"以恐惧与同意为国家奠基的英国唯物论者"},"idea":{"en":"Without a common power, life would be a war of all against all — “solitary, poor, nasty, brutish, and short”. Rational people would therefore authorise an absolute sovereign to keep the peace.","zh":"没有一个共同的权力，人生就会是一切人反对一切人的战争——“孤独、贫困、卑污、残忍而短寿”。因此，理性的人会授权一个绝对的主权者来维持和平。"},"schools":["social-contract"],"works":[{"t":{"en":"De Cive (On the Citizen)","zh":"《论公民》"},"y":1642},{"t":{"en":"Leviathan","zh":"《利维坦》"},"y":1651}],"wiki":"Thomas Hobbes"},
  {"id":"descartes","tradition":"modern","born":1596,"died":1650,"life":{"en":"1596–1650","zh":"1596–1650年"},"name":{"en":"René Descartes","zh":"勒内·笛卡尔"},"role":{"en":"French mathematician who rebuilt philosophy on the certainty of thought","zh":"以思维的确定性重建哲学的法国数学家"},"idea":{"en":"Doubting everything that could be doubted, he found one certainty: “I think, therefore I am.” He held that mind and body are two distinct substances, opening the modern mind–body problem.","zh":"在怀疑一切可以怀疑的东西之后，他找到了一个确定之点：“我思故我在。”他主张心灵与身体是两种不同的实体，由此开启了近代的心身问题。"},"schools":["rationalism"],"works":[{"t":{"en":"Discourse on the Method","zh":"《谈谈方法》"},"y":1637},{"t":{"en":"Meditations on First Philosophy","zh":"《第一哲学沉思集》"},"y":1641},{"t":{"en":"Principles of Philosophy","zh":"《哲学原理》"},"y":1644}],"wiki":"René Descartes","c":"Frans Hals - Portret van René Descartes.jpg","portrait":{"w":600,"h":735,"v":"97f58701c1","author":"After Frans Hals","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Frans_Hals_-_Portret_van_Ren%C3%A9_Descartes.jpg"}},
  {"id":"spinoza","tradition":"modern","born":1632,"died":1677,"life":{"en":"1632–1677","zh":"1632–1677年"},"name":{"en":"Baruch Spinoza","zh":"巴鲁赫·斯宾诺莎"},"role":{"en":"Dutch lens-grinder, expelled by his synagogue, who equated God with Nature","zh":"被犹太会堂逐出、视上帝即自然的荷兰磨镜片匠人"},"idea":{"en":"There is only one substance, “God or Nature”, and everything follows from it with necessity; mind and body are two aspects of one thing. Freedom is not escape from necessity but understanding it, which releases us from bondage to the passions.","zh":"只有一个实体，即“神或自然”，万物都必然地由它而出；心灵与身体是同一事物的两个方面。自由不是摆脱必然，而是理解必然，这种理解让我们摆脱激情的奴役。"},"schools":["rationalism"],"works":[{"t":{"en":"Theological-Political Treatise","zh":"《神学政治论》"},"y":1670},{"t":{"en":"Ethics","zh":"《伦理学》"},"y":1677}],"wiki":"Baruch Spinoza","c":"Spinoza.jpg","portrait":{"w":600,"h":697,"v":"20518478e5","author":"anonymous","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Spinoza.jpg"}},
  {"id":"locke","tradition":"modern","born":1632,"died":1704,"life":{"en":"1632–1704","zh":"1632–1704年"},"name":{"en":"John Locke","zh":"约翰·洛克"},"role":{"en":"English physician and philosopher of experience, consent and toleration","zh":"英国医生，经验、同意与宽容的哲学家"},"idea":{"en":"The mind begins as “white paper” written on by experience. Governments exist to protect life, liberty and property, rest on the consent of the governed, and may be resisted when they betray that trust.","zh":"心灵起初是一张由经验书写的“白纸”。政府的存在是为了保护生命、自由和财产，它建立在被统治者的同意之上，一旦背弃这份信托，人民就可以反抗。"},"schools":["empiricism","social-contract"],"works":[{"t":{"en":"An Essay Concerning Human Understanding","zh":"《人类理解论》"},"y":1689},{"t":{"en":"Two Treatises of Government","zh":"《政府论》"},"y":1689},{"t":{"en":"A Letter Concerning Toleration","zh":"《论宗教宽容》"},"y":1689}],"wiki":"John Locke","c":"Godfrey Kneller - Portrait of John Locke (Hermitage).jpg","portrait":{"w":600,"h":732,"v":"9a3ff7463a","author":"Godfrey Kneller","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Godfrey_Kneller_-_Portrait_of_John_Locke_(Hermitage).jpg"}},
  {"id":"leibniz","tradition":"modern","born":1646,"died":1716,"life":{"en":"1646–1716","zh":"1646–1716年"},"name":{"en":"Gottfried Wilhelm Leibniz","zh":"戈特弗里德·威廉·莱布尼茨"},"role":{"en":"German polymath, co-inventor of calculus, theorist of monads","zh":"德国博学家，微积分的发明者之一，单子论的提出者"},"idea":{"en":"The world consists of simple, mind-like substances, monads, whose states God harmonised in advance. Because God chose by the principle of sufficient reason, this is the best of all possible worlds — the claim Voltaire mocked in Candide.","zh":"世界由单纯的、类似心灵的实体——单子——构成，上帝预先协调了它们的状态。由于上帝依据充足理由律进行选择，这个世界是一切可能世界中最好的一个——伏尔泰在《老实人》里嘲讽的正是这一主张。"},"schools":["rationalism"],"works":[{"t":{"en":"Discourse on Metaphysics","zh":"《形而上学论》"},"y":1686},{"t":{"en":"Theodicy","zh":"《神正论》"},"y":1710},{"t":{"en":"Monadology","zh":"《单子论》"},"y":1714}],"wiki":"Gottfried Wilhelm Leibniz","c":"Christoph Bernhard Francke - Bildnis des Philosophen Leibniz (ca. 1695).jpg","portrait":{"w":600,"h":741,"v":"b26ff5e3e1","author":"Christoph Bernhard Francke","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Christoph_Bernhard_Francke_-_Bildnis_des_Philosophen_Leibniz_(ca._1695).jpg"}},
  {"id":"berkeley","tradition":"modern","born":1685,"died":1753,"life":{"en":"1685–1753","zh":"1685–1753年"},"name":{"en":"George Berkeley","zh":"乔治·贝克莱"},"role":{"en":"Irish bishop who argued that to be is to be perceived","zh":"主张“存在就是被感知”的爱尔兰主教"},"idea":{"en":"We never perceive matter itself, only ideas, so the notion of unthinking material substance is empty. Objects are collections of ideas, kept in being when no human is looking by the continual perception of God.","zh":"我们从未知觉到物质本身，只知觉到观念，因此“无思维的物质实体”这一概念是空洞的。物体是观念的集合；当无人观看时，它们依靠上帝持续的感知而存在。"},"schools":["empiricism"],"works":[{"t":{"en":"A Treatise Concerning the Principles of Human Knowledge","zh":"《人类知识原理》"},"y":1710},{"t":{"en":"Three Dialogues between Hylas and Philonous","zh":"《海拉斯和斐洛诺斯的三篇对话》"},"y":1713}],"wiki":"George Berkeley"},
  {"id":"montesquieu","tradition":"modern","born":1689,"died":1755,"life":{"en":"1689–1755","zh":"1689–1755年"},"name":{"en":"Montesquieu","zh":"孟德斯鸠"},"role":{"en":"French magistrate who compared the laws of many nations","zh":"比较各国法律的法国法官"},"idea":{"en":"Laws must suit each people’s climate, customs, commerce and religion. Liberty is safest where legislative, executive and judicial powers are separated, so that power checks power.","zh":"法律必须适合每个民族的气候、风俗、商业与宗教。立法、行政、司法三权分立、以权力制约权力的地方，自由才最有保障。"},"schools":["enlightenment"],"works":[{"t":{"en":"Persian Letters","zh":"《波斯人信札》"},"y":1721},{"t":{"en":"The Spirit of the Laws","zh":"《论法的精神》"},"y":1748}],"wiki":"Montesquieu"},
  {"id":"voltaire","tradition":"modern","born":1694,"died":1778,"life":{"en":"1694–1778","zh":"1694–1778年"},"name":{"en":"Voltaire","zh":"伏尔泰"},"role":{"en":"French writer who campaigned against intolerance and fanaticism","zh":"反对不宽容与狂热的法国作家"},"idea":{"en":"He popularised Locke and Newton in France and mocked Leibnizian optimism in Candide. His campaign for the executed Protestant Jean Calas made religious toleration a public cause.","zh":"他在法国普及了洛克和牛顿的思想，又在《老实人》中嘲讽莱布尼茨式的乐观主义。他为被处死的新教徒让·卡拉斯奔走申冤，使宗教宽容成为公共议题。"},"schools":["enlightenment"],"works":[{"t":{"en":"Letters on the English (Philosophical Letters)","zh":"《哲学通信》"},"y":1733},{"t":{"en":"Candide","zh":"《老实人》"},"y":1759},{"t":{"en":"Treatise on Tolerance","zh":"《论宽容》"},"y":1763}],"wiki":"Voltaire"},
  {"id":"hume","tradition":"modern","born":1711,"died":1776,"life":{"en":"1711–1776","zh":"1711–1776年"},"name":{"en":"David Hume","zh":"大卫·休谟"},"role":{"en":"Scottish skeptic who traced knowledge and morals to experience and feeling","zh":"把知识与道德追溯到经验和情感的苏格兰怀疑论者"},"idea":{"en":"We never observe necessary connections, only constant conjunctions, so belief in causes is a habit of the mind. Reason alone cannot move us to act — “reason is, and ought only to be the slave of the passions” — and morality rests on sentiment.","zh":"我们从未观察到必然联系，只观察到恒常的伴随，所以对原因的信念是心灵的一种习惯。单凭理性无法驱使我们行动——“理性是、并且只应当是激情的奴隶”——道德建立在情感之上。"},"schools":["empiricism"],"works":[{"t":{"en":"A Treatise of Human Nature","zh":"《人性论》"},"y":1739},{"t":{"en":"An Enquiry Concerning Human Understanding","zh":"《人类理智研究》"},"y":1748},{"t":{"en":"Dialogues Concerning Natural Religion","zh":"《自然宗教对话录》"},"y":1779}],"wiki":"David Hume","c":"David Hume Ramsay.jpg","portrait":{"w":600,"h":727,"v":"22ce8b8a2b","author":"Allan Ramsay","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:David_Hume_Ramsay.jpg"}},
  {"id":"rousseau","tradition":"modern","born":1712,"died":1778,"life":{"en":"1712–1778","zh":"1712–1778年"},"name":{"en":"Jean-Jacques Rousseau","zh":"让-雅克·卢梭"},"role":{"en":"Geneva-born writer who blamed society, not nature, for human corruption","zh":"认为人的败坏源于社会而非本性的日内瓦作家"},"idea":{"en":"In the state of nature humans were not warlike but free and capable of pity; inequality grew with property and society. Legitimate authority comes from the “general will” of citizens who give the laws to themselves.","zh":"在自然状态中，人并不好战，而是自由并怀有怜悯之心；不平等随着私有财产和社会而产生。正当的权威来自公民的“公意”，即公民为自己立法。"},"schools":["social-contract"],"works":[{"t":{"en":"Discourse on the Origin of Inequality","zh":"《论人类不平等的起源和基础》"},"y":1755},{"t":{"en":"The Social Contract","zh":"《社会契约论》"},"y":1762},{"t":{"en":"Emile, or On Education","zh":"《爱弥儿》"},"y":1762}],"wiki":"Jean-Jacques Rousseau","c":"Maurice Quentin de La Tour - Portrait of Jean-Jacques Rousseau - adjusted.jpg","portrait":{"w":600,"h":761,"v":"13afc98319","author":"Maurice Quentin de La Tour (Life time: 1788)","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Maurice_Quentin_de_La_Tour_-_Portrait_of_Jean-Jacques_Rousseau_-_adjusted.jpg"}},
  {"id":"diderot","tradition":"modern","born":1713,"died":1784,"life":{"en":"1713–1784","zh":"1713–1784年"},"name":{"en":"Denis Diderot","zh":"德尼·狄德罗"},"role":{"en":"Chief editor of the Encyclopédie, materialist and critic","zh":"《百科全书》主编，唯物论者与评论家"},"idea":{"en":"He edited the Encyclopédie to gather all human knowledge and “change the common way of thinking”. In dialogues unpublished in his lifetime he imagined a materialist account of life in which matter itself comes to feel and think.","zh":"他主编《百科全书》，要汇集人类的全部知识，“改变人们普遍的思维方式”。在生前未发表的对话中，他构想了一种唯物论的生命观：物质本身可以产生感觉与思想。"},"schools":["enlightenment"],"works":[{"t":{"en":"Encyclopédie (chief editor)","zh":"《百科全书》（主编）"},"y":1751},{"t":{"en":"D’Alembert’s Dream","zh":"《达朗贝尔的梦》"},"y":1769}],"wiki":"Denis Diderot"},
  {"id":"adam-smith","tradition":"modern","born":1723,"died":1790,"life":{"en":"1723–1790","zh":"1723–1790年"},"name":{"en":"Adam Smith","zh":"亚当·斯密"},"role":{"en":"Scottish moral philosopher and founder of political economy","zh":"苏格兰道德哲学家，政治经济学的奠基人"},"idea":{"en":"Morality grows from sympathy — imagining ourselves in another’s place — and from an inner “impartial spectator”. In commerce, the division of labour and free exchange can serve the common good without anyone intending it.","zh":"道德源于同情——设身处地地想象他人的处境——以及内心的“公正的旁观者”。在商业中，分工与自由交换可以在无人有意为之的情况下促进公共利益。"},"schools":["enlightenment"],"works":[{"t":{"en":"The Theory of Moral Sentiments","zh":"《道德情操论》"},"y":1759},{"t":{"en":"The Wealth of Nations","zh":"《国富论》"},"y":1776}],"wiki":"Adam Smith"},
  {"id":"kant","tradition":"modern","born":1724,"died":1804,"life":{"en":"1724–1804","zh":"1724–1804年"},"name":{"en":"Immanuel Kant","zh":"伊曼努尔·康德"},"role":{"en":"Königsberg professor whose critical philosophy redrew modern thought","zh":"以批判哲学重塑近代思想的柯尼斯堡教授"},"idea":{"en":"The mind actively structures experience, so we can know appearances with certainty but never things in themselves. Morality is a law reason gives itself: act only on a maxim you could will to be a universal law.","zh":"心灵主动地构造经验，因此我们能确定地认识现象，却永远无法认识物自体。道德是理性为自己颁布的法则：只按照你能同时意愿它成为普遍法则的准则去行动。"},"schools":["kantianism"],"works":[{"t":{"en":"Critique of Pure Reason","zh":"《纯粹理性批判》"},"y":1781},{"t":{"en":"Groundwork of the Metaphysics of Morals","zh":"《道德形而上学奠基》"},"y":1785},{"t":{"en":"Critique of Practical Reason","zh":"《实践理性批判》"},"y":1788}],"wiki":"Immanuel Kant","c":"Immanuel Kant - Gemaelde 1.jpg","portrait":{"w":600,"h":784,"v":"688e05ed3d","author":"Johann Gottlieb Becker (1720-1782)","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Immanuel_Kant_-_Gemaelde_1.jpg"}},
  {"id":"bentham","tradition":"modern","born":1748,"died":1832,"life":{"en":"1748–1832","zh":"1748–1832年"},"name":{"en":"Jeremy Bentham","zh":"杰里米·边沁"},"role":{"en":"English legal reformer who founded utilitarianism","zh":"创立功利主义的英国法律改革家"},"idea":{"en":"Nature has placed humankind under two sovereign masters, pain and pleasure, so laws should aim at the greatest happiness of the greatest number. He extended moral concern to animals: “The question is not, Can they reason? nor, Can they talk? but, Can they suffer?”","zh":"自然把人类置于痛苦与快乐这两位主宰之下，因此法律应当以最大多数人的最大幸福为目标。他把道德关怀扩展到动物：“问题不在于它们能否推理，也不在于它们能否说话，而在于它们能否感受痛苦。”"},"schools":["utilitarianism"],"works":[{"t":{"en":"A Fragment on Government","zh":"《政府片论》"},"y":1776},{"t":{"en":"An Introduction to the Principles of Morals and Legislation","zh":"《道德与立法原理导论》"},"y":1789}],"wiki":"Jeremy Bentham"},
  {"id":"wollstonecraft","tradition":"modern","born":1759,"died":1797,"life":{"en":"1759–1797","zh":"1759–1797年"},"name":{"en":"Mary Wollstonecraft","zh":"玛丽·沃斯通克拉夫特"},"role":{"en":"English writer who argued that women are rational beings owed education","zh":"主张女性是理性存在、理应受教育的英国作家"},"idea":{"en":"Women seem weak and frivolous not by nature but because they are denied education and treated as ornaments. If rights rest on reason, women share them, and society needs them as educated, independent citizens.","zh":"女性显得软弱轻浮，不是出于天性，而是因为她们被剥夺了教育、被当作装饰品。如果权利以理性为基础，女性就同样享有权利，社会也需要她们成为受过教育、独立自主的公民。"},"schools":["feminism"],"works":[{"t":{"en":"A Vindication of the Rights of Men","zh":"《为男权辩护》"},"y":1790},{"t":{"en":"A Vindication of the Rights of Woman","zh":"《女权辩护》"},"y":1792}],"wiki":"Mary Wollstonecraft","c":"Mary Wollstonecraft Portrait.jpg","portrait":{"w":600,"h":724,"v":"913f30723d","author":"John Opie","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Mary_Wollstonecraft_Portrait.jpg"}},
  {"id":"fichte","tradition":"modern","born":1762,"died":1814,"life":{"en":"1762–1814","zh":"1762–1814年"},"name":{"en":"Johann Gottlieb Fichte","zh":"约翰·戈特利布·费希特"},"role":{"en":"German idealist who grounded all knowledge in the self’s activity","zh":"把一切知识奠基于自我活动的德国观念论者"},"idea":{"en":"Kant’s thing in itself must go: philosophy should start from the I that “posits” itself and, in striving, posits a world that resists it. His Addresses to the German Nation (1808) made him a voice of German nationalism.","zh":"康德的物自体必须取消：哲学应当从“设定”自身的自我出发，自我在奋进中设定一个与之对立的世界。他的《对德意志民族的演讲》（1808）使他成为德意志民族主义的代言人。"},"schools":["german-idealism"],"works":[{"t":{"en":"Foundations of the Entire Science of Knowledge","zh":"《全部知识学的基础》"},"y":1794},{"t":{"en":"Addresses to the German Nation","zh":"《对德意志民族的演讲》"},"y":1808}],"wiki":"Johann Gottlieb Fichte"},
  {"id":"hegel","tradition":"modern","born":1770,"died":1831,"life":{"en":"1770–1831","zh":"1770–1831年"},"name":{"en":"Georg Wilhelm Friedrich Hegel","zh":"格奥尔格·威廉·弗里德里希·黑格尔"},"role":{"en":"German philosopher of spirit, history and dialectic","zh":"研究精神、历史与辩证法的德国哲学家"},"idea":{"en":"Reality is spirit coming to know itself through a dialectical process in which every limited position produces its own contradiction and is overcome. World history is the progress of the consciousness of freedom.","zh":"实在是精神通过辩证过程认识自身：每一个有限的立场都会产生自身的矛盾并被扬弃。世界历史就是自由意识的进展。"},"schools":["german-idealism"],"works":[{"t":{"en":"Phenomenology of Spirit","zh":"《精神现象学》"},"y":1807},{"t":{"en":"Science of Logic","zh":"《逻辑学》"},"y":1812},{"t":{"en":"Elements of the Philosophy of Right","zh":"《法哲学原理》"},"y":1820}],"wiki":"Georg Wilhelm Friedrich Hegel","c":"Jakob Schlesinger - Hegel 1831.jpg","portrait":{"w":600,"h":757,"v":"c362aab162","author":"Jakob Schlesinger","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Jakob_Schlesinger_-_Hegel_1831.jpg"}},
  {"id":"schelling","tradition":"modern","born":1775,"died":1854,"life":{"en":"1775–1854","zh":"1775–1854年"},"name":{"en":"Friedrich Wilhelm Joseph Schelling","zh":"弗里德里希·谢林"},"role":{"en":"German idealist philosopher of nature, art and freedom","zh":"研究自然、艺术与自由的德国观念论哲学家"},"idea":{"en":"Nature and mind are two expressions of one absolute: nature is visible spirit, spirit invisible nature. Early on he saw art as the place where this unity shows itself; later he turned to freedom, evil and the limits of reason.","zh":"自然与心灵是同一个绝对者的两种表现：自然是可见的精神，精神是不可见的自然。早年他认为艺术是这种统一显现之处；后来他转向自由、恶以及理性的界限等问题。"},"schools":["german-idealism"],"works":[{"t":{"en":"System of Transcendental Idealism","zh":"《先验唯心论体系》"},"y":1800},{"t":{"en":"Philosophical Investigations into the Essence of Human Freedom","zh":"《论人类自由的本质》"},"y":1809}],"wiki":"Friedrich Wilhelm Joseph Schelling"},
  {"id":"schopenhauer","tradition":"modern","born":1788,"died":1860,"life":{"en":"1788–1860","zh":"1788–1860年"},"name":{"en":"Arthur Schopenhauer","zh":"亚瑟·叔本华"},"role":{"en":"German pessimist who saw a blind will behind all things","zh":"认为万物背后是盲目意志的德国悲观主义者"},"idea":{"en":"Behind the world as representation lies one blind, insatiable striving — the will — that makes life swing between pain and boredom. Relief comes through art, compassion and the denial of the will, ideas he found echoed in Indian thought.","zh":"作为表象的世界背后，是一个盲目而永不满足的冲动——意志——它让人生在痛苦与无聊之间摇摆。解脱之道在于艺术、同情与意志的否定，他认为这些思想与印度思想遥相呼应。"},"schools":[],"works":[{"t":{"en":"The World as Will and Representation","zh":"《作为意志和表象的世界》"},"y":1818},{"t":{"en":"On the Basis of Morality","zh":"《论道德的基础》"},"y":1840}],"wiki":"Arthur Schopenhauer"},
  {"id":"mill","tradition":"modern","born":1806,"died":1873,"life":{"en":"1806–1873","zh":"1806–1873年"},"name":{"en":"John Stuart Mill","zh":"约翰·斯图尔特·密尔"},"role":{"en":"English philosopher of liberty, utility and women’s equality","zh":"论述自由、功利与女性平等的英国哲学家"},"idea":{"en":"The only reason to interfere with anyone’s liberty against their will is to prevent harm to others. He refined utilitarianism by distinguishing higher from lower pleasures, and argued for the full legal equality of women.","zh":"违背一个人的意志而干涉其自由，唯一正当的理由是防止他伤害他人。他区分了高级快乐与低级快乐，以此修正功利主义，并主张女性应享有完全的法律平等。"},"schools":["utilitarianism"],"works":[{"t":{"en":"On Liberty","zh":"《论自由》"},"y":1859},{"t":{"en":"Utilitarianism","zh":"《功利主义》"},"y":1861},{"t":{"en":"The Subjection of Women","zh":"《妇女的屈从地位》"},"y":1869}],"wiki":"John Stuart Mill"},
  {"id":"schleiermacher","tradition":"continental","born":1768,"died":1834,"life":{"en":"1768–1834","zh":"1768–1834年"},"name":{"en":"Friedrich Schleiermacher","zh":"弗里德里希·施莱尔马赫"},"role":{"en":"Berlin theologian and translator of Plato, father of modern hermeneutics","zh":"柏林神学家、柏拉图的译者，现代诠释学之父"},"idea":{"en":"Schleiermacher turned interpretation into a general art of understanding: to understand a text we must reconstruct both its language and its author’s individual way of thinking, since misunderstanding is the normal case. He also grounded religion in a feeling of absolute dependence.","zh":"施莱尔马赫把诠释变成一门普遍的理解艺术：要理解文本，既要重构其语言，也要重构作者独特的思维方式，因为误解才是常态。他还把宗教建立在“绝对依赖感”之上。"},"schools":["hermeneutics"],"works":[{"t":{"en":"On Religion: Speeches to Its Cultured Despisers","zh":"《论宗教：对蔑视宗教的有教养者的讲话》"},"y":1799},{"t":{"en":"Hermeneutics and Criticism","zh":"《诠释学与批判》"},"y":1838}],"wiki":"Friedrich Schleiermacher"},
  {"id":"kierkegaard","tradition":"continental","born":1813,"died":1855,"life":{"en":"1813–1855","zh":"1813–1855年"},"name":{"en":"Søren Kierkegaard","zh":"索伦·克尔凯郭尔"},"role":{"en":"Danish Christian thinker of the anxious, choosing individual","zh":"丹麦基督教思想家，关注焦虑而必须抉择的个人"},"idea":{"en":"Against Hegel’s system, Kierkegaard insisted that truth is subjectivity: what matters is how a single person lives, and faith is a passionate leap that no reasoning can secure.","zh":"克尔凯郭尔反对黑格尔的体系，主张“真理即主体性”：重要的是一个具体的人如何生活；信仰是理性无法担保的激情一跃。"},"schools":["existentialism"],"works":[{"t":{"en":"Either/Or","zh":"《非此即彼》"},"y":1843},{"t":{"en":"Fear and Trembling","zh":"《恐惧与战栗》"},"y":1843},{"t":{"en":"The Sickness unto Death","zh":"《致死的疾病》"},"y":1849}],"wiki":"Søren Kierkegaard","c":"Søren Kierkegaard (1813-1855) - (cropped).jpg","portrait":{"w":564,"h":796,"v":"aa0281b9f1","author":"La Biblioteca Real de Dinamarca","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:S%C3%B8ren_Kierkegaard_(1813-1855)_-_(cropped).jpg"}},
  {"id":"marx","tradition":"continental","born":1818,"died":1883,"life":{"en":"1818–1883","zh":"1818–1883年"},"name":{"en":"Karl Marx","zh":"卡尔·马克思"},"role":{"en":"German philosopher, economist and revolutionary in London exile","zh":"流亡伦敦的德国哲学家、经济学家与革命家"},"idea":{"en":"Marx turned Hegel’s dialectic into historical materialism: the way a society produces its means of life shapes its politics and ideas, and capitalism’s class conflict points beyond it.","zh":"马克思把黑格尔的辩证法改造成历史唯物主义：一个社会生产生活资料的方式决定其政治与观念，而资本主义的阶级冲突预示着对它的超越。"},"schools":["marxism"],"works":[{"t":{"en":"Economic and Philosophic Manuscripts of 1844","zh":"《1844年经济学哲学手稿》"},"y":1844},{"t":{"en":"The Communist Manifesto (with Engels)","zh":"《共产党宣言》（与恩格斯合著）"},"y":1848},{"t":{"en":"Capital, Volume I","zh":"《资本论》第一卷"},"y":1867}],"wiki":"Karl Marx","c":"Karl Marx by John Jabez Edwin Mayall 1875 - Restored.png","portrait":{"w":600,"h":889,"v":"d97752ac80","author":"John Jabez Edwin Mayall","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Karl_Marx_by_John_Jabez_Edwin_Mayall_1875_-_Restored.png"}},
  {"id":"engels","tradition":"continental","born":1820,"died":1895,"life":{"en":"1820–1895","zh":"1820–1895年"},"name":{"en":"Friedrich Engels","zh":"弗里德里希·恩格斯"},"role":{"en":"Manufacturer’s son who co-founded Marxism with Marx","zh":"工厂主之子，与马克思共同创立马克思主义"},"idea":{"en":"Engels documented industrial poverty first-hand, financed and edited Marx’s work, and popularised Marxism as a scientific worldview, extending the dialectic to nature and to the origins of the family.","zh":"恩格斯亲身记录了工业时代的贫困，资助并编辑马克思的著作，把马克思主义普及为一种“科学的世界观”，还把辩证法推广到自然界以及家庭的起源。"},"schools":["marxism"],"works":[{"t":{"en":"The Condition of the Working Class in England","zh":"《英国工人阶级状况》"},"y":1845},{"t":{"en":"Anti-Dühring","zh":"《反杜林论》"},"y":1878},{"t":{"en":"The Origin of the Family, Private Property and the State","zh":"《家庭、私有制和国家的起源》"},"y":1884}],"wiki":"Friedrich Engels"},
  {"id":"dilthey","tradition":"continental","born":1833,"died":1911,"life":{"en":"1833–1911","zh":"1833–1911年"},"name":{"en":"Wilhelm Dilthey","zh":"威廉·狄尔泰"},"role":{"en":"German historian of ideas who defended the human sciences","zh":"德国思想史家，为人文科学的独立地位辩护"},"idea":{"en":"Dilthey argued that nature is explained but human life is understood: the human sciences grasp lived experience and its expressions from the inside, through historical understanding rather than causal laws.","zh":"狄尔泰认为，自然要被说明，人的生命则要被理解：人文科学要从内部把握亲历的生命及其表达，依靠的是历史性的理解，而非因果规律。"},"schools":["hermeneutics"],"works":[{"t":{"en":"Introduction to the Human Sciences","zh":"《精神科学引论》"},"y":1883},{"t":{"en":"The Formation of the Historical World in the Human Sciences","zh":"《精神科学中历史世界的建构》"},"y":1910}],"wiki":"Wilhelm Dilthey"},
  {"id":"nietzsche","tradition":"continental","born":1844,"died":1900,"life":{"en":"1844–1900","zh":"1844–1900年"},"name":{"en":"Friedrich Nietzsche","zh":"弗里德里希·尼采"},"role":{"en":"German philologist who diagnosed the death of God","zh":"德国古典语文学家，诊断了“上帝之死”"},"idea":{"en":"Nietzsche argued that once belief in God collapses, the values built on it lose their ground; he traced morality’s origins to resentment and the will to power, and called for a revaluation of values that affirms life.","zh":"尼采认为，一旦对上帝的信仰崩塌，建立在其上的价值便失去根基；他把道德的起源追溯到怨恨与权力意志，并呼吁“重估一切价值”，以肯定生命。"},"schools":["existentialism"],"works":[{"t":{"en":"Thus Spoke Zarathustra","zh":"《查拉图斯特拉如是说》"},"y":1883},{"t":{"en":"Beyond Good and Evil","zh":"《善恶的彼岸》"},"y":1886},{"t":{"en":"On the Genealogy of Morality","zh":"《论道德的谱系》"},"y":1887}],"wiki":"Friedrich Nietzsche","c":"Nietzsche187a.jpg","portrait":{"w":600,"h":814,"v":"6fca40e237","author":"Friedrich Hermann Hartmann","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Nietzsche187a.jpg"}},
  {"id":"saussure","tradition":"continental","born":1857,"died":1913,"life":{"en":"1857–1913","zh":"1857–1913年"},"name":{"en":"Ferdinand de Saussure","zh":"费迪南·德·索绪尔"},"role":{"en":"Geneva linguist whose lectures founded structural linguistics","zh":"日内瓦语言学家，其讲课奠定了结构语言学"},"idea":{"en":"Saussure treated language as a system of signs whose meanings come from their differences, with an arbitrary link between sound and concept, and proposed a general science of signs, semiology. His Course was compiled by students after his death.","zh":"索绪尔把语言视为一个符号系统，其意义来自彼此的差异，而声音与概念之间的联系是任意的；他还设想了一门研究一切符号的普通科学——符号学。《普通语言学教程》是他去世后由学生整理出版的。"},"schools":["structuralism"],"works":[{"t":{"en":"Course in General Linguistics","zh":"《普通语言学教程》"},"y":1916}],"wiki":"Ferdinand de Saussure"},
  {"id":"husserl","tradition":"continental","born":1859,"died":1938,"life":{"en":"1859–1938","zh":"1859–1938年"},"name":{"en":"Edmund Husserl","zh":"埃德蒙德·胡塞尔"},"role":{"en":"Moravian-born mathematician turned philosopher, founder of phenomenology","zh":"生于摩拉维亚、由数学转向哲学的现象学创始人"},"idea":{"en":"Husserl held that philosophy must become a rigorous science of consciousness: by bracketing our natural belief in the world, we can describe the intentional structures through which anything appears.","zh":"胡塞尔主张，哲学必须成为一门关于意识的严格科学：通过悬置对世界存在的自然信念，我们可以描述任何事物得以显现的意向性结构。"},"schools":["phenomenology"],"works":[{"t":{"en":"Logical Investigations","zh":"《逻辑研究》"},"y":1900},{"t":{"en":"Ideas I","zh":"《纯粹现象学通论》（《观念I》）"},"y":1913},{"t":{"en":"The Crisis of European Sciences and Transcendental Phenomenology","zh":"《欧洲科学的危机与超越论的现象学》"},"y":1936}],"wiki":"Edmund Husserl"},
  {"id":"heidegger","tradition":"continental","born":1889,"died":1976,"life":{"en":"1889–1976","zh":"1889–1976年"},"name":{"en":"Martin Heidegger","zh":"马丁·海德格尔"},"role":{"en":"German philosopher of Being, compromised by his Nazi party membership","zh":"追问“存在”的德国哲学家，因加入纳粹党而饱受争议"},"idea":{"en":"Heidegger argued that Western philosophy forgot the question of the meaning of Being; he analysed human existence (Dasein) as being-in-the-world, care and being-towards-death, and later criticised technology for revealing everything as a resource.","zh":"海德格尔认为，西方哲学遗忘了“存在的意义”这一问题；他把人的生存（此在）分析为“在世界之中存在”、操心与“向死而在”，后期又批判技术把一切都揭示为可用资源。"},"schools":["phenomenology"],"works":[{"t":{"en":"Being and Time","zh":"《存在与时间》"},"y":1927},{"t":{"en":"The Question Concerning Technology","zh":"《技术的追问》"},"y":1954}],"wiki":"Martin Heidegger"},
  {"id":"gramsci","tradition":"continental","born":1891,"died":1937,"life":{"en":"1891–1937","zh":"1891–1937年"},"name":{"en":"Antonio Gramsci","zh":"安东尼奥·葛兰西"},"role":{"en":"Italian communist leader who wrote his major work in Mussolini’s prisons","zh":"意大利共产党领袖，在墨索里尼的监狱中写下主要著作"},"idea":{"en":"Gramsci argued that ruling classes govern less by force than by hegemony, a cultural common sense that makes their rule seem natural, so social change requires a long struggle over ideas and institutions.","zh":"葛兰西认为，统治阶级主要不是靠暴力，而是靠“文化霸权”来统治——一种让其统治显得理所当然的文化常识；因此社会变革需要在观念与制度上进行长期斗争。"},"schools":["marxism"],"works":[{"t":{"en":"Prison Notebooks","zh":"《狱中札记》"},"y":1935}],"wiki":"Antonio Gramsci"},
  {"id":"benjamin","tradition":"continental","born":1892,"died":1940,"life":{"en":"1892–1940","zh":"1892–1940年"},"name":{"en":"Walter Benjamin","zh":"瓦尔特·本雅明"},"role":{"en":"Berlin critic who joined Marxism, messianism and media theory","zh":"柏林批评家，融合了马克思主义、弥赛亚思想与媒介理论"},"idea":{"en":"Benjamin argued that technical reproduction strips art of its “aura” and could make it political, and that history should be read against the grain, from the standpoint of the defeated. He died fleeing the Nazis in 1940.","zh":"本雅明认为，技术复制使艺术失去“灵晕”，也可能使艺术政治化；历史应当“逆着纹理”去读，站在失败者的立场上。1940年，他在逃离纳粹途中去世。"},"schools":["critical-theory"],"works":[{"t":{"en":"The Work of Art in the Age of Mechanical Reproduction","zh":"《机械复制时代的艺术作品》"},"y":1935},{"t":{"en":"Theses on the Philosophy of History","zh":"《历史哲学论纲》"},"y":1940},{"t":{"en":"The Arcades Project (unfinished)","zh":"《拱廊街计划》（未完成）"},"y":1940}],"wiki":"Walter Benjamin"},
  {"id":"horkheimer","tradition":"continental","born":1895,"died":1973,"life":{"en":"1895–1973","zh":"1895–1973年"},"name":{"en":"Max Horkheimer","zh":"马克斯·霍克海默"},"role":{"en":"Director of the Frankfurt Institute who defined critical theory","zh":"法兰克福社会研究所所长，界定了“批判理论”"},"idea":{"en":"Horkheimer distinguished critical theory, which aims to free people from domination, from traditional theory, which accepts society as it is; with Adorno he argued that instrumental reason had turned enlightenment against itself.","zh":"霍克海默区分了以人从支配中解放为目标的批判理论，与接受社会现状的传统理论；他和阿多诺一起论证，工具理性已使启蒙走向了自身的反面。"},"schools":["critical-theory"],"works":[{"t":{"en":"Traditional and Critical Theory","zh":"《传统理论与批判理论》"},"y":1937},{"t":{"en":"Dialectic of Enlightenment (with Adorno)","zh":"《启蒙辩证法》（与阿多诺合著）"},"y":1947},{"t":{"en":"Eclipse of Reason","zh":"《理性之蚀》"},"y":1947}],"wiki":"Max Horkheimer"},
  {"id":"marcuse","tradition":"continental","born":1898,"died":1979,"life":{"en":"1898–1979","zh":"1898–1979年"},"name":{"en":"Herbert Marcuse","zh":"赫伯特·马尔库塞"},"role":{"en":"Frankfurt School exile who became the New Left’s philosopher","zh":"流亡美国的法兰克福学派成员，后来成为新左派的哲学代言人"},"idea":{"en":"Marcuse argued that affluent industrial society absorbs opposition by satisfying “false needs”, producing one-dimensional people; drawing on Freud, he imagined a non-repressive civilisation.","zh":"马尔库塞认为，富裕的工业社会通过满足“虚假需求”来吸收反对力量，造就了“单向度的人”；他借助弗洛伊德，设想了一种非压抑性的文明。"},"schools":["critical-theory"],"works":[{"t":{"en":"Reason and Revolution","zh":"《理性与革命》"},"y":1941},{"t":{"en":"Eros and Civilization","zh":"《爱欲与文明》"},"y":1955},{"t":{"en":"One-Dimensional Man","zh":"《单向度的人》"},"y":1964}],"wiki":"Herbert Marcuse"},
  {"id":"gadamer","tradition":"continental","born":1900,"died":2002,"life":{"en":"1900–2002","zh":"1900–2002年"},"name":{"en":"Hans-Georg Gadamer","zh":"汉斯-格奥尔格·伽达默尔"},"role":{"en":"Heidegger’s student, who made hermeneutics a philosophy of understanding","zh":"海德格尔的学生，把诠释学发展为一种关于理解的哲学"},"idea":{"en":"Gadamer argued that understanding is not a method but an event: we always interpret from within tradition and its prejudices, and truth emerges in a “fusion of horizons” between our present and the text.","zh":"伽达默尔认为，理解不是一种方法，而是一种发生：我们总是从传统及其成见之内进行诠释，真理在我们的当下与文本之间的“视域融合”中显现。"},"schools":["hermeneutics"],"works":[{"t":{"en":"Truth and Method","zh":"《真理与方法》"},"y":1960}],"wiki":"Hans-Georg Gadamer"},
  {"id":"adorno","tradition":"continental","born":1903,"died":1969,"life":{"en":"1903–1969","zh":"1903–1969年"},"name":{"en":"Theodor W. Adorno","zh":"西奥多·阿多诺"},"role":{"en":"Frankfurt philosopher, music theorist and critic of the culture industry","zh":"法兰克福学派哲学家、音乐理论家，文化工业的批判者"},"idea":{"en":"Adorno argued that modern society integrates everything into exchange and administration, so thought must resist by attending to what concepts leave out: a “negative dialectics” with no final reconciliation.","zh":"阿多诺认为，现代社会把一切都纳入交换与管理之中，因此思想必须通过关注概念所遗漏的东西来进行抵抗：这是一种没有最终和解的“否定的辩证法”。"},"schools":["critical-theory"],"works":[{"t":{"en":"Dialectic of Enlightenment (with Horkheimer)","zh":"《启蒙辩证法》（与霍克海默合著）"},"y":1947},{"t":{"en":"Minima Moralia","zh":"《最低限度的道德》"},"y":1951},{"t":{"en":"Negative Dialectics","zh":"《否定的辩证法》"},"y":1966}],"wiki":"Theodor W. Adorno"},
  {"id":"sartre","tradition":"continental","born":1905,"died":1980,"life":{"en":"1905–1980","zh":"1905–1980年"},"name":{"en":"Jean-Paul Sartre","zh":"让-保罗·萨特"},"role":{"en":"Parisian novelist and philosopher, the public face of existentialism","zh":"巴黎的小说家与哲学家，存在主义最广为人知的代表"},"idea":{"en":"Sartre argued that consciousness is a nothingness that can always negate what is given, so humans are radically free and responsible; later he tried to reconcile this freedom with Marxism.","zh":"萨特认为，意识是一种能够否定一切既定之物的“虚无”，因此人是彻底自由且必须负责的；后期他试图把这种自由与马克思主义调和起来。"},"schools":["existentialism"],"works":[{"t":{"en":"Nausea","zh":"《恶心》"},"y":1938},{"t":{"en":"Being and Nothingness","zh":"《存在与虚无》"},"y":1943},{"t":{"en":"Existentialism Is a Humanism","zh":"《存在主义是一种人道主义》"},"y":1946}],"wiki":"Jean-Paul Sartre"},
  {"id":"levinas","tradition":"continental","born":1906,"died":1995,"life":{"en":"1906–1995","zh":"1906–1995年"},"name":{"en":"Emmanuel Levinas","zh":"伊曼努尔·列维纳斯"},"role":{"en":"Lithuanian-born French philosopher of ethics as first philosophy","zh":"生于立陶宛的法国哲学家，主张伦理学是第一哲学"},"idea":{"en":"Levinas argued that the face of another person makes an ethical demand on me before any knowledge or theory, so responsibility for the other, not ontology, is philosophy’s starting point.","zh":"列维纳斯认为，他人的面容在任何认识或理论之前就向我提出了伦理要求；因此哲学的起点不是存在论，而是对他人的责任。"},"schools":["phenomenology"],"works":[{"t":{"en":"Totality and Infinity","zh":"《总体与无限》"},"y":1961},{"t":{"en":"Otherwise than Being","zh":"《别于存在或超越本质》"},"y":1974}],"wiki":"Emmanuel Levinas"},
  {"id":"arendt","tradition":"continental","born":1906,"died":1975,"life":{"en":"1906–1975","zh":"1906–1975年"},"name":{"en":"Hannah Arendt","zh":"汉娜·阿伦特"},"role":{"en":"German-Jewish political theorist who fled Nazism for America","zh":"逃离纳粹、流亡美国的德国犹太裔政治理论家"},"idea":{"en":"Arendt analysed totalitarianism as a new form of rule built on terror and ideology, coined the phrase “the banality of evil”, and defended political action among equals as the heart of human freedom.","zh":"阿伦特把极权主义分析为一种以恐怖和意识形态为基础的新型统治，提出“平庸之恶”的说法，并主张平等者之间的政治行动是人类自由的核心。"},"schools":[],"works":[{"t":{"en":"The Origins of Totalitarianism","zh":"《极权主义的起源》"},"y":1951},{"t":{"en":"The Human Condition","zh":"《人的境况》"},"y":1958},{"t":{"en":"Eichmann in Jerusalem","zh":"《艾希曼在耶路撒冷》"},"y":1963}],"wiki":"Hannah Arendt"},
  {"id":"beauvoir","tradition":"continental","born":1908,"died":1986,"life":{"en":"1908–1986","zh":"1908–1986年"},"name":{"en":"Simone de Beauvoir","zh":"西蒙娜·德·波伏瓦"},"role":{"en":"French existentialist whose The Second Sex reshaped feminism","zh":"法国存在主义者，《第二性》重塑了女性主义"},"idea":{"en":"Beauvoir argued that women have been made into man’s “Other”, defined by men rather than by themselves; since there is no feminine essence, freedom means refusing that assigned situation.","zh":"波伏瓦指出，女人一直被塑造成男人的“他者”，由男人而不是由她们自己来界定；既然并不存在女性的本质，自由就意味着拒绝这种被指派的处境。"},"schools":["existentialism","feminism"],"works":[{"t":{"en":"The Ethics of Ambiguity","zh":"《模糊性的道德》"},"y":1947},{"t":{"en":"The Second Sex","zh":"《第二性》"},"y":1949}],"wiki":"Simone de Beauvoir"},
  {"id":"merleau-ponty","tradition":"continental","born":1908,"died":1961,"life":{"en":"1908–1961","zh":"1908–1961年"},"name":{"en":"Maurice Merleau-Ponty","zh":"莫里斯·梅洛-庞蒂"},"role":{"en":"French phenomenologist of perception and the lived body","zh":"研究知觉与身体的法国现象学家"},"idea":{"en":"Merleau-Ponty argued that we meet the world first through the body, not as minds observing objects: perception is a bodily, pre-reflective engagement that comes before the split between subject and object.","zh":"梅洛-庞蒂认为，我们首先是通过身体与世界相遇，而不是作为心灵去观察对象：知觉是一种身体性的、前反思的投入，先于主体与客体的分裂。"},"schools":["phenomenology"],"works":[{"t":{"en":"Phenomenology of Perception","zh":"《知觉现象学》"},"y":1945},{"t":{"en":"The Visible and the Invisible","zh":"《可见的与不可见的》"},"y":1964}],"wiki":"Maurice Merleau-Ponty"},
  {"id":"levi-strauss","tradition":"continental","born":1908,"died":2009,"life":{"en":"1908–2009","zh":"1908–2009年"},"name":{"en":"Claude Lévi-Strauss","zh":"克洛德·列维-斯特劳斯"},"role":{"en":"French anthropologist who founded structural anthropology","zh":"法国人类学家，结构人类学的创始人"},"idea":{"en":"Lévi-Strauss argued that kinship systems, myths and classifications in all societies follow the same underlying logic of binary oppositions, so “primitive” thought is as rigorous as science.","zh":"列维-斯特劳斯认为，所有社会的亲属制度、神话与分类，都遵循同样的深层二元对立逻辑；因此所谓“原始”思维与科学一样严密。"},"schools":["structuralism"],"works":[{"t":{"en":"The Elementary Structures of Kinship","zh":"《亲属关系的基本结构》"},"y":1949},{"t":{"en":"Tristes Tropiques","zh":"《忧郁的热带》"},"y":1955},{"t":{"en":"The Savage Mind","zh":"《野性的思维》"},"y":1962}],"wiki":"Claude Lévi-Strauss"},
  {"id":"camus","tradition":"continental","born":1913,"died":1960,"life":{"en":"1913–1960","zh":"1913–1960年"},"name":{"en":"Albert Camus","zh":"阿尔贝·加缪"},"role":{"en":"Algerian-born French writer of the absurd and of revolt","zh":"生于阿尔及利亚的法国作家，书写荒诞与反抗"},"idea":{"en":"Camus held that life is absurd, a clash between our demand for meaning and a silent universe, yet suicide and religious leaps are evasions: we must live in lucid revolt. He himself rejected the label “existentialist”.","zh":"加缪认为，人生是荒诞的——人对意义的渴求与沉默的宇宙相互冲撞；但自杀与宗教式的跳跃都是逃避，人应当清醒地反抗着活下去。他本人拒绝“存在主义者”这一标签。"},"schools":["existentialism"],"works":[{"t":{"en":"The Stranger","zh":"《局外人》"},"y":1942},{"t":{"en":"The Myth of Sisyphus","zh":"《西西弗神话》"},"y":1942},{"t":{"en":"The Rebel","zh":"《反抗者》"},"y":1951}],"wiki":"Albert Camus"},
  {"id":"ricoeur","tradition":"continental","born":1913,"died":2005,"life":{"en":"1913–2005","zh":"1913–2005年"},"name":{"en":"Paul Ricœur","zh":"保罗·利科"},"role":{"en":"French philosopher who joined phenomenology, hermeneutics and narrative","zh":"把现象学、诠释学与叙事研究结合起来的法国哲学家"},"idea":{"en":"Ricœur held that we understand ourselves only indirectly, through symbols, texts and the stories we tell; he balanced a “hermeneutics of suspicion” (Marx, Nietzsche, Freud) with a hermeneutics of trust.","zh":"利科认为，我们只能间接地理解自己——通过象征、文本以及我们讲述的故事；他在“怀疑的诠释学”（马克思、尼采、弗洛伊德）与信任的诠释学之间寻求平衡。"},"schools":["hermeneutics"],"works":[{"t":{"en":"Freud and Philosophy","zh":"《弗洛伊德与哲学》"},"y":1965},{"t":{"en":"Time and Narrative","zh":"《时间与叙事》"},"y":1983},{"t":{"en":"Oneself as Another","zh":"《作为他者的自身》"},"y":1990}],"wiki":"Paul Ricœur"},
  {"id":"barthes","tradition":"continental","born":1915,"died":1980,"life":{"en":"1915–1980","zh":"1915–1980年"},"name":{"en":"Roland Barthes","zh":"罗兰·巴特"},"role":{"en":"French critic who read everyday culture as signs","zh":"把日常文化当作符号来解读的法国批评家"},"idea":{"en":"Barthes showed how advertising, wrestling and wine carry hidden “myths” that make bourgeois values seem natural, and later declared the “death of the author”: a text’s meaning is made by its reader.","zh":"巴特揭示了广告、摔跤、葡萄酒如何承载隐藏的“神话”，使资产阶级的价值显得天经地义；后来他宣布“作者之死”：文本的意义由读者生成。"},"schools":["structuralism"],"works":[{"t":{"en":"Mythologies","zh":"《神话学》"},"y":1957},{"t":{"en":"The Death of the Author","zh":"《作者之死》"},"y":1967},{"t":{"en":"S/Z","zh":"《S/Z》"},"y":1970}],"wiki":"Roland Barthes"},
  {"id":"lyotard","tradition":"continental","born":1924,"died":1998,"life":{"en":"1924–1998","zh":"1924–1998年"},"name":{"en":"Jean-François Lyotard","zh":"让-弗朗索瓦·利奥塔"},"role":{"en":"French philosopher who defined the postmodern condition","zh":"界定了“后现代状况”的法国哲学家"},"idea":{"en":"Lyotard defined the postmodern as “incredulity toward metanarratives”: grand stories of progress, emancipation or spirit no longer legitimate knowledge, which splits into many incommensurable language games.","zh":"利奥塔把后现代界定为“对元叙事的怀疑”：关于进步、解放或精神的宏大故事已不再能为知识提供正当性，知识分裂为许多不可通约的语言游戏。"},"schools":["poststructuralism"],"works":[{"t":{"en":"The Postmodern Condition","zh":"《后现代状况》"},"y":1979},{"t":{"en":"The Differend","zh":"《异识》"},"y":1983}],"wiki":"Jean-François Lyotard"},
  {"id":"deleuze","tradition":"continental","born":1925,"died":1995,"life":{"en":"1925–1995","zh":"1925–1995年"},"name":{"en":"Gilles Deleuze","zh":"吉尔·德勒兹"},"role":{"en":"French philosopher of difference, desire and becoming","zh":"关注差异、欲望与生成的法国哲学家"},"idea":{"en":"Deleuze sought a philosophy of difference in itself, not difference as a gap between fixed identities; with Félix Guattari he described desire as productive and thought as a rhizome, branching without a centre.","zh":"德勒兹追求一种关于“差异本身”的哲学，而不把差异看作固定同一性之间的空隙；他与加塔利一起，把欲望描述为生产性的，把思想描述为没有中心、四处蔓生的“块茎”。"},"schools":["poststructuralism"],"works":[{"t":{"en":"Difference and Repetition","zh":"《差异与重复》"},"y":1968},{"t":{"en":"Anti-Oedipus (with Félix Guattari)","zh":"《反俄狄浦斯》（与加塔利合著）"},"y":1972},{"t":{"en":"A Thousand Plateaus (with Félix Guattari)","zh":"《千高原》（与加塔利合著）"},"y":1980}],"wiki":"Gilles Deleuze"},
  {"id":"fanon","tradition":"continental","born":1925,"died":1961,"life":{"en":"1925–1961","zh":"1925–1961年"},"name":{"en":"Frantz Fanon","zh":"弗朗茨·法农"},"role":{"en":"Martinican psychiatrist and theorist of anticolonial liberation","zh":"马提尼克精神科医生，反殖民解放的理论家"},"idea":{"en":"Fanon analysed how colonial racism enters the psyche of the colonised, making them see themselves through white eyes, and argued that decolonisation requires a total break with the colonial order.","zh":"法农分析了殖民种族主义如何侵入被殖民者的心理，使他们透过白人的眼睛看待自己；他主张去殖民化需要与殖民秩序彻底决裂。"},"schools":["postcolonial"],"works":[{"t":{"en":"Black Skin, White Masks","zh":"《黑皮肤，白面具》"},"y":1952},{"t":{"en":"The Wretched of the Earth","zh":"《全世界受苦的人》"},"y":1961}],"wiki":"Frantz Fanon"},
  {"id":"foucault","tradition":"continental","born":1926,"died":1984,"life":{"en":"1926–1984","zh":"1926–1984年"},"name":{"en":"Michel Foucault","zh":"米歇尔·福柯"},"role":{"en":"French historian of madness, prisons and sexuality","zh":"研究疯癫、监狱与性经验史的法国思想家"},"idea":{"en":"Foucault showed that categories like madness, delinquency and sexuality were produced by historical practices of knowledge and power; modern power works less by punishment than by discipline, surveillance and norms.","zh":"福柯揭示，疯癫、犯罪、性等范畴是由知识与权力的历史实践生产出来的；现代权力主要不是通过惩罚，而是通过规训、监视与规范来运作。"},"schools":["poststructuralism"],"works":[{"t":{"en":"History of Madness","zh":"《古典时代疯狂史》"},"y":1961},{"t":{"en":"The Order of Things","zh":"《词与物》"},"y":1966},{"t":{"en":"Discipline and Punish","zh":"《规训与惩罚》"},"y":1975}],"wiki":"Michel Foucault"},
  {"id":"habermas","tradition":"continental","born":1929,"died":null,"life":{"en":"born 1929","zh":"1929年生"},"name":{"en":"Jürgen Habermas","zh":"尤尔根·哈贝马斯"},"role":{"en":"Leading second-generation Frankfurt theorist of democracy and communication","zh":"法兰克福学派第二代领军人物，研究民主与交往"},"idea":{"en":"Habermas argued that besides instrumental reason there is communicative reason, aimed at mutual understanding; legitimate norms and laws are those all affected could accept in free and equal public discussion.","zh":"哈贝马斯认为，除工具理性之外，还有以相互理解为目标的交往理性；正当的规范与法律，是所有相关者在自由平等的公共讨论中都能够接受的规范与法律。"},"schools":["critical-theory"],"works":[{"t":{"en":"The Structural Transformation of the Public Sphere","zh":"《公共领域的结构转型》"},"y":1962},{"t":{"en":"The Theory of Communicative Action","zh":"《交往行为理论》"},"y":1981},{"t":{"en":"Between Facts and Norms","zh":"《在事实与规范之间》"},"y":1992}],"wiki":"Jürgen Habermas"},
  {"id":"derrida","tradition":"continental","born":1930,"died":2004,"life":{"en":"1930–2004","zh":"1930–2004年"},"name":{"en":"Jacques Derrida","zh":"雅克·德里达"},"role":{"en":"Algerian-born French philosopher who founded deconstruction","zh":"生于阿尔及利亚的法国哲学家，解构的开创者"},"idea":{"en":"Derrida argued that Western thought privileges presence (speech over writing, the original over the copy), yet every such hierarchy depends on what it excludes; deconstruction reads texts to show this instability.","zh":"德里达认为，西方思想一直偏重“在场”（言语高于书写，原本高于摹本），但每一种这样的等级秩序都依赖于它所排斥的东西；解构就是通过阅读文本来揭示这种不稳定性。"},"schools":["poststructuralism"],"works":[{"t":{"en":"Speech and Phenomena","zh":"《声音与现象》"},"y":1967},{"t":{"en":"Of Grammatology","zh":"《论文字学》"},"y":1967},{"t":{"en":"Writing and Difference","zh":"《书写与差异》"},"y":1967}],"wiki":"Jacques Derrida"},
  {"id":"said","tradition":"continental","born":1935,"died":2003,"life":{"en":"1935–2003","zh":"1935–2003年"},"name":{"en":"Edward Said","zh":"爱德华·萨义德"},"role":{"en":"Palestinian-American literary critic at Columbia University","zh":"任教于哥伦比亚大学的巴勒斯坦裔美国文学批评家"},"idea":{"en":"Said argued that Western scholarship, art and policy created “the Orient” as an exotic, inferior Other, a body of knowledge that served imperial power and still shapes how the Middle East is seen.","zh":"萨义德认为，西方的学术、艺术与政策把“东方”塑造成一个异域而低劣的他者；这套知识服务于帝国权力，至今仍影响着人们看待中东的方式。"},"schools":["postcolonial"],"works":[{"t":{"en":"Orientalism","zh":"《东方学》"},"y":1978},{"t":{"en":"Culture and Imperialism","zh":"《文化与帝国主义》"},"y":1993}],"wiki":"Edward Said"},
  {"id":"spivak","tradition":"continental","born":1942,"died":null,"life":{"en":"born 1942","zh":"1942年生"},"name":{"en":"Gayatri Chakravorty Spivak","zh":"佳亚特里·查克拉沃蒂·斯皮瓦克"},"role":{"en":"Indian-born theorist and translator of Derrida, at Columbia University","zh":"生于印度的理论家、德里达的译者，任教于哥伦比亚大学"},"idea":{"en":"Spivak asked whether the subaltern, those shut out of power and representation, can speak: well-meaning intellectuals who claim to speak for them often silence them again.","zh":"斯皮瓦克追问：被排斥在权力与表述之外的底层人能否发声？那些自认为在替他们说话的好心知识分子，往往再次使他们沉默。"},"schools":["postcolonial"],"works":[{"t":{"en":"Can the Subaltern Speak?","zh":"《底层人能说话吗？》"},"y":1988},{"t":{"en":"A Critique of Postcolonial Reason","zh":"《后殖民理性批判》"},"y":1999}],"wiki":"Gayatri Chakravorty Spivak"},
  {"id":"butler","tradition":"continental","born":1956,"died":null,"life":{"en":"born 1956","zh":"1956年生"},"name":{"en":"Judith Butler","zh":"朱迪斯·巴特勒"},"role":{"en":"American philosopher at Berkeley, theorist of gender performativity","zh":"任教于加州大学伯克利分校的美国哲学家，提出性别述行理论"},"idea":{"en":"Butler argued that gender is not an inner essence that behaviour expresses but a performance repeated under social norms, which produces the appearance of a natural sex; norms can be subverted by repeating them differently.","zh":"巴特勒认为，性别并不是由行为表达出来的内在本质，而是在社会规范下不断重复的表演，正是这种重复制造出“自然性别”的表象；规范也可以通过“有差异的重复”被颠覆。"},"schools":["feminism"],"works":[{"t":{"en":"Gender Trouble","zh":"《性别麻烦》"},"y":1990},{"t":{"en":"Bodies That Matter","zh":"《身体之重》"},"y":1993}],"wiki":"Judith Butler"},
  {"id":"peirce","tradition":"analytic","born":1839,"died":1914,"life":{"en":"1839–1914","zh":"1839–1914年"},"name":{"en":"Charles Sanders Peirce","zh":"查尔斯·桑德斯·皮尔士"},"role":{"en":"Logician and scientist who founded pragmatism and semiotics","zh":"创立实用主义与符号学的逻辑学家与科学家"},"idea":{"en":"To make an idea clear, ask what practical effects its object could conceivably have; truth is the opinion that endless inquiry by a community of investigators would finally agree on.","zh":"要弄清一个观念，就问它的对象可设想地会产生哪些实际效果；真理是研究者共同体经过无尽探究最终会一致认同的意见。"},"schools":["pragmatism"],"works":[{"t":{"en":"The Fixation of Belief","zh":"《信念的确定》"},"y":1877},{"t":{"en":"How to Make Our Ideas Clear","zh":"《如何使我们的观念清晰》"},"y":1878}],"wiki":"Charles Sanders Peirce","c":"Charles Sanders Peirce.png","portrait":{"w":600,"h":900,"v":"f60e5e3100","author":"Charles_Sanders_Peirce_theb3558.jpg: NOAA Office of NOAA Corps Operations derivative work: Ori.livneh","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Charles_Sanders_Peirce.png"}},
  {"id":"james","tradition":"analytic","born":1842,"died":1910,"life":{"en":"1842–1910","zh":"1842–1910年"},"name":{"en":"William James","zh":"威廉·詹姆斯"},"role":{"en":"Psychologist and philosopher who made pragmatism famous","zh":"让实用主义广为人知的心理学家与哲学家"},"idea":{"en":"Truth is what works in the long run of experience, and we may sometimes have the right to believe ahead of the evidence; consciousness is a flowing “stream”, not a chain of separate ideas.","zh":"真理是在长远经验中行得通的东西，人有时有权在证据之前就去相信；意识是流动的“意识流”，而不是一串彼此分离的观念。"},"schools":["pragmatism"],"works":[{"t":{"en":"The Principles of Psychology","zh":"《心理学原理》"},"y":1890},{"t":{"en":"The Varieties of Religious Experience","zh":"《宗教经验种种》"},"y":1902},{"t":{"en":"Pragmatism","zh":"《实用主义》"},"y":1907}],"wiki":"William James","c":"William James b1842c.jpg","portrait":{"w":600,"h":800,"v":"f4783a8a05","author":"Notman Studios (photographer)","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:William_James_b1842c.jpg"}},
  {"id":"frege","tradition":"analytic","born":1848,"died":1925,"life":{"en":"1848–1925","zh":"1848–1925年"},"name":{"en":"Gottlob Frege","zh":"戈特洛布·弗雷格"},"role":{"en":"Jena mathematician who invented modern logic","zh":"创立现代逻辑的耶拿大学数学家"},"idea":{"en":"Arithmetic can be derived from logic, and expressions have both a sense (a way of presenting something) and a reference (the thing itself): “the morning star” and “the evening star” differ in sense but both refer to Venus.","zh":"算术可以从逻辑中推导出来；语言表达式既有涵义（呈现对象的方式），也有指称（对象本身）：“晨星”和“昏星”涵义不同，指称的却都是金星。"},"schools":["early-analytic"],"works":[{"t":{"en":"Begriffsschrift","zh":"《概念文字》"},"y":1879},{"t":{"en":"The Foundations of Arithmetic","zh":"《算术基础》"},"y":1884},{"t":{"en":"On Sense and Reference","zh":"《论涵义与指称》"},"y":1892}],"wiki":"Gottlob Frege","c":"Young frege.jpg","portrait":{"w":458,"h":619,"v":"8715113bd5","author":"Unknown author","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Young_frege.jpg"}},
  {"id":"dewey","tradition":"analytic","born":1859,"died":1952,"life":{"en":"1859–1952","zh":"1859–1952年"},"name":{"en":"John Dewey","zh":"约翰·杜威"},"role":{"en":"Philosopher of education and democracy; lectured in China 1919–21","zh":"教育与民主的哲学家，1919–1921年曾在中国讲学"},"idea":{"en":"Thinking is a tool for solving real problems, and democracy is not just a voting system but a way of life built on shared, experimental inquiry; schools should teach by doing.","zh":"思维是解决实际问题的工具；民主不只是投票制度，而是一种建立在共同、实验性探究之上的生活方式；学校应当“从做中学”。"},"schools":["pragmatism"],"works":[{"t":{"en":"Democracy and Education","zh":"《民主与教育》"},"y":1916},{"t":{"en":"Experience and Nature","zh":"《经验与自然》"},"y":1925},{"t":{"en":"The Quest for Certainty","zh":"《确定性的寻求》"},"y":1929}],"wiki":"John Dewey","c":"John Dewey cph.3a51565.jpg","portrait":{"w":600,"h":820,"v":"0631512579","author":"Underwood & Underwood","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:John_Dewey_cph.3a51565.jpg"}},
  {"id":"russell","tradition":"analytic","born":1872,"died":1970,"life":{"en":"1872–1970","zh":"1872–1970年"},"name":{"en":"Bertrand Russell","zh":"伯特兰·罗素"},"role":{"en":"Logician, public intellectual and Nobel laureate; lectured in China 1920–21","zh":"逻辑学家、公共知识分子、诺贝尔文学奖得主，1920–1921年曾在中国讲学"},"idea":{"en":"Logical analysis reveals what our sentences really assert, as in his theory of descriptions; he tried to found mathematics on logic and discovered the paradox that undermined Frege’s system.","zh":"逻辑分析能揭示句子真正断言的内容，摹状词理论即是一例；他试图把数学建立在逻辑之上，并发现了动摇弗雷格体系的“罗素悖论”。"},"schools":["early-analytic"],"works":[{"t":{"en":"On Denoting","zh":"《论指称》"},"y":1905},{"t":{"en":"Principia Mathematica (with A. N. Whitehead)","zh":"《数学原理》（与怀特海合著）"},"y":1910},{"t":{"en":"The Problems of Philosophy","zh":"《哲学问题》"},"y":1912}],"wiki":"Bertrand Russell"},
  {"id":"moore","tradition":"analytic","born":1873,"died":1958,"life":{"en":"1873–1958","zh":"1873–1958年"},"name":{"en":"G. E. Moore","zh":"G. E. 摩尔"},"role":{"en":"Cambridge defender of common sense against idealism","zh":"以常识对抗唯心论的剑桥哲学家"},"idea":{"en":"Goodness is a simple, indefinable property, so defining it as pleasure or any natural property commits the “naturalistic fallacy”; and we know common-sense truths, such as “here is a hand”, better than any philosophical argument against them.","zh":"“善”是一种简单而不可定义的性质，把它定义为快乐或任何自然性质，就犯了“自然主义谬误”；我们对“这里有一只手”这类常识真理的把握，比任何反对它们的哲学论证都更可靠。"},"schools":["early-analytic"],"works":[{"t":{"en":"Principia Ethica","zh":"《伦理学原理》"},"y":1903},{"t":{"en":"A Defence of Common Sense","zh":"《为常识辩护》"},"y":1925},{"t":{"en":"Proof of an External World","zh":"《外部世界的证明》"},"y":1939}],"wiki":"G. E. Moore"},
  {"id":"schlick","tradition":"analytic","born":1882,"died":1936,"life":{"en":"1882–1936","zh":"1882–1936年"},"name":{"en":"Moritz Schlick","zh":"莫里茨·石里克"},"role":{"en":"Physicist-philosopher who led the Vienna Circle","zh":"领导维也纳学派的物理学家兼哲学家"},"idea":{"en":"Philosophy is not a body of doctrines but the activity of clarifying meaning, and the meaning of a statement is the way it would be verified. He was shot dead by a former student at the University of Vienna in 1936.","zh":"哲学不是一套学说，而是澄清意义的活动；一个陈述的意义就在于它被证实的方式。1936年，他在维也纳大学被一名昔日学生枪杀。"},"schools":["logical-positivism"],"works":[{"t":{"en":"General Theory of Knowledge","zh":"《普通认识论》"},"y":1918},{"t":{"en":"The Turning Point in Philosophy","zh":"《哲学的转变》"},"y":1930}],"wiki":"Moritz Schlick"},
  {"id":"wittgenstein","tradition":"analytic","born":1889,"died":1951,"life":{"en":"1889–1951","zh":"1889–1951年"},"name":{"en":"Ludwig Wittgenstein","zh":"路德维希·维特根斯坦"},"role":{"en":"Viennese-born Cambridge philosopher who overturned his own first philosophy","zh":"生于维也纳、执教剑桥，推翻了自己早期哲学的哲学家"},"idea":{"en":"Early: a sentence pictures a possible fact, and what cannot be said must be passed over in silence. Late: meaning is use within “language-games” woven into forms of life, and philosophy is therapy for the bewitchment of our intelligence by language.","zh":"早期：命题是可能事实的图像，凡不可说的，必须保持沉默。后期：意义是词在交织于生活形式中的“语言游戏”里的用法，哲学是治疗语言对我们理智之蛊惑的疗法。"},"schools":["early-analytic","ordinary-language"],"works":[{"t":{"en":"Tractatus Logico-Philosophicus","zh":"《逻辑哲学论》"},"y":1921},{"t":{"en":"Philosophical Investigations (posthumous)","zh":"《哲学研究》（身后出版）"},"y":1953}],"wiki":"Ludwig Wittgenstein","c":"Ludwig Wittgenstein 1929.jpg","portrait":{"w":600,"h":812,"v":"82d2f37cce","author":"Moritz Nähr","license":"Public domain","licenseUrl":null,"page":"https://commons.wikimedia.org/wiki/File:Ludwig_Wittgenstein_1929.jpg"}},
  {"id":"carnap","tradition":"analytic","born":1891,"died":1970,"life":{"en":"1891–1970","zh":"1891–1970年"},"name":{"en":"Rudolf Carnap","zh":"鲁道夫·卡尔纳普"},"role":{"en":"Vienna Circle’s great system-builder, later in Chicago and Los Angeles","zh":"维也纳学派的体系建构者，后执教芝加哥与洛杉矶"},"idea":{"en":"Knowledge of the world can be logically reconstructed from experience, and questions like “do numbers really exist?” are not factual questions but choices of a linguistic framework, to be judged by their usefulness.","zh":"关于世界的知识可以从经验出发进行逻辑重构；“数真的存在吗”这类问题不是事实问题，而是对语言框架的选择，应以其有用性来评判。"},"schools":["logical-positivism"],"works":[{"t":{"en":"The Logical Structure of the World","zh":"《世界的逻辑构造》"},"y":1928},{"t":{"en":"The Logical Syntax of Language","zh":"《语言的逻辑句法》"},"y":1934},{"t":{"en":"Empiricism, Semantics, and Ontology","zh":"《经验主义、语义学和本体论》"},"y":1950}],"wiki":"Rudolf Carnap"},
  {"id":"ryle","tradition":"analytic","born":1900,"died":1976,"life":{"en":"1900–1976","zh":"1900–1976年"},"name":{"en":"Gilbert Ryle","zh":"吉尔伯特·赖尔"},"role":{"en":"Oxford philosopher who mocked the “ghost in the machine”","zh":"嘲讽“机器中的幽灵”的牛津哲学家"},"idea":{"en":"Treating the mind as a hidden inner thing is a “category mistake”, like looking for the university over and above its colleges; talk of minds is talk of abilities and dispositions to behave.","zh":"把心灵当作隐藏在内部的东西是一种“范畴错误”，就像在各个学院之外再去寻找“大学”本身；谈论心灵，就是谈论能力与行为倾向。"},"schools":["ordinary-language"],"works":[{"t":{"en":"The Concept of Mind","zh":"《心的概念》"},"y":1949},{"t":{"en":"Dilemmas","zh":"《两难》"},"y":1954}],"wiki":"Gilbert Ryle"},
  {"id":"popper","tradition":"analytic","born":1902,"died":1994,"life":{"en":"1902–1994","zh":"1902–1994年"},"name":{"en":"Karl Popper","zh":"卡尔·波普尔"},"role":{"en":"Viennese-born philosopher of science and defender of the open society","zh":"生于维也纳的科学哲学家、开放社会的捍卫者"},"idea":{"en":"A theory is scientific only if it could in principle be refuted by observation; knowledge grows by conjectures and refutations, and societies, like science, flourish when they stay open to criticism.","zh":"一个理论只有在原则上可能被观察推翻时才是科学的；知识通过猜想与反驳而增长，社会也像科学一样，只有保持对批评的开放才能繁荣。"},"schools":["post-positivism"],"works":[{"t":{"en":"The Logic of Scientific Discovery (Logik der Forschung)","zh":"《科学发现的逻辑》"},"y":1934},{"t":{"en":"The Open Society and Its Enemies","zh":"《开放社会及其敌人》"},"y":1945},{"t":{"en":"Conjectures and Refutations","zh":"《猜想与反驳》"},"y":1963}],"wiki":"Karl Popper"},
  {"id":"quine","tradition":"analytic","born":1908,"died":2000,"life":{"en":"1908–2000","zh":"1908–2000年"},"name":{"en":"W. V. O. Quine","zh":"W. V. O. 蒯因"},"role":{"en":"Harvard logician who attacked the analytic–synthetic distinction","zh":"抨击分析/综合二分的哈佛逻辑学家"},"idea":{"en":"There is no sharp line between truths of meaning and truths of fact; our beliefs form a single web that faces experience as a whole, and philosophy is continuous with natural science.","zh":"意义之真与事实之真之间没有截然的界线；我们的信念构成一张整体之网，作为整体面对经验，哲学与自然科学是连续的。"},"schools":["post-positivism"],"works":[{"t":{"en":"Two Dogmas of Empiricism","zh":"《经验论的两个教条》"},"y":1951},{"t":{"en":"Word and Object","zh":"《语词和对象》"},"y":1960}],"wiki":"Willard Van Orman Quine"},
  {"id":"ayer","tradition":"analytic","born":1910,"died":1989,"life":{"en":"1910–1989","zh":"1910–1989年"},"name":{"en":"A. J. Ayer","zh":"A. J. 艾耶尔"},"role":{"en":"Oxford philosopher who brought logical positivism to English readers","zh":"把逻辑实证主义带给英语读者的牛津哲学家"},"idea":{"en":"A statement is meaningful only if it is analytic or empirically verifiable; moral judgements are neither, so they express feelings of approval or disapproval rather than facts (emotivism).","zh":"陈述只有是分析的或可经验证实的才有意义；道德判断两者都不是，所以它表达的是赞成或反对的情感，而非事实（情感主义）。"},"schools":["logical-positivism"],"works":[{"t":{"en":"Language, Truth and Logic","zh":"《语言、真理与逻辑》"},"y":1936},{"t":{"en":"The Problem of Knowledge","zh":"《知识问题》"},"y":1956}],"wiki":"A. J. Ayer"},
  {"id":"austin","tradition":"analytic","born":1911,"died":1960,"life":{"en":"1911–1960","zh":"1911–1960年"},"name":{"en":"J. L. Austin","zh":"J. L. 奥斯汀"},"role":{"en":"Oxford philosopher of language who founded speech-act theory","zh":"开创言语行为理论的牛津语言哲学家"},"idea":{"en":"Many utterances do not describe anything but perform an act: saying “I promise” or “I do” at a wedding is making a promise or getting married. Careful study of ordinary words is the best starting point for philosophy.","zh":"许多话语并不描述什么，而是在做事：说“我保证”，或在婚礼上说“我愿意”，就是在许诺、在结婚。仔细研究日常词语，是哲学最好的起点。"},"schools":["ordinary-language"],"works":[{"t":{"en":"How to Do Things with Words (lectures of 1955, posthumous)","zh":"《如何以言行事》（1955年讲稿，身后出版）"},"y":1962},{"t":{"en":"Sense and Sensibilia (posthumous)","zh":"《感觉与可感物》（身后出版）"},"y":1962}],"wiki":"J. L. Austin"},
  {"id":"anscombe","tradition":"analytic","born":1919,"died":2001,"life":{"en":"1919–2001","zh":"1919–2001年"},"name":{"en":"G. E. M. Anscombe","zh":"伊丽莎白·安斯康姆"},"role":{"en":"Wittgenstein’s student and translator who relaunched virtue ethics","zh":"维特根斯坦的学生与译者，重启美德伦理学"},"idea":{"en":"Modern moral philosophy uses a “moral ought” cut off from the divine-law framework that once gave it sense; we should first develop a philosophy of psychology, of action, intention and virtue.","zh":"现代道德哲学使用的“道德应当”，已经脱离了曾经赋予它意义的神圣律法框架；我们应当先发展一套关于行动、意向与美德的心理学哲学。"},"schools":["virtue-ethics"],"works":[{"t":{"en":"Intention","zh":"《意向》"},"y":1957},{"t":{"en":"Modern Moral Philosophy","zh":"《现代道德哲学》"},"y":1958}],"wiki":"G. E. M. Anscombe"},
  {"id":"foot","tradition":"analytic","born":1920,"died":2010,"life":{"en":"1920–2010","zh":"1920–2010年"},"name":{"en":"Philippa Foot","zh":"菲利帕·富特"},"role":{"en":"Oxford moral philosopher who devised the trolley problem","zh":"提出“电车难题”的牛津道德哲学家"},"idea":{"en":"Moral goodness is a kind of natural goodness: just as a plant or animal can be a good or defective specimen of its kind, human virtues are what human beings need to live well.","zh":"道德之善是一种自然之善：正如植物或动物可以是其种类中良好或有缺陷的个体，人的美德就是人要活得好所需要的东西。"},"schools":["virtue-ethics"],"works":[{"t":{"en":"The Problem of Abortion and the Doctrine of the Double Effect","zh":"《堕胎问题与双重效应原则》"},"y":1967},{"t":{"en":"Virtues and Vices","zh":"《美德与恶行》"},"y":1978},{"t":{"en":"Natural Goodness","zh":"《自然的善》"},"y":2001}],"wiki":"Philippa Foot"},
  {"id":"rawls","tradition":"analytic","born":1921,"died":2002,"life":{"en":"1921–2002","zh":"1921–2002年"},"name":{"en":"John Rawls","zh":"约翰·罗尔斯"},"role":{"en":"Harvard philosopher who revived political philosophy with justice as fairness","zh":"以“作为公平的正义”复兴政治哲学的哈佛哲学家"},"idea":{"en":"Principles of justice are those free and equal people would choose behind a veil of ignorance: equal basic liberties for all, and social and economic inequalities only if they benefit the least advantaged.","zh":"正义原则是自由平等的人在无知之幕后会选择的原则：人人享有平等的基本自由；社会和经济的不平等只有在有利于最不利者时才被允许。"},"schools":["liberal-egalitarianism"],"works":[{"t":{"en":"A Theory of Justice","zh":"《正义论》"},"y":1971},{"t":{"en":"Political Liberalism","zh":"《政治自由主义》"},"y":1993}],"wiki":"John Rawls"},
  {"id":"kuhn","tradition":"analytic","born":1922,"died":1996,"life":{"en":"1922–1996","zh":"1922–1996年"},"name":{"en":"Thomas Kuhn","zh":"托马斯·库恩"},"role":{"en":"Physicist turned historian of science who coined “paradigm shift”","zh":"由物理学家转为科学史家，提出“范式转换”"},"idea":{"en":"Science mostly proceeds as “normal science” within a shared paradigm; when anomalies accumulate, a revolution installs a new paradigm that cannot be judged simply by the standards of the old.","zh":"科学大多以“常规科学”的形式在共享的范式内进行；当反常不断积累，一场革命便确立新范式，而新旧范式之间无法简单地用同一套标准衡量。"},"schools":["post-positivism"],"works":[{"t":{"en":"The Copernican Revolution","zh":"《哥白尼革命》"},"y":1957},{"t":{"en":"The Structure of Scientific Revolutions","zh":"《科学革命的结构》"},"y":1962}],"wiki":"Thomas Kuhn"},
  {"id":"putnam","tradition":"analytic","born":1926,"died":2016,"life":{"en":"1926–2016","zh":"1926–2016年"},"name":{"en":"Hilary Putnam","zh":"希拉里·普特南"},"role":{"en":"Harvard philosopher who launched functionalism, then criticised it","zh":"提出功能主义、后来又批判它的哈佛哲学家"},"idea":{"en":"Mental states are functional states that could be realised in many materials; and “meanings just ain’t in the head”: what our words refer to depends on the world. He later turned against functionalism and toward pragmatism.","zh":"心理状态是可以由多种材料实现的功能状态；而且“意义不在头脑之中”：词语指称什么取决于世界本身。他后来转而反对功能主义，走向实用主义。"},"schools":["philosophy-of-mind"],"works":[{"t":{"en":"Psychological Predicates","zh":"《心理谓词》"},"y":1967},{"t":{"en":"The Meaning of “Meaning”","zh":"《“意义”的意义》"},"y":1975},{"t":{"en":"Reason, Truth and History","zh":"《理性、真理与历史》"},"y":1981}],"wiki":"Hilary Putnam"},
  {"id":"macintyre","tradition":"analytic","born":1929,"died":2025,"life":{"en":"1929–2025","zh":"1929–2025年"},"name":{"en":"Alasdair MacIntyre","zh":"阿拉斯戴尔·麦金太尔"},"role":{"en":"Scottish-born philosopher who moved from Marxism to Thomism","zh":"生于苏格兰、由马克思主义转向托马斯主义的哲学家"},"idea":{"en":"Modern moral debate is interminable because it uses fragments of older traditions without their context; virtues make sense only within practices, the narrative unity of a life, and a living tradition.","zh":"现代道德争论之所以永无止境，是因为它使用的是脱离了原有语境的旧传统碎片；美德只有在实践、生命的叙事统一性和活的传统之中才有意义。"},"schools":["virtue-ethics"],"works":[{"t":{"en":"After Virtue","zh":"《追寻美德》"},"y":1981},{"t":{"en":"Whose Justice? Which Rationality?","zh":"《谁之正义？何种合理性？》"},"y":1988}],"wiki":"Alasdair MacIntyre"},
  {"id":"rorty","tradition":"analytic","born":1931,"died":2007,"life":{"en":"1931–2007","zh":"1931–2007年"},"name":{"en":"Richard Rorty","zh":"理查德·罗蒂"},"role":{"en":"Neopragmatist who challenged philosophy’s claim to mirror reality","zh":"质疑哲学能“映照”实在的新实用主义者"},"idea":{"en":"The mind is not a mirror of nature and philosophy cannot ground knowledge from outside our practices; we should aim at solidarity and less cruelty rather than at certainty.","zh":"心灵不是自然之镜，哲学也无法从我们的实践之外为知识奠基；我们应当追求团结、减少残忍，而不是追求确定性。"},"schools":["pragmatism"],"works":[{"t":{"en":"Philosophy and the Mirror of Nature","zh":"《哲学和自然之镜》"},"y":1979},{"t":{"en":"Contingency, Irony, and Solidarity","zh":"《偶然、反讽与团结》"},"y":1989}],"wiki":"Richard Rorty"},
  {"id":"searle","tradition":"analytic","born":1932,"died":null,"life":{"en":"born 1932","zh":"1932年生"},"name":{"en":"John Searle","zh":"约翰·塞尔"},"role":{"en":"Berkeley philosopher of language and mind, author of the Chinese Room","zh":"伯克利的语言与心灵哲学家，“中文屋”论证的提出者"},"idea":{"en":"A person who follows rules to shuffle Chinese symbols could answer questions in Chinese without understanding a word, so running a program is not the same as having a mind; understanding depends on the causal powers of brains.","zh":"一个按规则摆弄中文符号的人，可以用中文回答问题却一个字也不懂；所以运行程序并不等于拥有心灵，理解取决于大脑的因果能力。"},"schools":["philosophy-of-mind"],"works":[{"t":{"en":"Speech Acts","zh":"《言语行为》"},"y":1969},{"t":{"en":"Minds, Brains, and Programs","zh":"《心灵、大脑与程序》"},"y":1980},{"t":{"en":"The Rediscovery of the Mind","zh":"《心灵的再发现》"},"y":1992}],"wiki":"John Searle"},
  {"id":"nagel","tradition":"analytic","born":1937,"died":null,"life":{"en":"born 1937","zh":"1937年生"},"name":{"en":"Thomas Nagel","zh":"托马斯·内格尔"},"role":{"en":"NYU philosopher who asked what it is like to be a bat","zh":"追问“成为一只蝙蝠是什么样子”的纽约大学哲学家"},"idea":{"en":"An organism is conscious if there is something it is like to be it; this subjective point of view cannot be captured by any objective, physical description, the “view from nowhere”.","zh":"如果“成为某个生物”是某种样子，那么它就有意识；这种主观视角无法被任何客观的物理描述——“本然的观点”——所捕捉。"},"schools":["philosophy-of-mind"],"works":[{"t":{"en":"What Is It Like to Be a Bat?","zh":"《成为一只蝙蝠可能是什么样子？》"},"y":1974},{"t":{"en":"The View from Nowhere","zh":"《本然的观点》"},"y":1986},{"t":{"en":"Mind and Cosmos","zh":"《心灵与宇宙》"},"y":2012}],"wiki":"Thomas Nagel"},
  {"id":"nozick","tradition":"analytic","born":1938,"died":2002,"life":{"en":"1938–2002","zh":"1938–2002年"},"name":{"en":"Robert Nozick","zh":"罗伯特·诺齐克"},"role":{"en":"Harvard libertarian who answered Rawls","zh":"回应罗尔斯的哈佛自由至上主义者"},"idea":{"en":"Individuals have rights that set strict limits on what the state may do; a distribution is just if it arose from just acquisition and free exchange, whatever pattern results, so only a minimal state is justified.","zh":"个人拥有严格限定国家行为的权利；只要一种分配源于正当的获取和自由的交换，不论结果呈现什么样的模式，它就是正义的，因此只有“最小国家”才是正当的。"},"schools":["liberal-egalitarianism"],"works":[{"t":{"en":"Anarchy, State, and Utopia","zh":"《无政府、国家和乌托邦》"},"y":1974},{"t":{"en":"Philosophical Explanations","zh":"《哲学解释》"},"y":1981}],"wiki":"Robert Nozick"},
  {"id":"dennett","tradition":"analytic","born":1942,"died":2024,"life":{"en":"1942–2024","zh":"1942–2024年"},"name":{"en":"Daniel Dennett","zh":"丹尼尔·丹尼特"},"role":{"en":"Tufts philosopher who explained consciousness as the brain’s work","zh":"试图用大脑的运作解释意识的塔夫茨大学哲学家"},"idea":{"en":"There is no inner theatre where experience comes together; consciousness is many parallel processes in the brain, and the sense of an extra “hard problem” is a powerful illusion. Evolution by natural selection explains design without a designer.","zh":"大脑中并没有一个汇聚经验的“内在剧场”；意识是大脑中许多并行的过程，而觉得还剩下一个“难问题”，是一种强有力的错觉。自然选择的演化能够解释没有设计者的设计。"},"schools":["philosophy-of-mind"],"works":[{"t":{"en":"Consciousness Explained","zh":"《意识的解释》"},"y":1991},{"t":{"en":"Darwin’s Dangerous Idea","zh":"《达尔文的危险观念》"},"y":1995}],"wiki":"Daniel Dennett"},
  {"id":"singer","tradition":"analytic","born":1946,"died":null,"life":{"en":"born 1946","zh":"1946年生"},"name":{"en":"Peter Singer","zh":"彼得·辛格"},"role":{"en":"Australian utilitarian of animal liberation and effective giving","zh":"倡导动物解放与有效利他的澳大利亚功利主义者"},"idea":{"en":"Equal interests deserve equal consideration whoever has them, so the suffering of animals counts, and if we can prevent something very bad without sacrificing anything of comparable importance, we ought to do it.","zh":"同等的利益应得到同等的考虑，不论它属于谁，所以动物的痛苦同样重要；如果我们能在不牺牲同等重要之物的前提下阻止非常糟糕的事，就应当去做。"},"schools":["utilitarianism"],"works":[{"t":{"en":"Famine, Affluence, and Morality","zh":"《饥荒、富裕与道德》"},"y":1972},{"t":{"en":"Animal Liberation","zh":"《动物解放》"},"y":1975},{"t":{"en":"Practical Ethics","zh":"《实践伦理学》"},"y":1979}],"wiki":"Peter Singer"},
  {"id":"nussbaum","tradition":"analytic","born":1947,"died":null,"life":{"en":"born 1947","zh":"1947年生"},"name":{"en":"Martha Nussbaum","zh":"玛莎·努斯鲍姆"},"role":{"en":"Chicago philosopher of the capabilities approach and the emotions","zh":"芝加哥大学哲学家，倡导能力进路、研究情感"},"idea":{"en":"Justice should secure for every person a threshold of central capabilities, such as health, education, play and political voice; drawing on Aristotle and the Greek tragedians, she argues that emotions and vulnerability belong to ethics.","zh":"正义应当保障每个人都达到一系列核心能力的门槛，如健康、教育、游戏与政治发言权；她借鉴亚里士多德和希腊悲剧，主张情感与脆弱性本就属于伦理学。"},"schools":["liberal-egalitarianism"],"works":[{"t":{"en":"The Fragility of Goodness","zh":"《善的脆弱性》"},"y":1986},{"t":{"en":"Frontiers of Justice","zh":"《正义的前沿》"},"y":2006},{"t":{"en":"Creating Capabilities","zh":"《寻求有尊严的生活：正义的能力理论》"},"y":2011}],"wiki":"Martha Nussbaum"},
  {"id":"chalmers","tradition":"analytic","born":1966,"died":null,"life":{"en":"born 1966","zh":"1966年生"},"name":{"en":"David Chalmers","zh":"大卫·查默斯"},"role":{"en":"Australian philosopher who named the “hard problem” of consciousness","zh":"提出意识“难问题”的澳大利亚哲学家"},"idea":{"en":"Explaining the brain’s functions (the “easy problems”) leaves open why any of it is accompanied by experience at all; since a physical duplicate without experience seems conceivable, consciousness may need new fundamental laws.","zh":"解释大脑的种种功能（“易问题”）之后，仍然留下一个问题：为什么这一切会伴随着经验？既然一个没有经验的物理复制品似乎是可设想的，意识或许需要新的基本定律来解释。"},"schools":["philosophy-of-mind"],"works":[{"t":{"en":"Facing Up to the Problem of Consciousness","zh":"《直面意识问题》"},"y":1995},{"t":{"en":"The Conscious Mind","zh":"《有意识的心灵》"},"y":1996},{"t":{"en":"Reality+","zh":"《现实+》"},"y":2022}],"wiki":"David Chalmers"}
];
